  drops=(c)=>`<g stroke="${c}" stroke-width="1.6" stroke-linecap="round"><line x1="10" y1="24" x2="9" y2="27"/><line x1="14" y1="24" x2="13" y2="27"/><line x1="18" y1="24" x2="17" y2="27"/></g>`;
  let b="";
