function wxDay(a){const lo=a?N(a[2].pos_long):null;const hl=((new Date().getUTCHours()+new Date().getUTCMinutes()/60+(lo||0)/15)%24+24)%24;return hl>=6.5&&hl<18.5}
const BASEWX={icao:"KSFO",name:"San Francisco Intl",elev:"13",lat:"37.6189",lon:"-122.375",at:0,metar:"",taf:"",busy:false};
function baseWxLoad(){if(BASEWX.busy||!vam.url||Date.now()-BASEWX.at<10*60000)return;BASEWX.busy=true;
  vamGet("/api/efb/airport?icao="+BASEWX.icao,15000).then(j=>{BASEWX.metar=(j&&j.metar&&j.metar.raw)||"";BASEWX.taf=(j&&j.taf&&j.taf.raw)||"";BASEWX.at=BASEWX.metar?Date.now():Date.now()-9*60000;if(ofp._sample&&(cur==="wx"||!cur))render()})
    .catch(()=>{BASEWX.at=Date.now()-8*60000}).finally(()=>{BASEWX.busy=false})}
function wxFor(x){if(ofp._sample){baseWxLoad();return[[AL().base,"BASE",{icao_code:BASEWX.icao,name:BASEWX.name,elevation:BASEWX.elev,pos_lat:BASEWX.lat,pos_long:BASEWX.lon},BASEWX.metar||(typeof FCW!=="undefined"&&FCW.taf[BASEWX.icao]&&FCW.taf[BASEWX.icao].metar)||"",BASEWX.taf||(typeof FCW!=="undefined"&&FCW.taf[BASEWX.icao]&&FCW.taf[BASEWX.icao].raw)||""]]}return wxFor0(x)}
function wxFor0(x){const w=x.w;const pick=(...k)=>{for(const v of k){if(S(v))return S(v)}return""};
  return [["Departure","DEP",x.o,pick(w.orig_metar,x.o.metar),pick(w.orig_taf,x.o.taf)],["Destination","DEST",x.d,pick(w.dest_metar,x.d.metar),pick(w.dest_taf,x.d.taf)],["Alternate","ALTN",x.a,pick(w.altn_metar,x.a.metar),pick(w.altn_taf,x.a.taf)]].filter(a=>S(a[2].icao_code))}

/* METAR */
function decodeMetar(raw){
  raw=S(raw);if(!raw)return null;
  const t=raw.split(/\s+/);const r={raw,wind:null,visSM:null,clouds:[],temp:null,dew:null,alt:null,wx:[]};
  for(let i=1;i<t.length;i++){const s=t[i];if(s==="RMK"||s==="TEMPO"||s==="BECMG")break;let m;
    if((m=s.match(/^(\d{3}|VRB)(\d{2,3})(?:G(\d{2,3}))?(KT|MPS)$/))){const k=m[4]==="MPS"?1.944:1;r.wind={dir:m[1]==="VRB"?null:+m[1],spd:Math.round(+m[2]*k),gust:m[3]?Math.round(+m[3]*k):null}}
    else if(s==="CAVOK"){r.visSM=10}
    else if((m=s.match(/^P?(\d+)SM$/)))r.visSM=+m[1];
    else if((m=s.match(/^M?(\d+)\/(\d+)SM$/))){let v=+m[1]/+m[2];if(/^\d$/.test(t[i-1]))v+=+t[i-1];r.visSM=v}
    else if((m=s.match(/^(\d{4})$/))&&r.visSM==null&&i<5)r.visSM=+m[1]/1609;
    else if((m=s.match(/^(FEW|SCT|BKN|OVC|VV)(\d{3})/)))r.clouds.push({c:m[1],h:+m[2]*100});
    else if((m=s.match(/^(M?\d{2})\/(M?\d{2})?$/))){r.temp=+m[1].replace("M","-");r.dew=m[2]?+m[2].replace("M","-"):null}
    else if((m=s.match(/^A(\d{4})$/)))r.alt={inhg:+m[1]/100,hpa:Math.round(+m[1]/100*33.8639)};
    else if((m=s.match(/^Q(\d{4})$/)))r.alt={hpa:+m[1],inhg:+(+m[1]/33.8639).toFixed(2)};
    else if(/^(-|\+|VC)?(TS|SH|FZ|MI|BC|DR|BL)?(RA|SN|DZ|GR|GS|PL|SG|IC|BR|FG|HZ|FU|SA|DU|SQ|FC|UP)+$/.test(s))r.wx.push(s);}
  const ceil=r.clouds.filter(c=>/BKN|OVC|VV/.test(c.c)).map(c=>c.h);r.ceiling=ceil.length?Math.min(...ceil):null;
  const v=r.visSM==null?10:r.visSM,c=r.ceiling==null?99999:r.ceiling;
  r.cat=(c<500||v<1)?"LIFR":(c<1000||v<3)?"IFR":(c<=3000||v<=5)?"MVFR":"VFR";
  return r;
}
function rwyHdg(rwy){const m=S(rwy).match(/^(\d{1,2})/);return m?(+m[1]*10||360):null}
function components(wdir,wspd,hdg){const a=(wdir-hdg)*Math.PI/180;return{hw:Math.round(wspd*Math.cos(a)),xw:Math.round(wspd*Math.sin(a))}}
const WX_WORDS={RA:"rain",SN:"snow",DZ:"drizzle",BR:"mist",FG:"fog",HZ:"haze",TS:"thunderstorm",SH:"showers",FZ:"freezing",GR:"hail"};
function wxWords(list){return list.map(s=>{let p=s.startsWith("-")?"light ":s.startsWith("+")?"heavy ":"";s=s.replace(/^[-+]/,"");const out=[];for(let i=0;i<s.length;i+=2)out.push(WX_WORDS[s.substr(i,2)]||s.substr(i,2));return p+out.join(" ")}).join(", ")}
function condText(m){if(!m)return"—";if(m.wx.length){const w=wxWords(m.wx);return w.charAt(0).toUpperCase()+w.slice(1)}
  if(m.ceiling!=null)return m.ceiling<1000?"Low cloud":"Cloudy";if(m.clouds.length)return "Partly cloudy";return "Clear"}
const windTxt=w=>w?(w.dir==null?"VRB":pad(w.dir).padStart(3,"0"))+"/"+pad(w.spd)+(w.gust?"G"+w.gust:""):"—";

/* checklists */
