/* timer */
let tmr=store.get("timer",{start:null,acc:0,laps:[]});if(!tmr.laps)tmr.laps=[];
let cd=store.get("cd",{dur:300,end:null,remain:null});
let clockTab=store.get("clockTab","world"),actx=null;
const swMs=()=>tmr.acc+(tmr.start?Date.now()-tmr.start:0);
function swFmt(ms){const cs=Math.floor(ms/10)%100,t=Math.floor(ms/1000),h=Math.floor(t/3600),m=Math.floor(t%3600/60),sc=t%60;return (h?h+":"+pad(m):pad(m))+":"+pad(sc)+"."+pad(cs)}
const cdLeft=()=>cd.end!=null?Math.max(0,(cd.end-Date.now())/1000):cd.remain;
function cdFmt(t){t=Math.ceil(t);const h=Math.floor(t/3600),m=Math.floor(t%3600/60),sc=t%60;return (h?h+":"+pad(m):pad(m))+":"+pad(sc)}
function beep(){if(!actx)return;try{const t0=actx.currentTime;[0,.35,.7].forEach(dt=>{const o=actx.createOscillator(),g=actx.createGain();o.frequency.value=880;o.connect(g);g.connect(actx.destination);g.gain.setValueAtTime(.0001,t0+dt);g.gain.exponentialRampToValueAtTime(.3,t0+dt+.02);g.gain.exponentialRampToValueAtTime(.0001,t0+dt+.25);o.start(t0+dt);o.stop(t0+dt+.3)})}catch(e){}}
function cdCheck(){if(cd.end!=null&&Date.now()>=cd.end){cd.end=null;cd.remain=null;store.set("cd",cd);beep();toast("Timer done");if(cur==="timer")render()}}
let swRaf=0;
function swLoop(){swRaf=0;if(cur!=="timer"||clockTab!=="sw")return;const d=$("#swDig");if(!d)return;const ms=swMs();d.textContent=swFmt(ms);const c=$("#swCur");if(c)c.textContent=swFmt(ms-(tmr.laps[tmr.laps.length-1]||0));if(tmr.start)swRaf=requestAnimationFrame(swLoop)}
function updateTimer(){if(cur!=="timer")return;
  if(clockTab==="world"){const l=$("#wcList");if(l)l.innerHTML=worldRows()}
  if(clockTab==="sw"&&!swRaf)swLoop();
  if(clockTab==="cd"&&(cd.end!=null||cd.remain!=null)){const t=cdLeft(),dg=$("#cdDig"),r=$("#cdArc");if(dg)dg.textContent=cdFmt(t);if(r)r.setAttribute("stroke-dashoffset",String(283*(1-t/Math.max(1,cd.total||cd.dur))))}}
const LOCAL_TZ=(Intl.DateTimeFormat().resolvedOptions().timeZone)||"UTC";
const ICAO_TZ={KSFO:"America/Los_Angeles",KSEA:"America/Los_Angeles",KPDX:"America/Los_Angeles",KLAX:"America/Los_Angeles",KSAN:"America/Los_Angeles",KSJC:"America/Los_Angeles",KOAK:"America/Los_Angeles",KLAS:"America/Los_Angeles",KPHX:"America/Phoenix",KDEN:"America/Denver",KSLC:"America/Denver",KORD:"America/Chicago",KDFW:"America/Chicago",KIAH:"America/Chicago",KMSP:"America/Chicago",KATL:"America/New_York",KJFK:"America/New_York",KEWR:"America/New_York",KBOS:"America/New_York",KIAD:"America/New_York",KMIA:"America/New_York",KDTW:"America/Detroit",PHNL:"Pacific/Honolulu",PHOG:"Pacific/Honolulu",PANC:"America/Anchorage",CYVR:"America/Vancouver",CYYZ:"America/Toronto",MMMX:"America/Mexico_City",RCTP:"Asia/Taipei",RCSS:"Asia/Taipei",RCKH:"Asia/Taipei",RJAA:"Asia/Tokyo",RJTT:"Asia/Tokyo",RJBB:"Asia/Tokyo",RKSI:"Asia/Seoul",VHHH:"Asia/Hong_Kong",VMMC:"Asia/Macau",ZSPD:"Asia/Shanghai",ZBAA:"Asia/Shanghai",WSSS:"Asia/Singapore",VTBS:"Asia/Bangkok",RPLL:"Asia/Manila",WMKK:"Asia/Kuala_Lumpur",YSSY:"Australia/Sydney",YMML:"Australia/Melbourne",NZAA:"Pacific/Auckland",OMDB:"Asia/Dubai",OTHH:"Asia/Qatar",VIDP:"Asia/Kolkata",EGLL:"Europe/London",LFPG:"Europe/Paris",EDDF:"Europe/Berlin",EDDM:"Europe/Berlin",EHAM:"Europe/Amsterdam",LEMD:"Europe/Madrid",LIRF:"Europe/Rome",LSZH:"Europe/Zurich",EIDW:"Europe/Dublin"};
function aptTz(a){const i=S(a.icao_code).toUpperCase();if(ICAO_TZ[i])return ICAO_TZ[i];const tz=S(a.timezone);if(/^[A-Za-z]+\/[A-Za-z_\/]+$/.test(tz))return tz;const n=parseFloat(tz);if(isFinite(n)&&Number.isInteger(n)&&Math.abs(n)<=14)return "Etc/GMT"+(n<=0?"+":"-")+Math.abs(n);return null}
function tzP(tz,d){try{const o={};new Intl.DateTimeFormat("en-US",{timeZone:tz,hourCycle:"h23",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit"}).formatToParts(d).forEach(p=>o[p.type]=p.value);return{y:+o.year,mo:+o.month,d:+o.day,h:+o.hour%24,m:+o.minute,s:+o.second}}catch(e){return null}}
const tzOff=(p,d)=>Math.round((Date.UTC(p.y,p.mo-1,p.d,p.h,p.m)-Math.floor(d.getTime()/60000)*60000)/60000);
function miniClock(p){const night=p.h<6||p.h>=18,face=night?"#1C1C1E":"#FFFFFF",ink=night?"#FFFFFF":"#000000";let t="";for(let i=0;i<12;i++){const a=i*30*Math.PI/180;t+=`<line x1="${28+Math.sin(a)*21}" y1="${28-Math.cos(a)*21}" x2="${28+Math.sin(a)*24}" y2="${28-Math.cos(a)*24}" stroke="${ink}" stroke-opacity=".6" stroke-width="1.2"/>`}
  return `<svg viewBox="0 0 56 56" aria-hidden="true"><circle cx="28" cy="28" r="27" fill="${face}" stroke="var(--ck-line)"/>${t}<line x1="28" y1="28" x2="28" y2="15" stroke="${ink}" stroke-width="2.6" stroke-linecap="round" transform="rotate(${(p.h%12)*30+p.m*.5} 28 28)"/><line x1="28" y1="28" x2="28" y2="8" stroke="${ink}" stroke-width="1.8" stroke-linecap="round" transform="rotate(${p.m*6} 28 28)"/><line x1="28" y1="31" x2="28" y2="7" stroke="#FF9500" stroke-width=".9" transform="rotate(${p.s*6} 28 28)"/><circle cx="28" cy="28" r="1.8" fill="#FF9500"/></svg>`}
function worldRows(){const d=new Date(),x=O(),lp=tzP(LOCAL_TZ,d),lo=tzOff(lp,d);
  const rows=[["UTC","Coordinated Universal Time","UTC"],["Local",LOCAL_TZ.replace(/_/g," "),LOCAL_TZ],[S(x.o.icao_code),"Departure · "+S(x.o.name),aptTz(x.o)],[S(x.d.icao_code),"Destination · "+S(x.d.name),aptTz(x.d)],[S(x.a.icao_code),"Alternate · "+S(x.a.name),aptTz(x.a)]].filter(r=>r[0]&&r[2]);
  return rows.map(r=>{const p=tzP(r[2],d);if(!p)return"";const diff=tzOff(p,d)-lo;const dd=Date.UTC(p.y,p.mo-1,p.d)-Date.UTC(lp.y,lp.mo-1,lp.d);const day=dd>0?"Tomorrow":dd<0?"Yesterday":"Today";
    const ah=Math.abs(diff);const off=(diff<0?"−":"+")+Math.floor(ah/60)+(ah%60?":"+pad(ah%60):"")+"HRS";
    return `<div class="wc-row">${miniClock(p)}<span><span class="wc-sub">${day}, ${off}</span><b>${esc(r[0])}</b><span class="wc-sub2">${esc(r[1])}</span></span><span class="wc-time">${pad(p.h)}:${pad(p.m)}</span></div>`}).join("")}
function lapsHtml(){const L=tmr.laps,ms=swMs();if(!L.length&&!ms)return"";const durs=L.map((v,i)=>v-(L[i-1]||0));let best=-1,worst=-1;
  if(durs.length>=2){best=durs.indexOf(Math.min(...durs));worst=durs.indexOf(Math.max(...durs))}
  let h=`<div class="lap"><span>Lap ${L.length+1}</span><span id="swCur">${swFmt(ms-(L[L.length-1]||0))}</span></div>`;
  for(let i=durs.length-1;i>=0;i--)h+=`<div class="lap${i===best?" best":i===worst?" worst":""}"><span>Lap ${i+1}</span><span>${swFmt(durs[i])}</span></div>`;return h}

