/* ===== Live checklist push: vAMSYS flight phase → the normal checklist due now ===== */
const CLP={on:store.get("clAuto",true)!==false,notify:!!store.get("clNotify",false),flight:null,phase:"",why:"",idx:null,at:0,err:null,loading:false,pushed:store.get("clPushed",{})};
const nmDist=(a,b)=>{if(a[0]==null||b[0]==null)return null;const r=Math.PI/180,dl=(b[0]-a[0])*r,dn=(b[1]-a[1])*r;const h=Math.sin(dl/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin(dn/2)**2;return 2*3440.065*Math.asin(Math.sqrt(h))};
const CL_GROUPS=[["Cockpit preparation","Before start","After start","Taxi","Before takeoff"],["After takeoff / climb"],["Approach","Landing"],["After landing","Parking","Securing the aircraft"]];
/* Work out which checklist the flight is at, from the vAMSYS phase text first, then from position, speed and altitude. */
function clPhase(f){const x=O(),p=String(f.phase||"").toLowerCase().replace(/[_-]+/g," ");
  const pos=[f.lat,f.lon],dDep=nmDist(pos,[N(x.o.pos_lat),N(x.o.pos_long)]),dArr=nmDist(pos,[N(x.d.pos_lat),N(x.d.pos_long)]);
  const total=N(x.g.route_distance)||N(x.g.air_distance)||(dDep!=null&&dArr!=null?dDep+dArr:null);
  const remain=f.distanceRemaining!=null?f.distanceRemaining:dArr;const nearArr=(dArr!=null&&dArr<20)||(remain!=null&&remain<20&&(dDep==null||dDep>20));
  const gs=f.groundspeed||0,agl=(f.altitude||0)-(nearArr?(N(x.d.elevation)||0):(N(x.o.elevation)||0)),ground=gs<50&&agl<200;
  const R=(s,why)=>({sec:s,why});
  if(p){
    if(/arriv|on ?block|deboard|complet|finish|shut ?down|parked/.test(p)&&(nearArr||ground))return R("Parking","Arrived at the gate");
    if(/board|pre ?flight|initiali|loading|gate|not started|ready/.test(p)&&!nearArr)return R("Before start","Boarding");
    if(/push/.test(p))return R("After start","Pushback & engine start");
    if(/taxi/.test(p))return /in/.test(p)||nearArr?R("After landing","Taxi in"):R("Taxi","Taxi out");
    if(/landed|roll ?out|after land/.test(p))return R("After landing","Landed");
    if(/final|landing|short final/.test(p))return R("Landing","Final approach");
    if(/descen|approach|star/.test(p))return R("Approach","Descent / approach");
    if(/take ?off|depart|climb|initial|airborne/.test(p))return R("After takeoff / climb","Takeoff & climb");
    if(/cruise|en ?route/.test(p))return R(null,"Cruise");
  }
  if(ground){if(nearArr)return gs>3?R("After landing","Taxi in"):R("Parking","At the gate");return gs>3?R("Taxi","Taxi out"):R("Before start","At the gate")}
  const apprNm=Math.min(150,(total||300)*.4);
  if(remain!=null&&remain<15&&agl<3500)return R("Landing","Final approach");
  if(remain!=null&&remain<apprNm)return R("Approach","Descent");
  if(dDep!=null&&dDep<60)return R("After takeoff / climb","Climb");
  return R(null,"Cruise")}
/* Push the checklist for the current phase; list earlier ones in its group that were skipped. */
function clDue(sec){CLP.skipped=[];if(!sec)return null;const i=CL.findIndex(c=>c[0]===sec);if(i<0)return null;
  const g=CL_GROUPS.find(g=>g.includes(sec))||[sec];g.slice(0,g.indexOf(sec)).forEach(n=>{const k=CL.findIndex(c=>c[0]===n);if(k>=0){const q=clProgress(k);if(q.done<q.total)CLP.skipped.push(n)}});
  const q=clProgress(i);return q.done<q.total?i:null}
function clPushBanner(i,title,sub){
  if(window.__islOn&&window.__islOn()){const f=CLP.flight||{};
    islAlert({app:"Checklist · Live",short:CL[i][0],icon:`<span class="isx-ic" style="width:24px;height:24px;border-radius:6px;background:${APPS.checklist.bg};color:${APPS.checklist.fg}"><svg viewBox="0 0 24 24">${APPS.checklist.g}</svg></span>`,
      title:title||CL[i][0]+" checklist",sub:sub||((CLP.typeNote?CLP.typeNote+" · ":"")+CLP.why+" · "+(f.callsign||O().flight)),
      tap:()=>{clMode="normal";store.set("clMode","normal");clIdx=i;store.set("clIdx",i);goApp("checklist")}});return}let el=$("#clPush");if(!el){el=document.createElement("button");el.id="clPush";el.className="push";el.type="button";screenEl.appendChild(el);
    el.addEventListener("click",()=>{const k=+el.dataset.i;el.classList.remove("show");clMode="normal";store.set("clMode","normal");clIdx=k;store.set("clIdx",k);goApp("checklist")})}
  const f=CLP.flight||{};el.dataset.i=i;el.innerHTML=`<span class="push-ic" style="background:${APPS.checklist.bg};color:${APPS.checklist.fg}"><svg viewBox="0 0 24 24">${APPS.checklist.g}</svg></span><span class="push-b"><span class="push-h"><b>CHECKLIST</b><small>now</small></span><strong>${esc(title||CL[i][0]+" checklist")}</strong><small>${sub?esc(sub):(CLP.typeNote?esc(CLP.typeNote)+" · ":"")+esc(CLP.why)+" · "+esc(f.callsign||O().flight)+(f.groundspeed!=null?" · GS "+Math.round(f.groundspeed)+" KT":"")}</small></span>`;
  el.classList.remove("show");void el.offsetWidth;el.classList.add("show");clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove("show"),9000)}
function clPush(i){const id=O().id;if(CLP.pushed[id]===i)return;CLP.pushed[id]=i;store.set("clPushed",CLP.pushed);
  if(cur==="checklist"&&clMode==="normal"){clIdx=i;store.set("clIdx",i);render();toast((CLP.typeNote?CLP.typeNote+" · ":"")+"Live: "+CL[i][0]+" checklist");CLP.typeNote="";return}
  clIdx=i;store.set("clIdx",i);if(!cur)renderHome();clPushBanner(i);CLP.typeNote="";
  if(CLP.notify&&document.hidden&&"Notification" in window&&Notification.permission==="granted"){try{new Notification(CL[i][0]+" checklist",{body:CLP.why+" · "+O().flight,tag:"polaris-checklist"})}catch(e){}}}
/* Rebuild the checklists when the aircraft type of the current flight changes, and tell the pilot. */
function clTypeCheck(){const t=clType(),k=t.fam+":"+t.code,id=O().id,seen=store.get("clTypeSeen",{});
  if(CLP.typeKey!==k){const first=CLP.typeKey==null;CLP.typeKey=k;CL=buildCL();if(clIdx>=CL.length)clIdx=0;
    if(seen[id]!==k){seen[id]=k;store.set("clTypeSeen",seen);if(!first||t.src!=="OFP"){CLP.typeNote=t.name+" checklists";clPushBanner(clIdx,t.name+" checklists",(t.fam==="A350"?"A350 checklist":"A321 SOP")+" · from "+t.src+(t.ref?" "+t.ref:""));if(cur==="checklist")render();else if(!cur)renderHome()}}}}
async function clLivePoll(){if(!vamOn()||!CLP.on||CLP.loading){clTypeCheck();return}CLP.loading=true;
  try{const j=await vamGet("/api/efb/live");const L=j.flights||[];const me=vam.user.toLowerCase();const x=O();
    const f=L.find(q=>q.pilot&&q.pilot.toLowerCase()===me)||null;CLP.flight=f;CLP.err=null;CLP.at=Date.now();if(typeof MAP!=="undefined")MAP.live=L;
    if(!f)vamLoad("bookings");clTypeCheck();
    if(f){CLP.match=!f.from||!S(x.o.icao_code)||(f.from===S(x.o.icao_code)&&f.to===S(x.d.icao_code));const ph=clPhase(f);CLP.phase=f.phase||"";CLP.why=ph.why;CLP.idx=clDue(ph.sec);if(CLP.idx!=null&&CLP.match)clPush(CLP.idx)}
    else{CLP.idx=null;CLP.why=""}}
  catch(e){CLP.err=e.message}
  CLP.loading=false;if(cur==="checklist"&&clMode==="normal")render();else if(!cur)renderHome()}
function clLiveStrip(){if(clMode!=="normal")return "";
  if(!vamOn())return `<div class="live-strip off">${ico("link")}<span>Connect vAMSYS in Settings to have checklists pushed by flight phase.</span><a class="btn sm" href="#prefs">Settings</a></div>`;
  const f=CLP.flight,tog=`<button class="btn sm" data-clauto="${CLP.on?0:1}" aria-pressed="${CLP.on}">${CLP.on?"Following":"Follow flight"}</button>`;
  if(!CLP.on)return `<div class="live-strip off"><span class="dot"></span><span>Live checklist push is off.</span>${tog}</div>`;
  if(CLP.err&&!f)return `<div class="live-strip off"><span class="dot err"></span><span>${esc(CLP.err)}</span>${tog}</div>`;
  if(!f)return `<div class="live-strip off"><span class="dot"></span><span>${CLP.at?"No live vAMSYS flight for "+esc(vam.user)+". Start tracking in your vAMSYS client to get checklists pushed.":"Looking for your vAMSYS flight…"}</span>${tog}</div>`;
  return `<div class="live-strip"><span class="dot on"></span><span><b>${esc(f.callsign)}</b> ${esc(f.type||"")} ${esc(f.from)}→${esc(f.to)} · ${esc(CLP.why||f.phase||"—")} · GS ${Math.round(f.groundspeed||0)} KT · ${f.altitude>=18000?"FL"+Math.round(f.altitude/100):fmt(f.altitude)+" FT"}${CLP.match===false?' · <span class="c-amber">does not match the loaded OFP</span>':""}${CLP.skipped&&CLP.skipped.length?'<br><small class="c-amber">Not completed earlier: '+CLP.skipped.map(esc).join(", ")+'</small>':""}</span>${tog}</div>`}
document.addEventListener("click",e=>{const t=e.target.closest("button");if(!t)return;
  if(t.dataset.clauto){CLP.on=t.dataset.clauto==="1";store.set("clAuto",CLP.on);if(CLP.on){CLP.pushed[O().id]=null;clLivePoll()}render();return}
  if(t.dataset.cltype){store.set("clTypeSel",t.dataset.cltype);CLP.typeKey=null;const st=store.get("clTypeSeen",{});st[O().id]=null;store.set("clTypeSeen",st);clTypeCheck();CL=buildCL();if(clIdx>=CL.length)clIdx=0;render();toast(clType().name+" checklists");return}
  if(t.dataset.clnotify){if(t.dataset.clnotify==="0"){CLP.notify=false;store.set("clNotify",false);render();return}
    if(!("Notification" in window)){toast("This browser can’t show notifications");return}
    Notification.requestPermission().then(p=>{CLP.notify=p==="granted";store.set("clNotify",CLP.notify);toast(CLP.notify?"Notifications on":"Notifications were not allowed");render()});return}
});
setInterval(clLivePoll,15000);setTimeout(clLivePoll,2500);setTimeout(clTypeCheck,0);
document.addEventListener("visibilitychange",()=>{if(!document.hidden)clLivePoll()});

/* ===== Radar timeline: last ~80 minutes of RainViewer frames, play / step, intensity legend ===== */
function radarSet(i){if(!RADAR.frames.length)return;RADAR.i=(i+RADAR.frames.length)%RADAR.frames.length;const f=RADAR.frames[RADAR.i];RADAR.path=f.path;RADAR.time=f.time;mapSched();radarBar()}
function radarPlay(on){RADAR.play=on;clearInterval(RADAR.tm);if(on)RADAR.tm=setInterval(()=>{if(cur!=="map"){radarPlay(false);return}radarSet(RADAR.i+1)},750);radarBar()}
