function radarBar(){const el=$("#radarBar");if(!el)return;if(!ML.radar||!RADAR.frames.length||RADAR.err){el.hidden=true;return}el.hidden=false;const rc=!RADAR.open&&!RADAR.play;el.classList.toggle("rb-c",rc);
  const n=RADAR.frames.length,f=RADAR.frames[RADAR.i],d=new Date(f.time*1000),ago=Math.max(0,Math.round((Date.now()/1000-f.time)/60)),live=RADAR.i===n-1;
  el.innerHTML=`<button class="rb-play" data-rad="play" aria-label="${RADAR.play?"Pause":"Play"} radar loop">${RADAR.play?'<svg viewBox="0 0 24 24"><path d="M7 5h3.5v14H7zM13.5 5H17v14h-3.5z"/></svg>':'<svg viewBox="0 0 24 24"><path d="M8 5.5v13l11-6.5z"/></svg>'}</button>
${rc?`<button class="rb-time" data-rad="open" aria-label="Show radar timeline"><b>${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}Z</b><span class="${live?"rb-live":""}">${live?"Latest":ago+" min"}</span></button>`:`
   <div class="rb-mid"><div class="rb-top"><b>RADAR ${pad(d.getUTCHours())}${pad(d.getUTCMinutes())}Z</b><span class="${live?"rb-live":""}">${live?"Latest":ago+" min ago"}</span></div>
   <div class="rb-dots">${RADAR.frames.map((q,k)=>`<button data-rad="${k}" aria-label="Frame ${k+1}" aria-pressed="${k===RADAR.i}"></button>`).join("")}</div>
   <div class="rb-leg"><i></i><span>Light</span><span>Heavy</span></div></div>`}`}
document.addEventListener("click",e=>{const t=e.target.closest("[data-rad]");if(!t)return;const v=t.dataset.rad;if(v==="open"){RADAR.open=true;radarBar();radarIdle(6000)}else if(v==="play"){RADAR.open=true;radarPlay(!RADAR.play);if(!RADAR.play)radarIdle(4000)}else{RADAR.open=true;radarPlay(false);radarSet(+v);radarIdle(5000)}});
document.addEventListener("click",e=>{const b=e.target.closest("#mapAttrI");const w=document.querySelector(".mapwrap");if(!w)return;if(b){const o=!w.classList.contains("attr-open");w.classList.toggle("attr-open",o);b.setAttribute("aria-expanded",String(o));return}
  if(w.classList.contains("attr-open")&&!e.target.closest("#mapAttr")){w.classList.remove("attr-open");const i=$("#mapAttrI");if(i)i.setAttribute("aria-expanded","false")}});

