  if(d&&d.airport&&d.airport.lat!=null){lat=d.airport.lat;lon=d.airport.lon}else{const a=mapAptCandidates().find(q=>q.icao===s.icao&&q.lat!=null);if(a){lat=a.lat;lon=a.lon}}
