function ovGesture(st,pts,rect,w,h){const g0=st.ov;if(!g0)return;const z=MAP.z,c0=mpx(g0.lat,g0.lon,z),ids=[...pts.keys()];
  if(ids.length===1){const a=st.p.get(ids[0]),p=pts.get(ids[0]);if(!a)return;if(Math.abs(p.x-a.x)+Math.abs(p.y-a.y)>4)st.moved=true;if(!st.moved)return;const n=munpx(c0[0]+p.x-a.x,c0[1]+p.y-a.y,z);OV.geo={...g0,lat:n[0],lon:n[1]}}
  else{const a=st.p.get(ids[0]),b=st.p.get(ids[1]),p=pts.get(ids[0]),q=pts.get(ids[1]);if(!a||!b)return;const d0=Math.hypot(a.x-b.x,a.y-b.y),d1=Math.hypot(p.x-q.x,p.y-q.y);if(d0<10)return;st.moved=true;
    const s=Math.max(d1,1)/d0,ang=Math.atan2(q.y-p.y,q.x-p.x)-Math.atan2(b.y-a.y,b.x-a.x),mc=mpx(MAP.c.lat,MAP.c.lon,z);
    const cx=c0[0]-mc[0]+w/2+rect.left,cy=c0[1]-mc[1]+h/2+rect.top,m0x=(a.x+b.x)/2,m0y=(a.y+b.y)/2,m1x=(p.x+q.x)/2,m1y=(p.y+q.y)/2;
    const vx=cx-m0x,vy=cy-m0y,nx=m1x+(vx*Math.cos(ang)-vy*Math.sin(ang))*s,ny=m1y+(vx*Math.sin(ang)+vy*Math.cos(ang))*s,n=munpx(c0[0]+nx-cx,c0[1]+ny-cy,z);
    OV.geo={lat:n[0],lon:n[1],h:Math.max(200,Math.min(4e6,g0.h*s)),rot:((g0.rot+ang*180/Math.PI)%360+360)%360}}
  ovSched()}
function ovSave(){if(OV.sel&&OV.geo){store.set(ovKey(),OV.geo);OV.src="saved";if(OV.autoKind!=="pdf"){clearTimeout(OV.pushT);const sel=OV.sel,page=OV.page,geo={...OV.geo};OV.pushT=setTimeout(()=>ovSharedPut(sel,page,geo),2500)}}}
function ovUi(){if(typeof asUi==="function")asUi();const pn=$("#ovPanel"),bar=$("#ovBar"),btn=$("#ovBtn");if(!pn||!bar)return;if(btn)btn.setAttribute("aria-pressed",String(OV.open||!!OV.sel));
  /* the chart list lives in the airport sheet (Charts tab); the old list panel stays closed */
  if(!pn.hidden)pn.hidden=true;
  /* control bar */
  if(!OV.sel){bar.hidden=true;bar.innerHTML="";bar.dataset.sig="";return}
  const shI=OV.shInfo||{},sig=[OV.sel.pdf,OV.sel.name,OV.page,OV.pages,OV.loading,OV.err||"",OV.edit,OV.blend,!!OV.img,OV.src,OV.cropOn,!!OV.crop,shI.by||"",shI.undo||0,vamOn()].join("|");if(!bar.hidden&&bar.dataset.sig===sig)return;bar.dataset.sig=sig;bar.hidden=false;
  const head=`<div class="ov-top"><div><span class="eyebrow">${esc(OV.sel.icao)} · ${esc(OV.sel.group||"Chart")}</span><b>${esc(OV.sel.name)}</b>${OV.img?`<small class="ov-src">${OV.src==="shared"?(shI.by?"Lined up by "+esc(shI.by):"Lined up by a Polaris pilot"):OV.src==="auto"?(OV.autoKind==="rwy"?"Lined up with the runways":"Positioned from the chart’s own coordinates"):OV.src==="saved"?(OV.autoKind==="pdf"?"Your saved alignment":OV.shared?"Your alignment · shared with Polaris pilots":"Your saved alignment"):"Not lined up yet: Adjust, then Two fixes or drag it into place"}</small>`:""}</div><div class="ov-topb"><button class="btn sm" data-ov="full" aria-label="Open the chart full screen">Full chart</button><button class="btn sm" data-ov="close" aria-label="Remove chart overlay">Remove</button></div></div>`;
  if(OV.loading)bar.innerHTML=head+`<p class="note">Opening chart…</p>`;
  else if(OV.err)bar.innerHTML=head+`<p class="note">${esc(OV.err)}</p><div class="ov-row"><button class="btn sm" data-ov="retry">Try again</button></div>`;
  else if(OV.edit)bar.innerHTML=head+`<p class="note">Drag the chart to move it, pinch to resize and turn it. The map stays still.${OV.autoKind!=="pdf"&&!vamOn()?" Your alignment stays on this device; connect vAMSYS in Settings to share it with Polaris pilots.":""}</p><div class="ov-row"><button class="btn sm" data-ov="rot">Rotate 90°</button><button class="btn sm" data-ov="reset">Reset</button>${vamOn()&&shI.undo>0?`<button class="btn sm" data-ov="undo" title="Go back to the shared alignment before the last change">Undo shared change</button>`:""}<button class="btn sm primary" data-ov="edit" aria-pressed="true">Done</button></div>`;
  else bar.innerHTML=head+`<label class="ov-op"><span>Opacity</span><input type="range" id="ovOp" min="15" max="100" step="5" value="${Math.round(OV.op*100)}" aria-label="Chart opacity"></label>
    <div class="ov-row"><button class="btn sm" data-ov="edit" aria-pressed="false">Adjust</button>${OV.crop?`<button class="btn sm" data-ov="crop" aria-pressed="${OV.cropOn}">Plan view</button>`:""}<button class="btn sm" data-ov="blend" aria-pressed="${OV.blend}">See-through</button><button class="btn sm" data-ov="fly">Centre</button>${OV.pages>1?`<button class="btn sm" data-ov="prev" aria-label="Previous page"${OV.page<=1?" disabled":""}>‹</button><span class="mono">${OV.page}/${OV.pages}</span><button class="btn sm" data-ov="next" aria-label="Next page"${OV.page>=OV.pages?" disabled":""}>›</button>`:""}</div>`}
document.addEventListener("click",e=>{const t=e.target.closest("[data-ov],#chMap");if(!t)return;
  if(t.id==="chMap"){if(CH.sel){ovOpen(CH.sel,CH.icao,CH.sel.cycle);location.hash="#map"}return}
  const a=t.dataset.ov;
  if(a==="close")ovClose();
  else if(a==="edit"){OV.edit=!OV.edit;ovUi();ovSched()}
  else if(a==="rot"&&OV.geo){OV.geo={...OV.geo,rot:(OV.geo.rot+90)%360};ovSave();ovSched()}
  else if(a==="reset"){store.set(ovKey(),null);if(OV.shared){OV.geo={...OV.shared};OV.src="shared"}else{OV.geo=ovDefault();OV.src=OV.auto?"auto":""}ovUi();ovSched()}
  else if(a==="crop"){OV.cropOn=!OV.cropOn;store.set("ovCrop",OV.cropOn);ovUi();ovSched()}
  else if(a==="blend"){OV.blend=!OV.blend;store.set("ovBlend",OV.blend);ovUi();ovSched()}
  else if(a==="fly")ovFly();
  else if(a==="undo")ovSharedUndo();
  else if(a==="retry"&&OV.sel){const s=OV.sel;ovOpen({name:s.name,pdf:s.pdf,group:s.group},s.icao,s.cycle)}
  else if((a==="prev"||a==="next")&&OV.doc){const n=OV.page+(a==="next"?1:-1);if(n>=1&&n<=OV.pages)ovPage(n).then(()=>{ovUi();ovSched()}).catch(()=>{})}});
document.addEventListener("input",e=>{if(e.target.id==="ovOp"){OV.op=Math.max(.15,Math.min(1,+e.target.value/100));store.set("ovOp",OV.op);ovSched()}});

/* Airport diagrams carry no georeference, but their runway-end numbers are real text. Each "28R" sits just beyond
   that runway's threshold, so matching the numbers to the runway ends in the airport layout gives the chart's
   position, size and rotation (a similarity fit, with a robust first guess so taxiway letters can't fool it). */
function dgRef(items,view,rwys,merc){try{
  const W=view[2]-view[0],H=view[3]-view[1];
  /* runway ends from the layout: the two farthest points of each runway, named by direction */
  const byRef={};rwys.forEach(r=>{if(r.stopway||r.area||!r.ref||!r.pts||r.pts.length<2)return;(byRef[r.ref]=byRef[r.ref]||[]).push(...r.pts)});
  const ends=[];Object.keys(byRef).forEach(ref=>{const m=ref.toUpperCase().match(/^0?(\d{1,2})([LCR]?)\s*[\/-]\s*0?(\d{1,2})([LCR]?)$/);if(!m)return;const P=byRef[ref];let a=P[0],b=P[1],best=-1;
    for(let i=0;i<P.length;i++)for(let j=i+1;j<P.length;j++){const d=(P[i][0]-P[j][0])**2+((P[i][1]-P[j][1])*1.25)**2;if(d>best){best=d;a=P[i];b=P[j]}}
    const brg=(p,q)=>{const r=Math.PI/180,y=Math.sin((q[0]-p[0])*r)*Math.cos(q[1]*r),x=Math.cos(p[1]*r)*Math.sin(q[1]*r)-Math.sin(p[1]*r)*Math.cos(q[1]*r)*Math.cos((q[0]-p[0])*r);return(Math.atan2(y,x)/r+360)%360};
    const d1=+m[1],s1=m[2],d2=+m[3],s2=m[4],ba=brg(a,b),diff=(x,y)=>Math.abs(((x-y)%360+540)%360-180);
    /* the end you take off from heading toward the other one carries the number of that heading */
    const aIs1=diff(ba,d1*10)<diff(ba,d2*10);const e1=aIs1?a:b,e2=aIs1?b:a;
    ends.push({n:d1,s:s1,ll:e1,far:e2},{n:d2,s:s2,ll:e2,far:e1})});
  if(ends.length<2)return null;const nums=new Set(ends.map(e=>e.n));
  /* glue single characters into words: "2" "5" "R" printed one after another along the same baseline */
  const raw=items.map(it=>{const t=it.transform,ul=Math.hypot(t[0],t[1])||1,vl=Math.hypot(t[2],t[3])||1;return{s:String(it.str||"").trim(),o:[t[4],t[5]],u:[t[0]/ul,t[1]/ul],v:[t[2]/vl,t[3]/vl],w:it.width||0,h:it.height||vl}}).filter(o=>o.s&&/^[0-9LCR]+$/.test(o.s));
  const used=new Set(),words=[];
  raw.forEach((a,ia)=>{if(used.has(ia))return;
    /* walk back to the first character of this word */
    let start=a,si=ia,guard=0;for(;;){const prev=raw.findIndex((b,ib)=>ib!==si&&!used.has(ib)&&b.u[0]*start.u[0]+b.u[1]*start.u[1]>.98&&Math.hypot(b.o[0]+b.u[0]*b.w-start.o[0],b.o[1]+b.u[1]*b.w-start.o[1])<Math.max(2.4,start.h*.6));if(prev<0||++guard>6)break;start=raw[prev];si=prev}
    const g=[start];used.add(si);let cur=start;guard=0;
    for(;;){const nx=raw.findIndex((b,ib)=>!used.has(ib)&&b.u[0]*cur.u[0]+b.u[1]*cur.u[1]>.98&&Math.hypot(cur.o[0]+cur.u[0]*cur.w-b.o[0],cur.o[1]+cur.u[1]*cur.w-b.o[1])<Math.max(2.4,cur.h*.6));if(nx<0||++guard>6)break;used.add(nx);g.push(raw[nx]);cur=raw[nx]}
    const s=g.map(x=>x.s).join(""),f=g[0],l=g[g.length-1],e=[l.o[0]+l.u[0]*l.w,l.o[1]+l.u[1]*l.w];
    words.push({s,c:[(f.o[0]+e[0])/2+f.v[0]*f.h*.38-view[0],(f.o[1]+e[1])/2+f.v[1]*f.h*.38-view[1]]})});
  const labs=[];words.forEach(o=>{const m=o.s.match(/^0?(\d{1,2})([LCR]?)$/);if(!m)return;const n=+m[1];if(!nums.has(n))return;let suf=m[2]||"";
    if(!suf){const near=words.find(q=>/^[LCR]$/.test(q.s)&&Math.hypot(q.c[0]-o.c[0],q.c[1]-o.c[1])<9);if(near)suf=near.s}
    labs.push({n,s:suf,p:[o.c[0],H-o.c[1]]})});
  if(labs.length<2)return null;
  const Q=ends.map(e=>merc(e.ll[1],e.ll[0])),lat0=ends[0].ll[1],mPerQ=40075016.7*Math.cos(lat0*Math.PI/180);
  const cand=l=>ends.map((e,i)=>i).filter(i=>ends[i].n===l.n&&(!l.s||!ends[i].s||ends[i].s===l.s));
  const fit=pairs=>{const n=pairs.length;if(n<2)return null;let px=0,py=0,qx=0,qy=0;pairs.forEach(([p,q])=>{px+=p[0];py+=p[1];qx+=q[0];qy+=q[1]});px/=n;py/=n;qx/=n;qy/=n;
    let ar=0,ai=0,den=0;pairs.forEach(([p,q])=>{const a=p[0]-px,b=p[1]-py,c=q[0]-qx,d=q[1]-qy;ar+=c*a+d*b;ai+=d*a-c*b;den+=a*a+b*b});if(!den)return null;ar/=den;ai/=den;
    return{ar,ai,px,py,qx,qy,map:p=>[qx+ar*(p[0]-px)-ai*(p[1]-py),qy+ai*(p[0]-px)+ar*(p[1]-py)]}};
  /* targets: each end, moved out along its runway by "off" (the numbers are printed beyond the threshold) */
  const tgt=(i,off)=>{const e=ends[i],a=Q[i],b=merc(e.far[1],e.far[0]),ax=a[0]-b[0],ay=a[1]-b[1],L=Math.hypot(ax,ay)||1;return[a[0]+ax/L*off,a[1]+ay/L*off]};
  const score=(f,off,tol)=>{const sc=Math.hypot(f.ar,f.ai),hM=H*sc*mPerQ;if(!(hM>600&&hM<25000))return null;const ins=[];
    labs.forEach(l=>{const q=f.map(l.p);let bi=-1,bd=1e9;cand(l).forEach(i=>{const t=tgt(i,off),d=Math.hypot(q[0]-t[0],q[1]-t[1])*mPerQ;if(d<bd){bd=d;bi=i}});if(bi>=0&&bd<tol)ins.push([l,bi,bd])});
    const used={},ok=[];ins.sort((a,b)=>a[2]-b[2]).forEach(x=>{if(!used[x[1]]){used[x[1]]=1;ok.push(x)}});
    /* a number with its L/C/R counts more than a bare number (bare numbers are often elevations or taxiways) */
    return{ins:ok,w:ok.reduce((s,x)=>s+(x[0].s||nums.size<=2?1:.4),0),err:ok.reduce((s,x)=>s+x[2],0)}};
  let best=null;
  for(let i=0;i<labs.length;i++)for(let j=i+1;j<labs.length;j++){if(labs[i].n===labs[j].n)continue;
    for(const gi of cand(labs[i]))for(const gj of cand(labs[j])){if(gi===gj)continue;const f=fit([[labs[i].p,Q[gi]],[labs[j].p,Q[gj]]]);if(!f)continue;const s=score(f,0,320);if(!s)continue;
      if(!best||s.w>best.s.w+1e-9||(Math.abs(s.w-best.s.w)<1e-9&&s.err<best.s.err))best={f,s}}}
  
  /* a single runway gives only its two ends: accept them when they really are the two ends of one runway */
  if(best&&best.s.ins.length===2){const[x,y]=best.s.ins;if(ends[x[1]].far===ends[y[1]].ll&&x[0].s===ends[x[1]].s&&y[0].s===ends[y[1]].s&&x[2]<1&&y[2]<1){const f=best.f,sc=Math.hypot(f.ar,f.ai),c=f.map([W/2,H/2]);return{c,h:H*sc,rot:((Math.atan2(f.ai,f.ar)*180/Math.PI)%360+360)%360,n:2,rms:0,off:0,labels:[]}}}
  if(!best||best.s.ins.length<3)return null;
  let ins=best.s.ins,f=fit(ins.map(([l,i])=>[l.p,Q[i]])),off=0,rms=1e9;
  for(let it=0;it<3;it++){
    const outw=ins.map(([l,i])=>{const e=ends[i],q=f.map(l.p),a=Q[i],b=merc(e.far[1],e.far[0]),ax=a[0]-b[0],ay=a[1]-b[1],L=Math.hypot(ax,ay)||1;return((q[0]-a[0])*ax+(q[1]-a[1])*ay)/L}).sort((x,y)=>x-y);
    off=Math.max(0,Math.min(500/mPerQ,outw[Math.floor(outw.length/2)]));
    const s2=score(f,off,it?120:220);if(!s2||s2.ins.length<3)break;ins=s2.ins;f=fit(ins.map(([l,i])=>[l.p,tgt(i,off)]))||f;
    rms=Math.sqrt(ins.reduce((s,[l,i])=>{const m=f.map(l.p),t=tgt(i,off);return s+((m[0]-t[0])**2+(m[1]-t[1])**2)},0)/ins.length)*mPerQ}
  if(!(rms<80)||ins.length<3)return null;best={s:{ins}};
  const sc=Math.hypot(f.ar,f.ai),c=f.map([W/2,H/2]);
  return{c,h:H*sc,rot:((Math.atan2(f.ai,f.ar)*180/Math.PI)%360+360)%360,n:best.s.ins.length,rms:Math.round(rms),off:Math.round(off*mPerQ),labels:ins.map(([l,i])=>l.n+l.s+"->"+ends[i].n+ends[i].s)}}catch(e){return null}}


/* airport layout for the chart's airport (runway ends), loading it if needed, then the fit */
async function ovDiagRef(pg){try{const icao=OV.sel&&OV.sel.icao;if(!icao||rot0(pg))return null;
  /* AIP Taiwan diagrams print runway numbers too far from the ends, and other numbers like them: Line up instead */
  if((CH.data[icao]||{}).src==="tw")return null;
    if(!TX.data[icao]){txLoad(icao);for(let i=0;i<16&&!TX.data[icao];i++)await new Promise(r=>setTimeout(r,250))}
    const d=TX.data[icao];if(!d||!d.runways||!d.runways.length)return null;
    const tc=await pg.getTextContent();const g=dgRef(tc.items,pg.view,d.runways,(lat,lon)=>{const q=mpx(lat,lon,0);return[q[0]/TS,q[1]/TS]});if(!g)return null;
    const ll=munpx(g.c[0]*TS,g.c[1]*TS,0),hM=g.h*40075016.7*Math.cos(ll[0]*Math.PI/180);if(!isFinite(ll[0])||!(hM>500&&hM<30000))return null;
    return{lat:ll[0],lon:((ll[1]+540)%360)-180,h:hM,rot:g.rot}}catch(e){return null}}
const rot0=pg=>(pg.rotate||0)%360!==0;
try{window.__efbDg=dgRef}catch(e){}

/* shared alignment on the EFB server: read when a chart opens, written a moment after a pilot finishes adjusting */
const ovShQ=(sel,page)=>"icao="+encodeURIComponent(sel.icao)+"&name="+encodeURIComponent(sel.name)+"&page="+page;
async function ovSharedGet(sel,page,hasLocal){if(!vam.url||!sel)return;try{const j=await vamGet("/api/efb/ovgeo?"+ovShQ(sel,page),10000);const g=j&&j.geo;
    if(!g||OV.sel!==sel||OV.page!==page)return;OV.shared={lat:g.lat,lon:g.lon,h:g.h,rot:g.rot};OV.shInfo={by:g.by||"",t:g.t||0,undo:g.undo||0};
    if(!hasLocal&&!OV.edit){OV.geo={...OV.shared};OV.src="shared";ovUi();ovSched();if(cur==="map")ovFly()}else ovUi()}catch(e){}}
/* shared only by a pilot connected to vAMSYS (Settings), under that username; the server keeps the five alignments
   before each change, so a bad one can be undone (ovSharedUndo) */
async function ovSharedPost(body){const r=await fetch(vam.url.replace(/\/+$/,"")+"/api/efb/ovgeo",{method:"POST",headers:{"Content-Type":"text/plain"},body:JSON.stringify({...body,user:vam.user})});
  let j=null;try{j=await r.json()}catch(e){}if(!r.ok)throw new Error((j&&j.error)||"The EFB server answered HTTP "+r.status);return j}
async function ovSharedPut(sel,page,geo){if(!vamOn()||!sel||!geo)return;try{const j=await ovSharedPost({icao:sel.icao,name:sel.name,page,geo});const g=j&&j.geo;
    if(OV.sel===sel){OV.shared={...geo};if(g)OV.shInfo={by:g.by||vam.user,t:g.t||Date.now(),undo:g.undo||0};if(!OV.sharedToast){OV.sharedToast=1;toast("Alignment shared with Polaris pilots")}ovUi()}}
  catch(e){if(!OV.shareErrToast){OV.shareErrToast=1;toast(e.message||"Couldn’t share the alignment")}}}
async function ovSharedUndo(){const sel=OV.sel,page=OV.page;if(!vamOn()||!sel)return;try{const j=await ovSharedPost({icao:sel.icao,name:sel.name,page,revert:true});const g=j&&j.geo;if(!g||OV.sel!==sel)return;
    OV.shared={lat:g.lat,lon:g.lon,h:g.h,rot:g.rot};OV.shInfo={by:g.by||"",t:g.t||0,undo:g.undo||0};store.set(ovKey(),null);OV.geo={...OV.shared};OV.src="shared";toast("Back to the alignment before the last change");ovUi();ovSched()}
  catch(e){toast(e.message||"Couldn’t undo")}}

/* ---------- Vector base map ----------
   MapLibre GL draws OpenFreeMap vector tiles (OpenStreetMap data) under everything else. It is not
   interactive: the EFB keeps its own camera (MAP.c, MAP.z) and copies it to MapLibre on every frame,
   so the base map stays sharp during a pan or pinch while the overlays are moved as a picture. */
const VEC={map:null,el:null,lib:null,ready:false,err:null,key:"",t0:0};
const OFM="https://tiles.openfreemap.org";
/* Base map presets. FAA charts are the FAA's own published raster charts (US only); outside their coverage
   and beyond their zoom range the vector map shows through. */
const FAA_T="https://tiles.arcgis.com/tiles/ssFJjBXIUyZDrSYZ/arcgis/rest/services/";
const BASES={map:{name:"Map"},sat:{name:"Satellite",ras:[{id:"sat",url:"https://tiles.maps.eox.at/wmts/1.0.0/s2cloudless-2023_3857/default/g/{z}/{y}/{x}.jpg",min:0,max:14}],attr:'Satellite <a href="https://s2maps.eu" target="_blank" rel="noopener">Sentinel-2 cloudless by EOX</a> (Copernicus Sentinel data 2023)'},
  ifrh:{name:"IFR High",us:1,ifr:"H"},ifrl:{name:"IFR Low",us:1,ifr:"L"},
  faah:{name:"FAA High chart",us:1,ras:[{id:"ifrh",url:FAA_T+"IFR_High/MapServer/tile/{z}/{y}/{x}",min:4,max:9}]},
  faal:{name:"FAA Low chart",us:1,ras:[{id:"ifrl",url:FAA_T+"IFR_AreaLow/MapServer/tile/{z}/{y}/{x}",min:7,max:12}]},
  vfr:{name:"VFR",us:1,vfr:true,attr:'Terrain <a href="https://registry.opendata.aws/terrain-tiles/" target="_blank" rel="noopener">Terrain Tiles</a> (Mapzen, AWS Open Data)'},
  faav:{name:"FAA VFR chart",us:1,ras:[{id:"sec",url:FAA_T+"VFR_Sectional/MapServer/tile/{z}/{y}/{x}",min:8,max:12},{id:"tac",url:FAA_T+"VFR_Terminal/MapServer/tile/{z}/{y}/{x}",min:9,max:12}]}};
const baseKey=()=>BASES[ML.base]?ML.base:"map";
