/* FIR identifiers as a vector-map symbol layer: placed on top, so where one collides with a country or city name the base-map name gives way */
const vecFirOn=()=>vecReady()&&ML.fir&&!!FIR.data&&VEC.firOk===true;
function vecFirSync(){const m=VEC.map;if(!m||!VEC.ready)return;let ok=false;
  try{if(!m.isStyleLoaded()){VEC.firOk=!!m.getLayer("fir-lbl");VEC.firLn=VEC.firOk&&!!m.getLayer("fir-ln");return}
    const want=vecOn()&&ML.fir&&FIR.data;
    if(want){const cs=getComputedStyle(document.documentElement),cv=(k,d)=>(cs.getPropertyValue(k)||"").trim()||d;
      const col=cv("--map-firl","#2f9e6e"),land=cv("--map-land","#f2f2f2"),sea=cv("--map-sea","#cfe3ea"),ck=col+land+sea;
      if(!m.getSource("firlbl")||VEC.firSrc!==FIR.data){const seen=new Set(),fs=[];FIR.data.forEach(f=>{if(f.id.includes("-")||seen.has(f.id)||!isFinite(f.lx)||!isFinite(f.ly))return;seen.add(f.id);fs.push({type:"Feature",geometry:{type:"Point",coordinates:[f.lx,f.ly]},properties:{id:f.id,nm:f.nm&&f.nm.toUpperCase()!==f.id?f.nm.toUpperCase():"",oc:f.oc?1:0}})});
        const fc={type:"FeatureCollection",features:fs};if(m.getSource("firlbl"))m.getSource("firlbl").setData(fc);else m.addSource("firlbl",{type:"geojson",data:fc});VEC.firSrc=FIR.data}
      if(m.getLayer("fir-lbl")&&VEC.firCk!==ck){m.removeLayer("fir-lbl")}
      if(!m.getLayer("fir-lbl")){m.addLayer({id:"fir-lbl",type:"symbol",source:"firlbl",minzoom:1.2,maxzoom:8.5,
        layout:{"text-field":["step",["zoom"],["get","id"],3.6,["format",["get","id"],{},["case",["==",["get","nm"],""],"","\n"],{},["get","nm"],{"font-scale":.72}]],"text-font":["Noto Sans Bold"],"text-size":["interpolate",["linear"],["zoom"],1.2,11,4,12.5,6,13.5],"text-letter-spacing":.04,"text-padding":3,"symbol-sort-key":["get","oc"]},
        paint:{"text-color":col,"text-halo-color":["case",["==",["get","oc"],1],sea,land],"text-halo-width":1.8}});VEC.firCk=ck}
      /* the outlines as MapLibre lines: drawn by the GPU at every frame of a pan or pinch, where an SVG path of every FIR
         in the world had to be rebuilt at each redraw (a tenth of a second zoomed out to the world) */
      if(!m.getSource("firln")||VEC.firLnSrc!==FIR.data){const fs=[];FIR.data.forEach(f=>f.rings.forEach(r=>{const p=r.p;if(!p||p.length<2)return;const a=p[0],b=p[p.length-1];
          fs.push({type:"Feature",geometry:{type:"LineString",coordinates:r.open||(a[0]===b[0]&&a[1]===b[1])?p:p.concat([a])},properties:{oc:f.oc?1:0}})}));
        const fc={type:"FeatureCollection",features:fs};if(m.getSource("firln"))m.getSource("firln").setData(fc);else m.addSource("firln",{type:"geojson",data:fc,tolerance:.5,buffer:4});VEC.firLnSrc=FIR.data}
      const lc=cv("--map-fir","#3DAA78");
      if(m.getLayer("fir-ln")&&VEC.firLnCk!==lc){m.removeLayer("fir-ln");if(m.getLayer("fir-ln-oc"))m.removeLayer("fir-ln-oc")}
      if(!m.getLayer("fir-ln")){const before=(m.getStyle().layers.find(l=>l.type==="symbol"&&l.id!=="fir-lbl")||{}).id;
        /* as the SVG outlines were: fainter and thinner zoomed out to the world; oceanic FIRs dashed */
        const op=["step",["zoom"],.4,2,.65,3.5,1],wd=["step",["zoom"],.7,2,.9,3.5,1.15];
        m.addLayer({id:"fir-ln",type:"line",source:"firln",filter:["==",["get","oc"],0],layout:{"line-join":"round"},paint:{"line-color":lc,"line-width":wd,"line-opacity":op}},before);
        m.addLayer({id:"fir-ln-oc",type:"line",source:"firln",filter:["==",["get","oc"],1],layout:{"line-join":"round"},paint:{"line-color":lc,"line-width":wd,"line-opacity":op,"line-dasharray":[1.8,3.5]}},before);VEC.firLnCk=lc}
      ok=true}
    else{if(m.getLayer("fir-lbl"))m.removeLayer("fir-lbl");if(m.getLayer("fir-ln"))m.removeLayer("fir-ln");if(m.getLayer("fir-ln-oc"))m.removeLayer("fir-ln-oc")}}catch(e){ok=false}
  VEC.firOk=ok;VEC.firLn=ok&&!!m.getLayer("fir-ln")}
const vecFirLn=()=>vecFirOn()&&VEC.firLn===true;

