  const end=e=>{if(!pts.has(e.pointerId))return;pts.delete(e.pointerId);
    /* let go near a quarter turn and it settles there */
    if(!pts.size){const r=((CV.rot%360)+360)%360,q=Math.round(r/90)*90;if(Math.abs(r-q)<6&&r!==q){cvTurn(q-r)}}
    g0=pts.size?snap():null};
