/* cloud layers close together: their labels move along the line instead of piling up on each other */
function wxClLayout(){document.querySelectorAll(".clouds").forEach(ch=>{const L=[...ch.querySelectorAll(".cl")].map(cl=>({cl,sp:cl.querySelector("span"),t:cl.offsetTop})).filter(x=>x.sp).sort((a,b)=>a.t-b.t),put=[];
  for(const x of L){x.sp.style.left="8px";const w=x.sp.offsetWidth,h=x.sp.offsetHeight||17,top=x.t-20,bot=top+h;let left=8,moved=true;
    while(moved){moved=false;for(const p of put)if(top<p.bot+1&&bot>p.top-1&&left<p.right+8&&left+w>p.left-8){left=p.right+10;moved=true}}
    x.sp.style.left=left+"px";put.push({top,bot,left,right:left+w})}})}
