/* ---- the same airports and units on every device: kept for the pilot on the EFB server (/api/efb/wx); the newer copy wins ---- */
let wxlSyncT=0;
function wxlTouch(){try{store.set("wxUpd",Date.now())}catch(e){}clearTimeout(wxlSyncT);wxlSyncT=setTimeout(wxlSync,900)}
function wxlApplyRemote(wx,upd){WXL.fav=(wx.fav||[]).filter(x=>/^[A-Z0-9]{3,4}$/.test(x));Object.assign(WXU,wx.units||{});
  try{store.set("wxFav",WXL.fav);store.set("wxUnits",WXU);store.set("wxUpd",upd)}catch(e){}if(cur==="wx")wxlRefresh();else if(!cur&&typeof renderHome==="function")renderHome()}
async function wxlSync(){if(WXL.syncing||typeof authOn!=="function"||!authOn()||!authSrv()||navigator.onLine===false)return;WXL.syncing=true;
  try{let upd=store.get("wxUpd",0)||0;const g=await fetch(authSrv()+"/api/efb/wx").then(r=>r.ok?r.json():Promise.reject(new Error(r.status)));
    if(g.wx&&g.upd>upd){const same=JSON.stringify(g.wx.fav||[])===JSON.stringify(WXL.fav)&&JSON.stringify(Object.assign({},WXU,g.wx.units||{}))===JSON.stringify(WXU);if(same)store.set("wxUpd",g.upd);else wxlApplyRemote(g.wx,g.upd)}
    else{/* first time here with airports or units already set on this device: they become the pilot's copy */
      if(!g.wx&&!upd&&(WXL.fav.length||WXU.t!=="C"||WXU.w!=="kt"||WXU.p!=="inHg"||WXU.v!=="sm"||WXU.h!=="ft")){upd=Date.now();store.set("wxUpd",upd)}
      if(upd&&(!g.wx||upd>g.upd)){const r=await fetch(authSrv()+"/api/efb/wx",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({wx:{fav:WXL.fav,units:WXU},upd})}).then(r=>r.json());
        if(r&&r.stale&&r.wx)wxlApplyRemote(r.wx,r.upd)}}}
  catch(e){}WXL.syncing=false}
