/* ===== Weather: where your aircraft is =====
   Like "My Location" in iOS Weather: while you fly a Polaris flight that vAMSYS shows live, the list starts with the
   weather at the airport nearest your aircraft (the nearest one that reports a METAR), with how far it is. It follows
   the aircraft as it flies, has the location arrow in the iPhone's dots, and is gone once the flight ends. The airport
   list is the EFB's own (the one the map uses), so nothing new is asked of the server. */
const WXP={f:null,at:0,busy:false,near:null,look:{},tm:0};
const wxpNm=(a,b,c,d)=>{const r=Math.PI/180,x=Math.sin((c-a)*r/2),y=Math.sin((d-b)*r/2),h=x*x+Math.cos(a*r)*Math.cos(c*r)*y*y;return 3440.065*2*Math.asin(Math.min(1,Math.sqrt(h)))};
function wxpPos(){const f=WXP.f;if(!f)return null;const la=N(f.lat),lo=N(f.lon);return la!=null&&lo!=null?{la,lo,f}:null}
/* the live flight: the checklist's poll when it is fresh, else our own (every 30 s while Weather is open) */
function wxpPoll(){if(!vam.url||!vam.user)return;
  if(typeof CLP!=="undefined"&&CLP.at&&Date.now()-CLP.at<40000){WXP.f=CLP.flight||null;WXP.at=CLP.at;wxpNear();return}
  if(WXP.busy)return;WXP.busy=true;
  vamGet("/api/efb/live",15000).then(j=>{const L=(j&&j.flights)||[],me=vam.user.toLowerCase();WXP.f=L.find(q=>q.pilot&&q.pilot.toLowerCase()===me)||null;WXP.at=Date.now();if(typeof MAP!=="undefined")MAP.live=L})
    .catch(()=>{}).finally(()=>{WXP.busy=false;wxpNear()})}
/* the nearest airport that has a METAR */
function wxpNear(){const p=wxpPos(),was=WXP.near&&WXP.near.icao+":"+Math.round(WXP.near.nm/5);
  if(!p){WXP.near=null}else if(typeof APTS==="undefined"||!APTS.a){if(typeof aptsLoad==="function")aptsLoad("a");clearTimeout(WXP.tm);WXP.tm=setTimeout(wxpNear,1500);return}
  else{const c=[];for(const r of APTS.a){if(!/^[A-Z]{4}$/.test(r[0]))continue;const d=Math.abs(r[3]-p.la);if(d>12)continue;c.push([wxpNm(p.la,p.lo,r[3],r[4]),r])}
    c.sort((a,b)=>a[0]-b[0]);let pick=null;
    for(const[nm,r]of c.slice(0,6)){const icao=r[0],L=WXP.look[icao];
      if(L==null){WXP.look[icao]="busy";vamGet("/api/efb/airport?icao="+icao,20000).then(j=>{WXP.look[icao]=j&&j.metar&&j.metar.raw?"ok":"none";if(j&&j.airport){if(typeof AS!=="undefined")AS.data[icao]=j;FCW.taf[icao]={at:Date.now(),raw:j.taf&&j.taf.raw||null,metar:j.metar&&j.metar.raw||null}}})
        .catch(()=>{WXP.look[icao]="none"}).finally(()=>wxpNear());break}
      if(L==="busy")break;if(L==="ok"){pick={icao,nm,name:r[2]};break}}
    if(pick)WXP.near=pick;else if(!c.length)WXP.near=null}
  const now=WXP.near&&WXP.near.icao+":"+Math.round(WXP.near.nm/5);/* opened on the aircraft last time: back to it as soon as it is known again */
  if(now&&!was&&store.get("wxSel")==="POS")wxSel="POS";if(now!==was&&cur==="wx")render()}
setInterval(()=>{if(cur==="wx"&&!document.hidden)wxpPoll()},30000);
window.addEventListener("hashchange",()=>{if(location.hash==="#wx")setTimeout(wxpPoll,300)});
setTimeout(()=>{if(cur==="wx")wxpPoll()},1500);
