function hotBand(t,oat){return t.bands.findIndex(b=>oat>=b[0])}
function hotLook(){const t=HOT[WI.fl||"t1a"],oat=WI.oat,c=WI.cond||"sl";if(oat==null||!isFinite(oat))return{msg:"Enter the outside air temperature."};
  const bi=hotBand(t,oat),band=t.bands[bi];const conc=t.conc?(WI.conc||"100/0"):"";const rows=t.rows[conc]||[];
  if(c==="oth")return{none:true,band,why:"No holdover time guidelines exist for heavy snow, ice pellets, moderate or heavy freezing rain, small hail or hail."};
  if(conc&&!rows[bi])return{none:true,band,why:`No holdover times for ${conc} ${t.name.split(" ·")[0]} at this temperature. Check the lowest operational use temperature (LOUT); use 100/0 or Type I.`};
  let col=t.cols.indexOf(c);if(col<0&&/^s(vl|l|m)$/.test(c))col=t.cols.indexOf("sn");const v=rows[bi]?rows[bi][col]:null;
  const notes=[];if(c==="fzdz"||c==="lfzra"){if((WI.fl==="t2"||WI.fl==="t4")&&oat<-10)return{none:true,band,why:"No holdover time guidelines exist for this condition below −10 °C."}}
  if((c==="smra"||c==="rcsw")&&oat<=0&&!v)return{none:true,band,why:"No holdover time guidelines exist for this condition at 0 °C and below."};
  if(!v)return{none:true,band,why:"No holdover time guidelines exist for this condition and temperature."};
  if(t.cols.includes("sn")&&/^s(vl|l|m)$/.test(c))notes.push("Type II has one snow range from moderate (lower value) to very light (upper value).");
  if(/^s(vl|l|m)$|^snfg$|^smra$/.test(c))notes.push("Snowfall intensity comes from the reported visibility (FAA Table 57). No holdover times exist if it correlates to heavy snow.");
  if(c==="fzdz")notes.push("Use light freezing rain times if freezing drizzle can’t be positively identified.");
  if(c==="smra")notes.push("For very light or light snow mixed with light rain or drizzle, use light freezing rain times.");
  return{v,band,conc,notes}}
const wiHM=m=>Math.floor(m/60)+":"+String(m%60).padStart(2,"0");
/* suggest a condition from a METAR's present weather */
function hotFromMetar(raw){const r=" "+String(raw||"").split(/ RMK /)[0]+" ";
  if(/ (\+|)FZRA| PL| GR| GS|\+SN|\+SG/.test(r)&&!/ -FZRA/.test(r))return"oth";if(/ -FZRA/.test(r))return"lfzra";if(/FZDZ/.test(r))return"fzdz";
  if(/(SN|SG|PL)\S*RA|RA\S*SN/.test(r))return"smra";if(/ (-|)(SN|SG) /.test(r)&&/FZFG/.test(r))return"snfg";if(/ -SN| -SG/.test(r))return"sl";if(/ SN | SG /.test(r))return"sm";if(/FZFG|IC /.test(r))return"fzfg";return null}
function wiPrefill(){const x=O();if(WI._for===x.id)return;WI._for=x.id;
  const dep=wxFor(x).find(a=>a[1]==="DEP"),dst=wxFor(x).find(a=>a[1]==="DEST");
  const md=dep&&decodeMetar(dep[3]);if(md&&md.temp!=null)WI.oat=md.temp;const sug=dep&&hotFromMetar(dep[3]);if(sug)WI.cond=sug;
  const t=S(x.ac.icaocode);if(t&&!WI.fl)WI.fl=/^A35/.test(t)?"t1c":"t1a";
  const ma=dst&&decodeMetar(dst[3]);if(dst){WI.ad=S(dst[2].icao_code);const el=N(dst[2].elevation);if(el!=null)WI.elev=el;if(ma&&ma.temp!=null)WI.tad=ma.temp}wiSave()}
function wiColdCalc(){const el=N(WI.elev),t=N(WI.tad);const ok=el!=null&&t!=null;let isa="Enter the aerodrome elevation and temperature.";if(ok){const dev=t-(15-1.98*el/1000);isa=`ISA ${dev>=0?"+":"−"}${Math.abs(dev).toFixed(0)} °C`+(t>0?" · no correction above 0 °C":"")}
  const rows={};WI_ROWS.forEach(([k])=>{const a=N((WI.alt||{})[k]);let out="—",add="";if(ok&&a!=null&&a>el){const cr=Math.ceil(wiCorr(a,el,t)/10)*10;out=fmt(a+cr);add=cr?`+${fmt(cr)}`:"0"}else if(ok&&a!=null)out="below AD";rows[k]=[add,out]});return{isa,rows}}
function wiColdOut(){const c=wiColdCalc();
  const rows=WI_ROWS.map(([k,l])=>{const a=N((WI.alt||{})[k]);return `<tr><td>${l}</td><td><input class="wi-in" type="number" inputmode="numeric" data-wi="alt.${k}" value="${a??""}" placeholder="ft" aria-label="${l} published altitude"></td><td class="num" id="wiA_${k}">${c.rows[k][0]}</td><td class="num"><b id="wiF_${k}">${c.rows[k][1]}</b></td></tr>`}).join("");
  return `<div class="wi-isa" id="wiIsa">${c.isa}</div>
   <table class="tbl wi-tbl"><thead><tr><th>Fix</th><th>Published</th><th class="num">Corr.</th><th class="num">Fly</th></tr></thead><tbody>${rows}</tbody></table>`}
function wiHotOut(){const r=hotLook(),t=HOT[WI.fl||"t1a"];if(r.msg)return `<div class="wi-res"><span>${r.msg}</span></div>`;
  const st=WI.hotStart?new Date(WI.hotStart):null,now=Date.now();
  let timer="";if(st&&r.v){const el=Math.floor((now-WI.hotStart)/60000),lo=new Date(WI.hotStart+r.v[0]*60000),hi=new Date(WI.hotStart+r.v[1]*60000);
    timer=`<div class="wi-timer${el>=r.v[1]?" over":el>=r.v[0]?" warn":""}"><span>Started ${pad(st.getUTCHours())}${pad(st.getUTCMinutes())}Z · ${el} min ago</span><b>Window ${pad(lo.getUTCHours())}${pad(lo.getUTCMinutes())}–${pad(hi.getUTCHours())}${pad(hi.getUTCMinutes())}Z</b></div>`}
  return `<div class="wi-res${r.none?" none":""}"><small>${esc(t.name)}${r.conc?" · "+r.conc:""} · ${esc(r.band[1])}</small>
    ${r.none?`<b>No holdover time</b><span>${esc(r.why)}</span>`:`<b class="mono">${wiHM(r.v[0])} – ${wiHM(r.v[1])}</b><span>Holdover time, from the start of the final (anti-icing) fluid application.</span>`}</div>
   ${r.v?`<div class="ms-btns wi-tb"><button type="button" data-wi-act="start">${st?"Restart":"Start"} timer</button>${st?`<button type="button" data-wi-act="stop">Clear</button>`:""}</div>${timer}`:""}
   ${(r.notes||[]).map(n=>`<p class="wi-note">${esc(n)}</p>`).join("")}`}
V.winter=()=>{wiPrefill();const tabs=`<div class="chips" role="group" aria-label="Winter Ops">${[["cold","Cold temperature"],["hot","Holdover time"]].map(t=>`<button data-wi-tab="${t[0]}" aria-pressed="${wiTab===t[0]}">${t[1]}</button>`).join("")}</div>`;
  if(wiTab==="cold")return `<section class="card">${cardH("Winter Ops","Cold temperature correction")}<div class="card-b wi">${tabs}
    <div class="wi-row"><label class="f">Aerodrome<input type="text" data-wi="ad" value="${esc(WI.ad||"")}" maxlength="4" placeholder="ICAO" autocapitalize="characters"></label>
     <label class="f">Elev ft<input type="number" inputmode="numeric" data-wi="elev" value="${WI.elev??""}"></label>
     <label class="f">Temp °C<input type="number" inputmode="numeric" data-wi="tad" value="${WI.tad??""}"></label>
     <button class="btn" type="button" data-wi-act="fetch">Use METAR</button></div>
    <div id="wiOut">${wiColdOut()}</div>
    <p class="wi-note">ICAO Doc 8168 formula (matches the published cold temperature table), rounded up to the next 10 ft. Correct all published altitudes and heights on the approach (DA/MDA included) when the aerodrome temperature is below ISA and at or below 0 °C, or as your procedure requires. Tell ATC before flying corrected altitudes; don’t correct altitudes ATC assigns while vectoring without their agreement.</p></div></section>`;
  const t=HOT[WI.fl||"t1a"];
  return `<section class="card">${cardH("Winter Ops","Holdover time")}<div class="card-b wi">${tabs}
   <div class="wi-sub">Fluid</div><div class="chips" role="group">${Object.keys(HOT).map(k=>`<button data-wi-set="fl:${k}" aria-pressed="${(WI.fl||"t1a")===k}">${esc(HOT[k].name)}</button>`).join("")}</div>
   ${t.conc?`<div class="wi-sub">Concentration (fluid/water)</div><div class="chips" role="group">${t.conc.map(c=>`<button data-wi-set="conc:${c}" aria-pressed="${(WI.conc||"100/0")===c}">${c}</button>`).join("")}</div>`:""}
   <div class="wi-row one"><label class="f">Outside air temp °C<input type="number" inputmode="numeric" data-wi="oat" value="${WI.oat??""}"></label></div>
   <div class="wi-sub">Weather</div><div class="chips wi-cond" role="group">${HOT_COND.map(c=>`<button data-wi-set="cond:${c[0]}" aria-pressed="${(WI.cond||"sl")===c[0]}">${esc(c[1])}</button>`).join("")}</div>
   <div id="wiOut">${wiHotOut()}</div>
   <p class="wi-note">FAA Holdover Time Guidelines, Winter 2026–2027 (${t.tbl}, generic values). For simulation only. Times shrink in heavy precipitation, high wind or jet blast, and when the wing is colder than the air; a pre-takeoff check is still needed.</p></div></section>`};
function wiRefresh(){if(wiTab==="cold"){const c=wiColdCalc(),i=$("#wiIsa");if(i)i.textContent=c.isa;Object.keys(c.rows).forEach(k=>{const a=$("#wiA_"+k),f=$("#wiF_"+k);if(a)a.textContent=c.rows[k][0];if(f)f.textContent=c.rows[k][1]});return}const o=$("#wiOut");if(o)o.innerHTML=wiHotOut()}
document.addEventListener("input",e=>{const k=e.target.dataset&&e.target.dataset.wi;if(!k)return;const v=e.target.value;
  if(k.startsWith("alt.")){WI.alt=WI.alt||{};WI.alt[k.slice(4)]=v===""?null:+v}else if(k==="ad")WI.ad=v.toUpperCase();else WI[k]=v===""?null:+v;wiSave();wiRefresh()});
document.addEventListener("click",e=>{const t=e.target.closest("[data-wi-tab],[data-wi-set],[data-wi-act]");if(!t)return;
  if(t.dataset.wiTab){wiTab=t.dataset.wiTab;store.set("wiTab",wiTab);render();return}
  if(t.dataset.wiSet){const [k,v]=t.dataset.wiSet.split(":");WI[k]=v;wiSave();render();return}
  const a=t.dataset.wiAct;
  if(a==="start"){WI.hotStart=Date.now();wiSave();wiRefresh()}
  else if(a==="stop"){WI.hotStart=null;wiSave();wiRefresh()}
  else if(a==="fetch"){const ic=String(WI.ad||"").toUpperCase();if(!/^[A-Z0-9]{4}$/.test(ic)){toast("Enter a 4-letter ICAO code");return}if(!vam.url){toast("Set the EFB server in Settings");return}
    t.disabled=true;vamGet("/api/efb/airport?icao="+ic,15000).then(j=>{const a=j&&j.airport;if(a&&a.elevM!=null)WI.elev=Math.round(a.elevM/.3048);const m=j&&j.metar&&decodeMetar(j.metar.raw);if(m&&m.temp!=null)WI.tad=m.temp;
      if(!a&&!m)toast("No data for "+ic);wiSave();render()}).catch(err=>toast(err.message)).finally(()=>{t.disabled=false})}});
setInterval(()=>{if(cur==="winter"&&wiTab==="hot"&&WI.hotStart)wiRefresh()},30000);

/* ===== Convert: imperial / metric reference tables ===== */
let ucT=store.get("ucT","alt");
const ucR=(v,d)=>{const p=Math.pow(10,d||0);return(Math.round(v*p)/p).toLocaleString("en-US",{minimumFractionDigits:d||0,maximumFractionDigits:d||0})};
const UCT={
 alt:{name:"Metric flight levels",head:["Metres","Feet","FL","Direction"],note:"Metric cruising levels (China and others), feet rounded to the nearest 100 ft. Eastbound: track 000°–179°; westbound: 180°–359°.",
  rows:()=>{const m=[600,900,1200,1500,1800,2100,2400,2700,3000,3300,3600,3900,4200,4500,4800,5100,5400,5700,6000,6300,6600,6900,7200,7500,7800,8100,8400,8900,9200,9500,9800,10100,10400,10700,11000,11300,11600,11900,12200,12500,13100,13700,14300,14900];
   const east=new Set([900,1500,2100,2700,3300,3900,4500,5100,5700,6300,6900,7500,8100,8900,9500,10100,10700,11300,11900,12500,13700,14900]);
   return m.map(v=>{const f=Math.round(v*3.28084/100)*100;return[ucR(v),ucR(f),"FL"+String(f/100).padStart(3,"0"),east.has(v)?"East":"West"]})}},
 len:{name:"Length",head:["Metres","Feet","Metres","Feet"],note:"Runway and obstacle lengths. 1 m = 3.2808 ft.",
  rows:()=>[500,1000,1500,1800,2000,2200,2500,2800,3000,3200,3500,3800,4000,4500].map((v,i)=>{const f=[1000,2000,3000,4000,5000,6000,7000,8000,9000,10000,11000,12000,13000,15000][i];return[ucR(v),ucR(v*3.28084),ucR(f*.3048),ucR(f)]})},
 vis:{name:"Visibility · RVR",head:["Statute miles","Metres","RVR ft","RVR m"],note:"Visibility in statute miles and RVR in feet (US charts) against metres. 1 SM = 1,609 m; 1 ft = 0.3048 m.",
  rows:()=>{const sm=[["1/4",.25],["1/2",.5],["3/4",.75],["1",1],["1 1/4",1.25],["1 1/2",1.5],["2",2],["2 1/2",2.5],["3",3],["4",4],["5",5],["6",6]],rv=[300,600,1000,1200,1400,1600,1800,2000,2400,3000,4000,5000];
   return sm.map((r,i)=>[r[0],ucR(Math.round(r[1]*1609.344/10)*10),ucR(rv[i]),ucR(Math.round(rv[i]*.3048/5)*5)])}},
 spd:{name:"Speed",head:["Knots","km/h","m/s","mph"],note:"1 kt = 1.852 km/h = 0.5144 m/s.",
  rows:()=>[5,10,15,20,25,30,35,40,50,60,80,100,150,200,250,300,450,500].map(k=>[ucR(k),ucR(k*1.852),ucR(k*.514444,1),ucR(k*1.150779)])},
 dist:{name:"Distance",head:["NM","km","Statute miles","Feet"],note:"1 NM = 1.852 km = 1.1508 statute miles = 6,076 ft.",
  rows:()=>[.5,1,2,3,5,10,20,25,50,100,200,250,500,1000].map(n=>[ucR(n,n<1?1:0),ucR(n*1.852,1),ucR(n*1.150779,1),ucR(n*6076.12)])},
 tmp:{name:"Temperature",head:["°C","°F","°C","°F"],note:"°F = °C × 9/5 + 32.",
  rows:()=>{const a=[-50,-40,-30,-25,-20,-15,-10,-5,0,5,10,15];return a.map((c,i)=>{const c2=[20,25,30,35,40,45,50,55,60,65,70,75][i];return[c,ucR(c*9/5+32),c2,ucR(c2*9/5+32)]})}},
 prs:{name:"Pressure",head:["hPa","inHg","hPa","inHg"],note:"1 inHg = 33.864 hPa. Standard: 1013.25 hPa = 29.92 inHg.",
  rows:()=>{const a=[];for(let h=960;h<=1000;h+=5)a.push(h);return a.map(h=>{const h2=h+50;return[h,ucR(h/33.8639,2),h2,ucR(h2/33.8639,2)]})}},
 wt:{name:"Weight · fuel",head:["kg","lb","Litres","US gal"],note:"1 kg = 2.2046 lb. Fuel litres and US gallons at a density of 0.80 kg/L (Jet A-1 is about 0.78–0.84).",
  rows:()=>[100,500,1000,2000,5000,10000,15000,20000,30000,50000,75000,100000].map(k=>[ucR(k),ucR(k*2.20462),ucR(k/.8),ucR(k/.8/3.78541)])}};
function ucTables(){const t=UCT[ucT]||UCT.alt;
  return `<section class="card uct">${cardH("Reference","Imperial · metric tables")}<div class="card-b" style="display:grid;gap:12px">
   <div class="chips" role="group" aria-label="Table">${Object.keys(UCT).map(k=>`<button data-uct="${k}" aria-pressed="${ucT===k}">${UCT[k].name}</button>`).join("")}</div>
   <div class="uct-w"><table class="uct-t"><thead><tr>${t.head.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${t.rows().map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table></div>
   <p class="wi-note">${t.note}</p></div></section>`}
{const _vc=V.convert;V.convert=()=>_vc()+ucTables()}
document.addEventListener("click",e=>{const b=e.target.closest("[data-uct]");if(!b)return;ucT=b.dataset.uct;store.set("ucT",ucT);render()});

/* ===== Music (Polaris Sound) =====
   Polaris tracks: listed in music/tracks.json next to the EFB, e.g.
   {"tracks":[{"title":"Departure","artist":"Polaris Airways","src":"music/departure.mp3","cover":"music/departure.jpg"}]}
   Device tracks: audio files the pilot adds, kept in this browser (IndexedDB). */
const MU={list:[],local:[],idx:Math.max(0,store.get("muIdx",0)|0),shuffle:!!store.get("muShuf",false),repeat:store.get("muRep","all"),vol:+store.get("muVol",.8),loaded:false,loading:false,manifest:null};
const muA=new Audio();muA.preload="metadata";muA.volume=isFinite(MU.vol)?MU.vol:.8;
const muTracks=()=>MU.list.concat(MU.local);
const muFmt=s=>{if(!isFinite(s)||s<0)return "0:00";s=Math.floor(s);return Math.floor(s/60)+":"+pad(s%60)};
function muName(n){n=String(n||"").split("/").pop().replace(/\.[a-z0-9]{2,4}$/i,"").replace(/_/g," ").trim();const m=n.match(/^(.+?)\s+-\s+(.+)$/);return m?{artist:m[1],title:m[2]}:{artist:"",title:n||"Untitled"}}
/* IndexedDB for tracks added on this device */
function muDb(){return new Promise((res,rej)=>{try{const r=indexedDB.open("polaris-efb-music",1);r.onupgradeneeded=()=>r.result.createObjectStore("tracks",{keyPath:"id"});r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}catch(e){rej(e)}})}
async function muDbAll(){try{const db=await muDb();return await new Promise((res,rej)=>{const q=db.transaction("tracks").objectStore("tracks").getAll();q.onsuccess=()=>res(q.result||[]);q.onerror=()=>rej(q.error)})}catch(e){return []}}
async function muDbPut(rec){const db=await muDb();return new Promise((res,rej)=>{const tx=db.transaction("tracks","readwrite");tx.objectStore("tracks").put(rec);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
async function muDbDel(id){try{const db=await muDb();await new Promise(res=>{const tx=db.transaction("tracks","readwrite");tx.objectStore("tracks").delete(id);tx.oncomplete=res;tx.onerror=res})}catch(e){}}
async function muLoad(force){if(MU.loading||(MU.loaded&&!force))return;MU.loading=true;
  try{const r=await fetch("music/tracks.json",{cache:"no-store"});if(r.ok){const j=await r.json();const arr=Array.isArray(j)?j:(j.tracks||[]);
      MU.list=arr.filter(t=>t&&S(t.src)).map((t,i)=>{const n=muName(t.src);return{id:"p"+i,title:S(t.title)||n.title,artist:S(t.artist)||n.artist||"Polaris Airways",album:S(t.album)||"Polaris Sound",src:S(t.src),cover:S(t.cover),from:"polaris"}});MU.manifest="ok"}
    else MU.manifest="missing"}catch(e){MU.manifest="missing"}
  const recs=await muDbAll();MU.local.forEach(t=>{try{URL.revokeObjectURL(t.src)}catch(e){}});
  MU.local=recs.sort((a,b)=>a.added-b.added).map(r=>({id:r.id,title:r.title,artist:r.artist||"On this device",album:"This device",src:URL.createObjectURL(r.blob),cover:"",from:"device"}));
  MU.loaded=true;MU.loading=false;if(MU.idx>=muTracks().length)MU.idx=0;if(cur==="music")render();muSession()}
async function muAdd(files){let n=0;for(const f of files){if(!/^audio\//.test(f.type)&&!/\.(mp3|m4a|aac|wav|ogg|oga|flac|opus)$/i.test(f.name))continue;const nm=muName(f.name);
    try{await muDbPut({id:"d"+Date.now()+"-"+n,title:nm.title,artist:nm.artist,blob:f,added:Date.now()+n});n++}catch(e){toast("This browser couldn’t store "+f.name);}}
  if(n){toast(n+" track"+(n>1?"s":"")+" added");MU.loaded=false;await muLoad(true)}else toast("No audio files were selected")}
const muCur=()=>muTracks()[MU.idx];
function muSet(i,play){const L=muTracks();if(!L.length)return;MU.idx=(i+L.length)%L.length;store.set("muIdx",MU.idx);const t=L[MU.idx];
  if(muA.dataset.src!==t.src){muA.dataset.src=t.src;muA.src=t.src}if(play)muA.play().catch(()=>toast("Tap play to start the music"));muSession();muRefresh(true)}
function muStep(d){const L=muTracks();if(!L.length)return;if(MU.shuffle&&L.length>1){let j;do{j=Math.floor(Math.random()*L.length)}while(j===MU.idx);muSet(j,true)}else muSet(MU.idx+d,true)}
function muToggle(){if(!muTracks().length){toast("No music yet. Add tracks first.");return}if(!muA.dataset.src){muSet(MU.idx,true);return}if(muA.paused)muA.play().catch(()=>{});else muA.pause()}
muA.addEventListener("ended",()=>{if(MU.repeat==="one"){muA.currentTime=0;muA.play();return}const L=muTracks();if(MU.repeat==="off"&&!MU.shuffle&&MU.idx===L.length-1){muRefresh(true);return}muStep(1)});
muA.addEventListener("error",()=>{if(!muA.dataset.src)return;const t=muCur();toast("Couldn’t play "+(t?t.title:"this track"));});
["play","pause"].forEach(ev=>muA.addEventListener(ev,()=>{muRefresh(true);updBar();if("mediaSession" in navigator)navigator.mediaSession.playbackState=muA.paused?"paused":"playing"}));
muA.addEventListener("timeupdate",()=>muRefresh(false));muA.addEventListener("loadedmetadata",()=>muRefresh(false));
function muSession(){if(!("mediaSession" in navigator))return;const t=muCur();if(!t)return;
  try{navigator.mediaSession.metadata=new MediaMetadata({title:t.title,artist:t.artist,album:t.album,artwork:t.cover?[{src:t.cover,sizes:"512x512"}]:[]});
    navigator.mediaSession.setActionHandler("play",()=>muA.play());navigator.mediaSession.setActionHandler("pause",()=>muA.pause());
    navigator.mediaSession.setActionHandler("previoustrack",()=>muStep(-1));navigator.mediaSession.setActionHandler("nexttrack",()=>muStep(1));
    navigator.mediaSession.setActionHandler("seekto",d=>{if(d&&isFinite(d.seekTime))muA.currentTime=d.seekTime})}catch(e){}}
function muCover(t,i,big){if(t&&t.cover)return `<img src="${esc(t.cover)}" alt="" loading="lazy">`;const gid="mc"+(muCover.n=(muCover.n||0)+1);const pal=[["#1A6772","#0E3C43"],["#A78970","#6E5440"],["#3C5A73","#1D2E3D"],["#2E7D5B","#174734"]][(i||0)%4];
  return `<svg viewBox="0 0 100 100" aria-hidden="true"><defs><linearGradient id="${gid}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${pal[0]}"/><stop offset="1" stop-color="${pal[1]}"/></linearGradient></defs><rect width="100" height="100" fill="url(#${gid})"/><g fill="none" stroke="#fff" stroke-opacity=".85" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M42 64V36l24-5v28"/><circle cx="36" cy="64" r="6"/><circle cx="60" cy="59" r="6"/></g></svg>`}
function muRefresh(full){if(cur==="music"){if(full){const sc=document.querySelector("#main").scrollTop;$("#view").innerHTML=V.music();document.querySelector("#main").scrollTop=sc;return}
    const d=muA.duration,c=muA.currentTime,s=$("#muSeek");if(s&&!s._drag)s.value=isFinite(d)&&d?Math.round(c/d*1000):0;const a=$("#muT1"),b=$("#muT2");if(a)a.textContent=muFmt(c);if(b)b.textContent=isFinite(d)?"−"+muFmt(d-c):"--:--"}}
const MU_IC={play:'<path d="M8 5.5v13l11-6.5z" fill="currentColor" stroke="none"/>',pause:'<path d="M7 5h3.5v14H7zM13.5 5H17v14h-3.5z" fill="currentColor" stroke="none"/>',prev:'<path d="M18 6v12l-8.5-6zM9.5 6v12L1 12z" fill="currentColor" stroke="none" transform="translate(2 0)"/>',next:'<path d="M6 6v12l8.5-6zM14.5 6v12l8.5-6z" fill="currentColor" stroke="none" transform="translate(-2 0)"/>',
 shuffle:'<path d="M3 7h3.5c4.5 0 6.5 10 11 10H21M3 17h3.5c1.8 0 3-1.5 4.2-3.4M13.3 10.4C14.5 8.5 15.7 7 17.5 7H21M18.5 4.5L21 7l-2.5 2.5M18.5 14.5L21 17l-2.5 2.5"/>',repeat:'<path d="M4 11V9a3 3 0 0 1 3-3h13l-3-3M20 13v2a3 3 0 0 1-3 3H4l3 3"/>',vol:'<path d="M4 9.5h3.5L12 5.5v13l-4.5-4H4z" fill="currentColor"/><path d="M15.5 9a4 4 0 0 1 0 6M18 6.5a7.5 7.5 0 0 1 0 11"/>',add:'<path d="M12 5v14M5 12h14"/>',note:'<path d="M9 18V5.5l11-2V16"/><circle cx="6.5" cy="18" r="2.5"/><circle cx="17.5" cy="16" r="2.5"/>'};
const muI=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${MU_IC[k]}</svg>`;
V.music=()=>{muLoad();const L=muTracks(),t=muCur(),playing=!muA.paused&&!!muA.dataset.src;const d=muA.duration,c=muA.currentTime;
  const now=`<section class="card mu-now"><div class="mu-art${playing?" on":""}">${muCover(t,MU.idx,1)}</div>
    <div class="mu-meta"><span class="eyebrow">${t?(playing?"Now playing":"Ready")+" · "+esc(t.album):"Polaris Sound"}</span><h2>${t?esc(t.title):"No music yet"}</h2><p>${t?esc(t.artist):"Add Polaris tracks to the site, or add files from this device."}</p></div>
    <div class="mu-prog"><input type="range" id="muSeek" min="0" max="1000" value="${isFinite(d)&&d?Math.round(c/d*1000):0}" aria-label="Seek"${t?"":" disabled"}><div class="mu-times"><span id="muT1">${muFmt(c)}</span><span id="muT2">${isFinite(d)?"−"+muFmt(d-c):"--:--"}</span></div></div>
    <div class="mu-ctl"><button data-mu="shuffle" aria-pressed="${MU.shuffle}" aria-label="Shuffle">${muI("shuffle")}</button><button data-mu="prev" aria-label="Previous track">${muI("prev")}</button><button class="mu-play" data-mu="play" aria-label="${playing?"Pause":"Play"}">${muI(playing?"pause":"play")}</button><button data-mu="next" aria-label="Next track">${muI("next")}</button><button data-mu="repeat" aria-pressed="${MU.repeat!=="off"}" aria-label="Repeat: ${MU.repeat}">${muI("repeat")}${MU.repeat==="one"?'<b class="one">1</b>':""}</button></div>
    <div class="mu-vol">${muI("vol")}<input type="range" id="muVol" min="0" max="100" value="${Math.round(muA.volume*100)}" aria-label="Volume"></div></section>`;
  const row=(t,i)=>`<div class="mu-row${i===MU.idx?" cur":""}"><button class="mu-pick" data-mutrack="${i}" aria-label="Play ${esc(t.title)}"><span class="mu-th">${muCover(t,i)}${i===MU.idx&&playing?'<span class="eq"><i></i><i></i><i></i></span>':""}</span><span class="mu-tt"><b>${esc(t.title)}</b><small>${esc(t.artist)}</small></span></button><span class="pill ${t.from==="polaris"?"c-cyan":""}" style="${t.from==="polaris"?"":"color:var(--bronze)"}">${t.from==="polaris"?"Polaris":"Device"}</span>${t.from==="device"?`<button class="btn sm" data-mudel="${esc(t.id)}" aria-label="Remove ${esc(t.title)}">Remove</button>`:""}</div>`;
  const lib=`<section class="card">${cardH("Library · "+L.length+" track"+(L.length===1?"":"s"),"Polaris Sound",`<label class="btn sm pri" style="cursor:pointer">${muI("add").replace('<svg','<svg style="width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:2"')}Add from device<input type="file" id="muFile" accept="audio/*,.mp3,.m4a,.aac,.wav,.ogg,.flac,.opus" multiple hidden></label>`)}
    ${!MU.loaded?`<div class="empty">Loading music…</div>`:L.length?L.map(row).join(""):`<div class="mu-empty">${muI("note")}<h3>Your hangar is quiet</h3><p class="note">Polaris tracks appear here once the site has a <span class="mono">music/tracks.json</span> list. You can also add audio files from this device; they stay in this browser only.</p></div>`}
    ${MU.loaded&&MU.manifest==="missing"&&L.length?`<div class="card-f">No Polaris playlist on this site yet. Showing tracks from this device.</div>`:""}</section>`;
  return `<div class="mu">${now}${lib}</div>`};
document.addEventListener("click",e=>{const t=e.target.closest("button");if(!t)return;
  if(t.dataset.mu){const a=t.dataset.mu;if(a==="play")muToggle();else if(a==="prev"){if(muA.currentTime>3)muA.currentTime=0;else muStep(-1)}else if(a==="next")muStep(1);
    else if(a==="shuffle"){MU.shuffle=!MU.shuffle;store.set("muShuf",MU.shuffle);muRefresh(true)}else if(a==="repeat"){MU.repeat=MU.repeat==="all"?"one":MU.repeat==="one"?"off":"all";store.set("muRep",MU.repeat);toast("Repeat "+(MU.repeat==="all"?"all":MU.repeat==="one"?"one track":"off"));muRefresh(true)}return}
  if(t.dataset.mutrack){const i=+t.dataset.mutrack;if(i===MU.idx&&muA.dataset.src)muToggle();else muSet(i,true);return}
  if(t.dataset.mudel){const id=t.dataset.mudel;const L=muTracks();const wasCur=muCur()&&muCur().id===id;if(wasCur){muA.pause();muA.removeAttribute("src");delete muA.dataset.src;muA.load()}
    muDbDel(id).then(()=>{MU.loaded=false;return muLoad(true)}).then(()=>{if(MU.idx>=muTracks().length)MU.idx=0;toast("Track removed");muRefresh(true)});return}
});
document.addEventListener("input",e=>{const t=e.target;if(t.id==="muSeek"){const d=muA.duration;if(isFinite(d))muA.currentTime=t.value/1000*d;return}
  if(t.id==="muVol"){muA.volume=t.value/100;store.set("muVol",muA.volume)}});
document.addEventListener("change",e=>{if(e.target.id==="muFile"&&e.target.files.length){muAdd([...e.target.files]);e.target.value=""}});
document.addEventListener("pointerdown",e=>{if(e.target.id==="muSeek")e.target._drag=true});document.addEventListener("pointerup",()=>{const s=$("#muSeek");if(s)s._drag=false});
setTimeout(()=>muLoad(),1200);

/* Home screen "Now Playing" widget (phone page 3) */
function muWidget(){const t=muCur(),on=!!muA.dataset.src&&!muA.paused;
  return `<div class="w w-m w-mu"><a class="muw-l" href="#music" aria-label="Open Music"><span class="muw-cv">${muCover(t,MU.idx,1)}</span><span class="muw-t"><small>${on?"NOW PLAYING":"POLARIS SOUND"}</small><b>${esc(t?t.title:"No music yet")}</b><span>${esc(t?t.artist:"Add tracks in Music")}</span></span></a>
   <span class="muw-c"><button data-mu="prev" aria-label="Previous track">${muI("prev")}</button><button class="muw-p" data-mu="play" aria-label="${on?"Pause":"Play"}">${muI(on?"pause":"play")}</button><button data-mu="next" aria-label="Next track">${muI("next")}</button></span></div>`}
["play","pause","emptied"].forEach(ev=>muA.addEventListener(ev,()=>{if(!cur)renderHome()}));

/* ===== OFP document =====
   The operational flight plan exactly as SimBrief prints it (the plan_html in the loaded OFP), on paper or at night,
   with bigger or smaller type, find in page, and the PDF one tap away. The HTML is cleaned before it is shown:
   no scripts, frames, forms or event handlers, only plain web links and images. */

const OD={pen:false,tool:"pen",col:store.get("odInkCol","red")||"red",undo:[],pencil:!!store.get("odPencil",false),finger:store.get("odFinger",null)||(store.get("odPencil",false)?"scroll":"write"),fs:+store.get("odFs",13)||13,night:store.get("odNight",null),q:"",hits:0,at:0,cacheId:null,html:""};
const odNight=()=>OD.night!=null?!!OD.night:isDark();
function odClean(raw){try{const doc=new DOMParser().parseFromString(String(raw||""),"text/html");
    doc.querySelectorAll("script,style,iframe,frame,object,embed,form,input,button,link,meta,base,svg,math,template").forEach(n=>n.remove());
    doc.body.querySelectorAll("*").forEach(n=>{[...n.attributes].forEach(a=>{const k=a.name.toLowerCase(),v=a.value.trim();
      if(k.startsWith("on")||k==="style"&&/expression|url\(/i.test(v)||k==="srcset")n.removeAttribute(a.name);
      else if((k==="href"||k==="src")&&!/^https?:\/\//i.test(v))n.removeAttribute(a.name)});
      if(n.tagName==="A"){n.setAttribute("target","_blank");n.setAttribute("rel","noopener noreferrer")}
      if(n.tagName==="IMG"){n.setAttribute("loading","lazy");n.setAttribute("referrerpolicy","no-referrer")}});
    return doc.body.innerHTML}catch(e){return ""}}
function odHtml(){const id=O().id;if(OD.cacheId!==id){OD.cacheId=id;OD.undo=[];const t=ofp.text||{};OD.html=t.plan_html?odClean(S(t.plan_html)):""}return OD.html}
const odPdf=()=>ofp.files&&S(ofp.files.directory)&&ofp.files.pdf&&S(ofp.files.pdf.link)?S(ofp.files.directory)+S(ofp.files.pdf.link):"";
V.ofpdoc=()=>{if(ofp._sample)return `<div style="padding:24px 16px;max-width:760px;margin:0 auto">${sampleNote()}</div>`;
  const x=O(),h=odHtml(),pdf=odPdf();
  return `<div class="od ${odNight()?"night":""} ${OD.pen?"inking":""}" id="odRoot" style="--odfs:${OD.fs}px;--odfsn:${OD.fs}">
    <div class="od-bar"><div class="od-t"><span class="eyebrow">OFP · ${esc(x.id)}</span><b>${esc(x.flight)} · ${esc(S(x.o.icao_code))} → ${esc(S(x.d.icao_code))}</b></div>
      <div class="od-tools"><div class="od-find"><input type="search" id="odQ" placeholder="Find in OFP" value="${esc(OD.q)}" autocomplete="off" spellcheck="false"><span id="odN" class="od-n"></span>
        <button class="btn sm" data-od="prev" aria-label="Previous match">‹</button><button class="btn sm" data-od="next" aria-label="Next match">›</button></div>
        <button class="btn sm" data-od="smaller" aria-label="Smaller text">A−</button><button class="btn sm" data-od="bigger" aria-label="Bigger text">A+</button>
        <button class="btn sm" data-od="night" aria-pressed="${odNight()}">Night</button><button class="btn sm od-penb" data-od="pen" aria-pressed="${OD.pen}">${OD_PEN_ICON}Pen</button>${pdf?`<a class="btn sm" href="${esc(pdf)}" target="_blank" rel="noopener">PDF ↗</a>`:""}</div>${odInkBar()}</div>
    <div class="od-scroll" id="odScroll"><div class="od-paper"><div class="od-host" id="odHost"><div id="odPaper">${h||`<p class="od-none">This OFP has no printed plan in it. ${pdf?"Open the PDF instead.":"Fetch it again from SimBrief in Flight › Download."}</p>`}</div>${h?odInkSvg():""}</div></div></div></div>`};
/* find: mark every match in the text, step through them */
function odFind(q,step){const paper=document.getElementById("odPaper");if(!paper)return;
  if(q!==OD.q||step==null){OD.q=q;paper.querySelectorAll("mark.odm").forEach(m=>{m.replaceWith(document.createTextNode(m.textContent))});paper.normalize();OD.hits=0;OD.at=0;
    if(q&&q.length>=2){const re=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),"gi"),w=document.createTreeWalker(paper,NodeFilter.SHOW_TEXT),nodes=[];while(w.nextNode())nodes.push(w.currentNode);
      nodes.forEach(t=>{const s=t.nodeValue;if(!re.test(s))return;re.lastIndex=0;const f=document.createDocumentFragment();let last=0,m;
        while((m=re.exec(s))){f.appendChild(document.createTextNode(s.slice(last,m.index)));const mk=document.createElement("mark");mk.className="odm";mk.textContent=m[0];f.appendChild(mk);last=m.index+m[0].length;OD.hits++}
        f.appendChild(document.createTextNode(s.slice(last)));t.replaceWith(f)})}}
  const ms=[...paper.querySelectorAll("mark.odm")];if(step)OD.at=(OD.at+step+ms.length)%Math.max(1,ms.length);
  ms.forEach((m,i)=>m.classList.toggle("cur",i===OD.at));if(ms[OD.at])ms[OD.at].scrollIntoView({block:"center",behavior:step?"smooth":"auto"});
  const n=document.getElementById("odN");if(n)n.textContent=q&&q.length>=2?(ms.length?(OD.at+1)+" / "+ms.length:"No match"):""}
document.addEventListener("input",e=>{if(e.target.id==="odQ")odFind(e.target.value.trim(),null)});
document.addEventListener("keydown",e=>{if(e.target.id==="odQ"&&e.key==="Enter"){e.preventDefault();odFind(e.target.value.trim(),e.shiftKey?-1:1)}});
document.addEventListener("click",e=>{const b=e.target.closest("[data-od]");if(!b)return;const a=b.dataset.od,root=document.getElementById("odRoot");
  if(a==="next"||a==="prev"){odFind(OD.q,a==="next"?1:-1);return}
  if(a==="bigger"||a==="smaller"){odSetFs(OD.fs+(a==="bigger"?1:-1));return}
  if(a==="night"){OD.night=!odNight();store.set("odNight",OD.night);if(root)root.classList.toggle("night",OD.night);b.setAttribute("aria-pressed",String(OD.night))}});
/* pinch or ctrl + wheel on the page changes the type size too */
document.addEventListener("wheel",e=>{if(!e.ctrlKey||!e.target.closest("#odScroll"))return;e.preventDefault();odSetFs(OD.fs+(e.deltaY<0?1:-1))},{passive:false});
function odSetFs(n){OD.fs=Math.max(9,Math.min(24,n));store.set("odFs",OD.fs);const r=document.getElementById("odRoot");if(r){r.style.setProperty("--odfs",OD.fs+"px");r.style.setProperty("--odfsn",OD.fs)}}

/* ===== Pen: write on the OFP =====
   Ink is kept per OFP (the last 12) in this browser. Points are stored in units of the type size, so the marks stay on
   their line when the text is made bigger or smaller. With an Apple Pencil, the pencil writes and a finger scrolls. */
const OD_PEN_ICON='<svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true" style="margin-right:4px;vertical-align:-2px"><path d="M4 20l1-4L16 5l3 3L8 19z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg>';
const OD_COL={red:"#E0342B",blue:"#1E6FD9",green:"#1E9A52",ink:"currentColor"},OD_HL="#FFD21F";
const odInkAll=()=>store.get("odInk",{})||{};
function odInk(){const id=O().id,a=odInkAll()[id];return a&&Array.isArray(a.s)?a.s:[]}
function odInkSave(list){const all=odInkAll(),id=O().id;if(list.length)all[id]={t:Date.now(),s:list};else delete all[id];
  const ids=Object.keys(all).sort((a,b)=>all[b].t-all[a].t);ids.slice(12).forEach(k=>delete all[k]);store.set("odInk",all)}
function odPathD(p){if(!p.length)return"";if(p.length===1)return`M${p[0][0]} ${p[0][1]}l.001 0`;let d=`M${p[0][0]} ${p[0][1]}`;
  for(let i=1;i<p.length-1;i++){const mx=((p[i][0]+p[i+1][0])/2).toFixed(2),my=((p[i][1]+p[i+1][1])/2).toFixed(2);d+=`Q${p[i][0]} ${p[i][1]} ${mx} ${my}`}
  const L=p[p.length-1];return d+`L${L[0]} ${L[1]}`}
function odStrokeEl(k){const hl=k.h;return `<path d="${odPathD(k.p)}" stroke="${hl?OD_HL:(OD_COL[k.c]||OD_COL.red)}" stroke-width="${hl?1.05:.13}" ${hl?'opacity=".38" stroke-linecap="butt"':'stroke-linecap="round"'} stroke-linejoin="round" fill="none"/>`}
function odInkSvg(){return `<svg class="od-ink" id="odInk" aria-hidden="true"${OD.finger==="scroll"?' style="touch-action:auto"':""}><g>${odInk().map(odStrokeEl).join("")}</g></svg>`}
function odInkBar(){const cols=Object.keys(OD_COL).map(c=>`<button class="od-sw ${c}" data-odink="col:${c}" aria-label="${c==="ink"?"Black":c[0].toUpperCase()+c.slice(1)}" aria-pressed="${OD.tool==="pen"&&OD.col===c}"><i style="background:${c==="ink"?"var(--pink)":OD_COL[c]}"></i></button>`).join("");
  return `<div class="od-inkbar" role="toolbar" aria-label="Pen">${cols}
    <button class="btn sm" data-odink="hl" aria-pressed="${OD.tool==="hl"}"><i class="od-hlchip"></i>Highlight</button>
    <button class="btn sm" data-odink="erase" aria-pressed="${OD.tool==="erase"}">Eraser</button>
    <span class="od-sep"></span><button class="btn sm" data-odink="undo">Undo</button><button class="btn sm" data-odink="clear" id="odInkClear">Clear all</button>
    <span class="od-sep"></span><span class="od-fl">Finger</span><div class="od-seg" role="group" aria-label="What one finger does"><button class="btn sm" data-odink="f:write" aria-pressed="${OD.finger==="write"}">Writes</button><button class="btn sm" data-odink="f:scroll" aria-pressed="${OD.finger==="scroll"}">Scrolls</button></div>
    <span class="od-hint">${OD.finger==="scroll"?(OD.pencil?"Pencil writes · finger scrolls":"Finger scrolls · use a Pencil or mouse to write"):"One finger writes · two fingers scroll"}</span></div>`}
function odSetFinger(f){OD.finger=f;store.set("odFinger",f);const svg=document.getElementById("odInk");if(svg)svg.style.touchAction=f==="scroll"?"auto":"";odInkBarRedraw()}
function odInkRedraw(){const g=document.querySelector("#odInk g");if(g)g.innerHTML=odInk().map(odStrokeEl).join("")}
function odInkBarRedraw(){const b=document.querySelector(".od-inkbar");if(b)b.outerHTML=odInkBar()}
/* drawing */
let odDraw=null;
/* with fingers on the page: one finger writes, two fingers scroll (and pinch for type size), like a notes app */
const odTP=new Map();let odPan=null;
function odMid(){const v=[...odTP.values()].slice(0,2);return{x:(v[0].x+v[1].x)/2,y:(v[0].y+v[1].y)/2,d:Math.hypot(v[0].x-v[1].x,v[0].y-v[1].y)}}
function odPanStart(){const sc=document.getElementById("odScroll");if(!sc)return;if(odPan&&odPan.raf)cancelAnimationFrame(odPan.raf);const m=odMid();
  odPan={sc,m,d:m.d,t:performance.now(),vx:0,vy:0,raf:0}}
function odPanMove(){const P=odPan;if(!P||odTP.size<2)return;const m=odMid(),now=performance.now(),dt=Math.max(1,now-P.t),dx=m.x-P.m.x,dy=m.y-P.m.y;
  P.sc.scrollLeft-=dx;P.sc.scrollTop-=dy;P.vx=.8*(dx/dt)+.2*P.vx;P.vy=.8*(dy/dt)+.2*P.vy;P.m=m;P.t=now;
  /* pinch: one step of type size per 14% change in finger spread */
  const k=m.d/P.d;if(k>1.14||k<.88){const top=P.sc.scrollTop/Math.max(1,P.sc.scrollHeight),f=OD.fs;odSetFs(OD.fs+(k>1?1:-1));P.d=m.d;if(OD.fs!==f)P.sc.scrollTop=top*P.sc.scrollHeight}}
function odPanEnd(){const P=odPan;if(!P)return;if(odTP.size)return;/* wait for every finger to lift before writing again */
  let vx=P.vx,vy=P.vy,last=performance.now();if(performance.now()-P.t>80){odPan=null;return}
  const step=now=>{const dt=now-last;last=now;const f=Math.exp(-dt/325);P.sc.scrollLeft-=vx*dt;P.sc.scrollTop-=vy*dt;vx*=f;vy*=f;
    if(Math.hypot(vx,vy)>.02&&odPan===P)P.raf=requestAnimationFrame(step);else if(odPan===P)odPan=null};P.raf=requestAnimationFrame(step)}
function odPt(ev){const h=document.getElementById("odHost").getBoundingClientRect();return[+((ev.clientX-h.left)/OD.fs).toFixed(2),+((ev.clientY-h.top)/OD.fs).toFixed(2)]}
function odErase(pt){const list=odInk(),r=.55;let hit=-1;
  for(let i=list.length-1;i>=0&&hit<0;i--){const k=list[i],rr=r+(k.h?.5:.07),p=k.p;
    for(let j=0;j<p.length;j++){const a=p[j],b=p[j+1]||a,dx=b[0]-a[0],dy=b[1]-a[1],L=dx*dx+dy*dy,t=L?Math.max(0,Math.min(1,((pt[0]-a[0])*dx+(pt[1]-a[1])*dy)/L)):0;
      if(Math.hypot(a[0]+t*dx-pt[0],a[1]+t*dy-pt[1])<rr){hit=i;break}}}
  if(hit<0)return;const k=list.splice(hit,1)[0];OD.undo.push({a:"del",k,i:hit});odInkSave(list);odInkRedraw()}
document.addEventListener("pointerdown",ev=>{const svg=ev.target.closest&&ev.target.closest("#odInk");if(!svg||!OD.pen)return;
  /* the first time a Pencil writes, a finger goes back to scrolling (the pilot can change it back) */
  if(ev.pointerType==="pen"&&!OD.pencil){OD.pencil=true;store.set("odPencil",true);if(!store.get("odFinger",null))odSetFinger("scroll")}
  if(ev.pointerType==="touch"&&OD.finger==="scroll")return;
  if(ev.button>0)return;
  if(ev.pointerType==="touch"){odTP.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});try{svg.setPointerCapture(ev.pointerId)}catch(e){}
    /* a second finger: drop the stroke the first one just started and move the page with both */
    if(odTP.size>=2){ev.preventDefault();if(odDraw){if(odDraw.el)odDraw.el.remove();if(odDraw.raf)cancelAnimationFrame(odDraw.raf);odDraw=null}odPanStart();return}
    if(odPan)return}ev.preventDefault();try{svg.setPointerCapture(ev.pointerId)}catch(e){}
  if(OD.tool==="erase"){odDraw={id:ev.pointerId,erase:true};odErase(odPt(ev));return}
  const k={c:OD.col,h:OD.tool==="hl",p:[odPt(ev)]},g=svg.querySelector("g");g.insertAdjacentHTML("beforeend",odStrokeEl(k));odDraw={id:ev.pointerId,k,el:g.lastElementChild,raf:0}});
document.addEventListener("pointermove",ev=>{if(odTP.has(ev.pointerId)){odTP.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});if(odPan){ev.preventDefault();odPanMove();return}}
  if(!odDraw||ev.pointerId!==odDraw.id)return;ev.preventDefault();
  const evs=ev.getCoalescedEvents?ev.getCoalescedEvents():[ev];
  if(odDraw.erase){(evs.length?evs:[ev]).forEach(e=>odErase(odPt(e)));return}
  const p=odDraw.k.p;(evs.length?evs:[ev]).forEach(e=>{const q=odPt(e),l=p[p.length-1];if(Math.hypot(q[0]-l[0],q[1]-l[1])>=.06)p.push(q)});
  if(!odDraw.raf)odDraw.raf=requestAnimationFrame(()=>{if(odDraw&&odDraw.el){odDraw.el.setAttribute("d",odPathD(odDraw.k.p));odDraw.raf=0}})},{passive:false});
function odDrawEnd(ev){if(odTP.has(ev.pointerId)){odTP.delete(ev.pointerId);if(odPan){if(odTP.size<2)odPanEnd();return}}
  if(!odDraw||ev.pointerId!==odDraw.id)return;const d=odDraw;odDraw=null;if(d.raf)cancelAnimationFrame(d.raf);if(d.erase)return;
  const k=d.k;/* a highlighter stroke that is nearly level is laid flat on the line */
  if(k.h&&k.p.length>1){const a=k.p[0],b=k.p[k.p.length-1],ys=k.p.map(q=>q[1]);if(Math.abs(b[0]-a[0])>1.5&&Math.max(...ys)-Math.min(...ys)<.9){const y=+(ys.reduce((s,v)=>s+v,0)/ys.length).toFixed(2);k.p=[[a[0],y],[b[0],y]]}}
  const list=odInk();list.push(k);OD.undo.push({a:"add"});odInkSave(list);if(d.el)d.el.outerHTML=odStrokeEl(k)}
document.addEventListener("pointerup",odDrawEnd);document.addEventListener("pointercancel",odDrawEnd);
/* iPad: keep the Apple Pencil from scrolling the page while it writes */
/* iOS starts its own scroll from a touch even under touch-action:none inside a scrolling box, and then cancels the
   pointer (the stroke stops after a few points). Cancelling the touch events themselves is what holds the page still:
   always for the Pencil, for fingers when a finger writes (two fingers are scrolled here, by hand), and for every touch
   while a stroke is being drawn (a resting palm). */
const odOnInk=e=>OD.pen&&e.target&&e.target.closest&&e.target.closest("#odInk");
const odHold=e=>[...e.changedTouches,...e.touches].some(t=>t.touchType==="stylus")||OD.finger==="write"||!!odDraw||!!(odPan&&odTP.size);
document.addEventListener("touchstart",e=>{if(odOnInk(e)&&odHold(e))e.preventDefault()},{passive:false});
document.addEventListener("touchmove",e=>{if((odOnInk(e)&&odHold(e))||(OD.pen&&odDraw))e.preventDefault()},{passive:false});
/* toolbar */
document.addEventListener("click",e=>{const pb=e.target.closest('[data-od="pen"]');
  if(pb){OD.pen=!OD.pen;const root=document.getElementById("odRoot");if(root)root.classList.toggle("inking",OD.pen);pb.setAttribute("aria-pressed",String(OD.pen));
    const svg=document.getElementById("odInk");if(svg)svg.style.touchAction=OD.finger==="scroll"?"auto":"";return}
  const b=e.target.closest("[data-odink]");if(!b)return;const a=b.dataset.odink;
  if(a.startsWith("f:")){odSetFinger(a.slice(2));return}
  if(a.startsWith("col:")){OD.tool="pen";OD.col=a.slice(4);store.set("odInkCol",OD.col)}
  else if(a==="hl"||a==="erase")OD.tool=OD.tool===a?"pen":a;
  else if(a==="undo"){const u=OD.undo.pop(),list=odInk();if(!u)return;
    if(u.a==="add")list.pop();else if(u.a==="del")list.splice(Math.min(u.i,list.length),0,u.k);else if(u.a==="clear")list.push(...u.list);odInkSave(list);odInkRedraw();return}
  else if(a==="clear"){const list=odInk();if(!list.length)return;
    if(!b.dataset.arm){b.dataset.arm="1";b.textContent="Tap again to clear";setTimeout(()=>{if(b.isConnected){delete b.dataset.arm;b.textContent="Clear all"}},3000);return}
    OD.undo.push({a:"clear",list:list.slice()});odInkSave([]);odInkRedraw();odInkBarRedraw();return}
  odInkBarRedraw()});

/* ===== Briefing summary in Flight Plan → Overview =====
   The plan at a glance, laid out like the SimBrief briefing: flight info, the plan summary and the load sheet, with a
   banner for whatever limits the payload (the estimated weight that reaches its maximum). */
function bsSigned(v,w){if(v==null||v===""||isNaN(+v))return"—";v=Math.round(+v);return(v<0?"M":"P")+String(Math.abs(v)).padStart(w||2,"0")}
function bsDate(sec){if(!sec)return"—";const d=new Date(sec*1000);return String(d.getUTCDate()).padStart(2,"0")+" "+["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][d.getUTCMonth()]+" "+String(d.getUTCFullYear()).slice(2)}
function briefSummary(){const x=O(),g=x.g,p=ofp.params||{},tm=ofp.times||{},wt=ofp.weights||{},f=ofp.fuel||{},atc=ofp.atc||{},u=x.unit.toLowerCase();
  const st=(k,v,warn)=>`<div><dt>${k}</dt><dd>${v}${warn?' <span class="bs-warn" title="At its limit">!</span>':""}</dd></div>`;
  const ap=a=>esc(S(a.icao_code)||"—")+(S(a.iata_code)?" <small>/ "+esc(S(a.iata_code))+"</small>":"");
  const kg=v=>N(v)?fmt(N(v))+" <small>"+u+"</small>":"—";
  const gen=N(p.time_generated);let genS="";if(gen){const d=new Date(gen*1000);genS=d.getUTCDate().toString().padStart(2,"0")+" "+["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][d.getUTCMonth()]+" "+d.getUTCFullYear()+" at "+utcHM(gen)}
  /* what is at its maximum: landing, takeoff or zero fuel weight */
  const lim=[["MLW",wt.est_ldw,wt.max_ldw],["MTOW",wt.est_tow,wt.max_tow],["MZFW",wt.est_zfw,wt.max_zfw]].filter(r=>N(r[2])&&N(r[1])>=N(r[2])-1).map(r=>r[0]);
  const bag=N(wt.bag_weight)||(N(wt.bag_count)&&N(wt.bag_weight_ea)?N(wt.bag_count)*N(wt.bag_weight_ea):0);
  const wind=S(g.avg_wind_dir)!==""?String(Math.round(N(g.avg_wind_dir))).padStart(3,"0")+" / "+Math.round(N(g.avg_wind_spd)):"—";
  const etops=S(g.is_etops);
  return `<div class="bs-banners">${genS?`<div class="bs-ban info">${ICO_I}This briefing was generated on ${genS}.</div>`:""}${lim.length?`<div class="bs-ban warn">${ICO_I}Payload/cargo limited by ${lim.join(" and ")}</div>`:""}</div>
  <section class="card">${cardH("Briefing","Flight info")}<dl class="stats">
    ${st("Flight number",esc(x.flight))}${st("Callsign",esc(S(atc.callsign)||x.flight))}${st("Departure",ap(x.o))}${st("Arrival",ap(x.d))}${st("Alternate",ap(x.a))}${st("Aircraft",esc(S(x.ac.name)||S(x.ac.icaocode)||"—"))}
    ${st("Departure date",bsDate(N(tm.sched_out)))}${st("Departure time",utcHM(N(tm.sched_out)))}${st("Arrival time",utcHM(N(tm.sched_in)))}${st("Air time",hhmm(N(tm.est_time_enroute)))}${st("Block time",hhmm(N(tm.sched_block)||N(tm.est_block)))}${st("Airframe",esc(S(x.ac.reg)||"—"))}</dl></section>
  <section class="card">${cardH("Briefing","Flight plan summary")}<dl class="stats">
    ${st("Initial altitude",N(g.initial_altitude)?fmt(N(g.initial_altitude))+" <small>ft</small>":"—")}${st("Cruise profile",esc(S(g.cruise_profile)||(S(g.costindex)?"CI "+S(g.costindex):"—")))}${st("Route distance",fmt(N(g.route_distance)||N(g.air_distance))+" <small>nm</small>")}${st("Average wind",wind)}${st("Wind component",bsSigned(g.avg_wind_comp,3))}${st("ISA deviation",bsSigned(g.avg_temp_dev))}
    ${st("Release number",esc(S(g.release)||"—"))}${st("AIRAC cycle",esc(S(p.airac)||"—"))}${st("OFP layout",esc(S(p.ofp_layout)||"—"))}${st("Units",x.unit)}${st("Navlog",x.fixes.length?"Yes":"No")}${st("ETOPS",/^(1|true|yes)$/i.test(etops)?"Yes":"No")}</dl></section>
  <section class="card">${cardH("Briefing",`Load sheet <small class="bs-u">all weights in ${x.unit}</small>`)}<dl class="stats">
    ${st("Enroute burn",kg(f.enroute_burn))}${st("Passengers",fmt(N(wt.pax_count)))}${st("Empty weight",kg(wt.oew))}${st("Estimated ZFW",kg(wt.est_zfw),lim.includes("MZFW"))}${st("Estimated TOW",kg(wt.est_tow),lim.includes("MTOW"))}${st("Estimated LW",kg(wt.est_ldw),lim.includes("MLW"))}
    ${st("Block fuel",kg(f.plan_ramp))}${st("Baggage",bag?kg(bag):"—")}${st("Payload",kg(wt.payload))}${st("Max ZFW",kg(wt.max_zfw))}${st("Max TOW",kg(wt.max_tow))}${st("Max LW",kg(wt.max_ldw))}</dl></section>`}
const ICO_I='<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" stroke-width="2"/><path d="M12 7.5v6M12 16.2v.3" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>';
{const _s=ofpSummary;ofpSummary=function(){const h=_s();if(ofp._sample)return h;
  /* the summary replaces the short stats card under the route */
  const k=h.indexOf('<section class="card"><dl class="stats">'),e=k<0?-1:h.indexOf("</section>",k);
  return k<0?h+briefSummary():h.slice(0,k)+briefSummary()+h.slice(e+10)}}

/* ===== Airline =====
   The EFB is Polaris Airways'. (A second airline's theme, 海岸航空, was here and has been taken out for now; its code
   and artwork are kept in _archive/airline-eim.js for when it comes back.) AL() gives the airline's names. */
const AIRLINES={paw:{name:"Polaris Airways",efb:"Polaris EFB",base:"Polaris base",theme:"#1A6772"}};
function AL(){return AIRLINES.paw}
function applyAirline(){document.documentElement.dataset.airline="paw";const m=document.querySelector('meta[name="theme-color"]');if(m)m.content=AIRLINES.paw.theme;document.title="Polaris Airways EFB"}
/* a device that had the other theme picked goes back to Polaris */
try{if(store.get("airline","paw")!=="paw")store.set("airline","paw")}catch(e){}
applyAirline();

/* ---------- VATSIM live traffic ----------
   Every pilot connected to VATSIM. Read from the EFB server (/api/efb/vatsim: the network feed cut to about a fifth,
   routes left out and fetched for one pilot when picked); if the server doesn't have that yet, straight from the
   network's public feed (data.vatsim.net, readable from the browser). Fetched every 20 s while the map is open with the layer on, never while the page is hidden. The aircraft are
   stamped on the map canvas from pre-drawn pictures, so two thousand of them pan and zoom smoothly; a tap picks the nearest one and shows its
   flight. Polaris callsigns (PAW) stand out in the Polaris colour; a flight that the Polaris traffic layer already shows
   (vAMSYS) is drawn only once, there. Zoomed out, aircraft on the ground are left out. */
