const NP_LEG={VA:"Heading to altitude",CA:"Course to altitude",FA:"From fix to altitude",VI:"Heading to intercept",CI:"Course to intercept",VM:"Heading, vectors",FM:"From fix, vectors",DF:"Direct",TF:"Track",CF:"Course",IF:"Start",RF:"Arc",AF:"DME arc",HM:"Hold",HA:"Hold to altitude",HF:"Hold",PI:"Procedure turn",VD:"Heading to DME",CD:"Course to DME",FD:"From fix to DME",VR:"Heading to radial",CR:"Course to radial"};

