{const _ac=appChrome;appChrome=function(id){const r=_ac.apply(this,arguments);if(id==="mail")screenEl.dataset.layout="split";return r}}
{const i=PAGE1.indexOf("timer");PAGE1.splice(i<0?PAGE1.length:i,0,"mail");PAGE3.unshift("mail")}
