const mailSave=(k,set)=>store.set(k,[...set]);
const mailUnread=()=>{if(!MAIL.list)return 0;const rd=mailSet("mailRead"),tr=mailSet("mailTrash");return MAIL.list.filter(m=>(!m.conv||m.inbox)&&!rd.has(m.id)&&!tr.has(m.id)).length};
/* who this EFB is comes from the pilot's sign-in (pilotauth.js): the server picks the messages meant for them */
function mailQuery(){return ""}
