const updNewer=(a,b)=>!!a&&!!b&&a!==b&&(a>b||(b.slice(0,2)==="12"&&a.slice(0,2)==="01"));
async function updCheck(force){if(UPD.busy||!EFB_BUILD||!/^https?:/.test(location.protocol))return;if(!force&&Date.now()-UPD.at<600000)return;UPD.busy=true;if(cur==="prefs")render();
  try{const r=await fetch(location.pathname+"?u="+Date.now(),{cache:"no-store"});if(!r.ok)throw new Error("HTTP "+r.status);
    let txt="";const rd=r.body&&r.body.getReader?r.body.getReader():null;
    if(rd){const dec=new TextDecoder();while(txt.length<65536){const {value,done}=await rd.read();if(done)break;txt+=dec.decode(value,{stream:true});if(/name="efb-build"[^>]*>/.test(txt))break}try{rd.cancel()}catch(e){}}else txt=await r.text();
    const m=txt.match(/<meta name="efb-build" content="([^"]+)"/);UPD.err=null;UPD.build=m&&updNewer(m[1],EFB_BUILD)?m[1]:null}
  catch(e){UPD.err=/fetch|network|load/i.test((e&&e.message)||"")?"Can’t reach the EFB site":(e&&e.message)||"Couldn’t check"}
  finally{UPD.busy=false;UPD.at=Date.now();renderHome();if(cur==="prefs")render();
    if(UPD.build&&UPD.alerted!==UPD.build&&notiGet().upd&&!(typeof dndActive==="function"&&dndActive())&&window.__islOn&&window.__islOn()&&window.islAlert&&cur!=="prefs"){UPD.alerted=UPD.build;
      islAlert({app:"Software Update",short:"Update ready",icon:`<span class="isx-ic" style="width:24px;height:24px;border-radius:6px;background:${APPS.prefs.bg};color:${APPS.prefs.fg}"><svg viewBox="0 0 24 24">${APPS.prefs.g}</svg></span>`,title:"A new Polaris EFB is ready",sub:"Tap to update now · build "+UPD.build,ms:8000,tap:updApply})}}}
function updApply(){if(!UPD.build)return;try{sessionStorage.setItem("pefb:updFrom",EFB_BUILD)}catch(e){}location.replace(location.pathname+"?v="+encodeURIComponent(UPD.build)+location.hash)}
setTimeout(()=>updCheck(),20000);setInterval(()=>{if(!document.hidden)updCheck()},60000);
document.addEventListener("visibilitychange",()=>{if(!document.hidden&&Date.now()-UPD.at>300000)updCheck(true)});
{const _b=badge;badge=function(id){if(id==="prefs"&&UPD.build)return `<span class="badge" aria-label="Update available">1</span>`;return _b(id)}}
/* after an update, say so once */
setTimeout(()=>{let f=null;try{f=sessionStorage.getItem("pefb:updFrom");sessionStorage.removeItem("pefb:updFrom")}catch(e){}if(f&&f!==EFB_BUILD)toast("Updated to build "+EFB_BUILD)},1500);

/* --- Notification choices, one place for all of them */
const notiGet=()=>Object.assign({mail:true,sound:false,upd:true},store.get("noti",{}));
const notiSet=(k,v)=>{const n=notiGet();n[k]=v;store.set("noti",n)};
let stAC=null;
/* a soft two-note chime, made on the spot (no sound file) */
function stChime(){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;stAC=stAC||new AC();const c=stAC,t=c.currentTime;if(c.state==="suspended")c.resume();
  [[880,0],[1318.5,.14]].forEach(([f,d])=>{const o=c.createOscillator(),g=c.createGain();o.type="sine";o.frequency.value=f;g.gain.setValueAtTime(0,t+d);g.gain.linearRampToValueAtTime(.18,t+d+.02);g.gain.exponentialRampToValueAtTime(.0001,t+d+.55);o.connect(g).connect(c.destination);o.start(t+d);o.stop(t+d+.6)})}
document.addEventListener("click",e=>{const b=e.target.closest("[data-noti-mail],[data-noti-sound],[data-noti-upd],[data-noti-test]");if(!b)return;
  if(b.dataset.notiTest!=null){stChime();return}
  const k=b.dataset.notiMail!=null?"mail":b.dataset.notiSound!=null?"sound":"upd";const v=(b.dataset.notiMail||b.dataset.notiSound||b.dataset.notiUpd)==="1";notiSet(k,v);if(k==="sound"&&v)stChime();render()});

/* --- Connection: the internet, the Polaris EFB server (health, with its response time), vAMSYS, VATSIM, radar and mail */
const CONN={srv:null,busy:false,at:0};
async function connTest(force){if(CONN.busy||(!force&&Date.now()-CONN.at<60000))return;CONN.busy=true;if(cur==="prefs")render();
  if(!vam.url)CONN.srv={ok:false,err:"No server address set"};
  else{const t0=performance.now(),ac=new AbortController(),tm=setTimeout(()=>ac.abort(),12000);
    try{const r=await fetch(vam.url.replace(/\/+$/,"")+"/api/efb/health",{cache:"no-store",signal:ac.signal});const j=await r.json().catch(()=>({}));
      CONN.srv={ok:r.ok&&j.ok!==false,ms:Math.round(performance.now()-t0),configured:j.configured,openaip:j.openaip,err:r.ok?null:"HTTP "+r.status}}
    catch(e){CONN.srv={ok:false,err:e&&e.name==="AbortError"?"No answer in 12 s":"Can’t reach the server"}}finally{clearTimeout(tm)}}
  CONN.busy=false;CONN.at=Date.now();if(cur==="prefs")render()}
window.addEventListener("online",()=>{connTest(true)});window.addEventListener("offline",()=>{if(cur==="prefs")render()});
const ago=ms=>{const s=Math.max(0,Math.round((Date.now()-ms)/1000));return s<60?s+" s ago":s<3600?Math.round(s/60)+" min ago":Math.round(s/3600)+" h ago"};
function connSummary(){if(!navigator.onLine)return["Offline","r"];if(CONN.srv&&!CONN.srv.ok)return["Server down","r"];if(CONN.srv&&CONN.srv.ok)return["Connected","g"];return["Online","g"]}

/* --- The pilot on VATSIM: found in the same network list the map uses, by CID, or by the flight plan's callsign */
function vsMe(){if(!VS.list)return null;const cid=String(store.get("vatsimCid","")).trim();
  if(cid)return VS.list.find(p=>String(p.cid)===cid)||null;
  let cs="";try{cs=ofp._sample?"":String((O().g&&O().g.callsign)||O().flight||"").toUpperCase().replace(/\s+/g,"")}catch(e){}
  return cs?VS.list.find(p=>p.c===cs)||null:null}
function vsWant(){if(!VS.loading&&!document.hidden&&Date.now()-VS.at>(VS.err?60000:20000))vsLoad()}
let vsSeen=0;setInterval(()=>{if(cur!=="prefs"||document.hidden)return;if(psec==="vatsim"||psec==="conn")vsWant();
  if(VS.at!==vsSeen){vsSeen=VS.at;const a=document.activeElement;if(!(a&&a.id==="stCid"))render()}},2000);
document.addEventListener("change",e=>{if(e.target.id!=="stCid")return;const v=e.target.value.replace(/\D/g,"");store.set("vatsimCid",v);if(v&&!VS.list)vsWant();render()});
document.addEventListener("keydown",e=>{if(e.target.id==="stCid"&&e.key==="Enter")e.target.blur()});
document.addEventListener("click",e=>{const b=e.target.closest("[data-vsme]");if(!b)return;const me=vsMe();if(!me)return;
  ML.vatsim=true;try{store.set("mapL",ML)}catch(x){}MAP.c={lat:me.la,lon:me.lo};MAP.z=Math.max(MAP.z||0,8.5);if(typeof mapFollowSet==="function")mapFollowSet(false);MAP.sel={t:"vs",id:me.c};goApp("map")});

/* ===== Device settings: Airplane Mode, Do Not Disturb (by hand, or while airborne), screen dimming and night light,
   accessibility, SimBrief auto-fetch, and map defaults. Settings > their sections draw the controls (views.js). ===== */

/* --- Airplane Mode: background network jobs pause (mail, VATSIM, update checks, connection tests); everything the
   pilot asks for by hand still works, and so do the flight plan, charts, weather and the live flight. */
const apmOn=()=>store.get("apm",false)===true;
{const _m=mailLoad;mailLoad=function(force){if(apmOn()&&!force)return;return _m.apply(this,arguments)}}
{const _t=vsTick;vsTick=function(){if(apmOn())return;return _t.apply(this,arguments)}}
{const _w=vsWant;vsWant=function(){if(apmOn())return;return _w.apply(this,arguments)}}
{const _u=updCheck;updCheck=function(force){if(apmOn()&&!force)return;return _u.apply(this,arguments)}}
{const _c=connTest;connTest=function(force){if(apmOn()&&!force)return;return _c.apply(this,arguments)}}
function apmSet(on){store.set("apm",!!on);sbIcons();toast(on?"Airplane Mode on · background updates paused":"Airplane Mode off");if(!on){mailLoad(true);updCheck(true);connTest(true)}render()}

/* --- Do Not Disturb: by hand, or automatically while the pilot's own flight is airborne (vAMSYS live flight, or the
   pilot found on VATSIM). Mail and update alerts are held and summed up after landing; checklist alerts still come. */
const DND={held:[],was:false};
function inFlight(){try{const f=CLP.flight;if(f&&CLP.match!==false){const ph=String(CLP.why||f.phase||"");if(/climb|cruise|descent|final|takeoff|airborne|en.?route/i.test(ph))return true;if(+f.altitude>2500&&+f.groundspeed>120)return true}}catch(e){}
  try{const me=vsMe();if(me&&me.g>120&&me.a>2500)return true}catch(e){}return false}
const dndActive=()=>store.get("dnd",false)===true||(store.get("dndFlight",true)!==false&&inFlight());
function dndHold(list){list.forEach(m=>{if(!DND.held.some(h=>h.id===m.id))DND.held.push({id:m.id,subject:m.subject})});sbIcons()}
setInterval(()=>{const a=dndActive();if(a!==DND.was){DND.was=a;sbIcons();if(cur==="prefs")render()}
  if(!a&&DND.held.length){const n=DND.held.length,s=DND.held[0].subject;DND.held=[];
    if(window.__islOn&&window.__islOn()&&window.islAlert)islAlert({app:"Mail",short:n+" while flying",icon:`<span class="isx-ic" style="width:24px;height:24px;border-radius:6px;background:${APPS.mail.bg};color:#fff"><svg viewBox="0 0 24 24">${APPS.mail.g}</svg></span>`,
      title:n>1?n+" messages arrived during your flight":"A message arrived during your flight",sub:s,ms:7000,tap:()=>goApp("mail")});else toast((n>1?n+" messages":"A message")+" arrived during your flight")}
  /* with a CID and in-flight Do Not Disturb, look for the pilot on VATSIM once a minute */
  if(store.get("dndFlight",true)!==false&&store.get("vatsimCid","")&&!apmOn()&&!document.hidden&&!VS.loading&&Date.now()-VS.at>60000)vsLoad()},15000);
document.addEventListener("click",e=>{const b=e.target.closest("[data-apm],[data-dnd],[data-dnd-flight]");if(!b)return;
  if(b.dataset.apm!=null){apmSet(b.dataset.apm==="1");return}
  if(b.dataset.dnd!=null)store.set("dnd",b.dataset.dnd==="1");else store.set("dndFlight",b.dataset.dndFlight==="1");DND.was=dndActive();sbIcons();render()});

/* status bar: an aeroplane instead of the Wi-Fi mark in Airplane Mode, and a moon while Do Not Disturb holds alerts */
const SB_PL='<svg viewBox="0 0 24 24" class="sbx"><path d="M21 16v-2l-8-5V3.5a1.5 1.5 0 0 0-3 0V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5z"/></svg>',
  SB_MO='<svg viewBox="0 0 24 24" class="sbx"><path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5z"/></svg>';
function sbIcons(){const r=document.querySelector(".statusbar>span:last-child");if(!r)return;let x=r.querySelector(".sbx-w");if(!x){x=document.createElement("span");x.className="sbx-w";r.insertBefore(x,r.firstChild)}
  const wifi=x.nextElementSibling;x.innerHTML=(dndActive()?SB_MO:"")+(apmOn()?SB_PL:"");if(wifi&&wifi.tagName==="svg")wifi.style.display=apmOn()?"none":""}
setTimeout(sbIcons,0);

/* --- Brightness: a dimming layer below the iPad's own lowest brightness, and a warm or red night light */
const dimLv=()=>Math.max(0,Math.min(70,+store.get("dim",0)||0)),nightLt=()=>store.get("nightLt","off");
function dimApply(){let t=$("#stTint"),d=$("#stDim");if(!d){t=document.createElement("div");t.id="stTint";d=document.createElement("div");d.id="stDim";[t,d].forEach(el=>{el.setAttribute("aria-hidden","true");screenEl.appendChild(el)})}
  const n=nightLt();t.style.display=n==="off"?"none":"";t.style.background=n==="red"?"rgb(255,52,26)":"rgb(255,196,138)";d.style.background=`rgba(0,0,0,${dimLv()/100})`;d.style.display=dimLv()?"":"none"}
setTimeout(dimApply,0);
document.addEventListener("input",e=>{if(e.target.id!=="stDimR")return;store.set("dim",100-(+e.target.value));dimApply();const o=$("#stDimV");if(o)o.textContent=e.target.value+"%"});   /* the slider is brightness: right is brighter, as on iPad */
document.addEventListener("click",e=>{const b=e.target.closest("[data-nightlt]");if(!b)return;store.set("nightLt",b.dataset.nightlt);dimApply();render()});

/* --- Accessibility: larger text (zooms the reading apps only; the map, charts and the pen-on-OFP keep 1:1 so touch and
   drawing stay exact), bold text, more contrast, less motion */
const A11Y_APPS=["ofp","wx","checklist","winter","convert","perf","load","logbook","simbrief","prefs","mail","_navlog","_oooi"];
function a11yApply(){const h=document.documentElement,ts=store.get("textSize","m");h.dataset.ts=ts;h.classList.toggle("a11y-bold",store.get("boldText",false)===true);
  h.classList.toggle("a11y-hc",store.get("hiContrast",false)===true);h.classList.toggle("a11y-rm",store.get("lessMotion",false)===true);
  screenEl.dataset.zoomok=A11Y_APPS.includes(cur)?"1":"0"}
{const _ac=appChrome;appChrome=function(id){const r=_ac.apply(this,arguments);screenEl.dataset.zoomok=A11Y_APPS.includes(id)?"1":"0";return r}}
setTimeout(a11yApply,0);window.addEventListener("hashchange",()=>setTimeout(a11yApply,0));
document.addEventListener("click",e=>{const b=e.target.closest("[data-textsize],[data-boldtext],[data-hicontrast],[data-lessmotion]");if(!b)return;
  if(b.dataset.textsize)store.set("textSize",b.dataset.textsize);if(b.dataset.boldtext)store.set("boldText",b.dataset.boldtext==="1");
  if(b.dataset.hicontrast)store.set("hiContrast",b.dataset.hicontrast==="1");if(b.dataset.lessmotion)store.set("lessMotion",b.dataset.lessmotion==="1");a11yApply();render()});

/* --- Flight Operations: SimBrief account in one place, and an optional fetch of the newest plan when the EFB opens */
async function sbFetchQuiet(manual){const u=String(store.get("sbUser","")).trim();if(!u){if(manual)toast("Enter your SimBrief username first");return}
  if(manual)toast("Fetching your latest SimBrief plan…");
  try{const j=await fetch(sbHref(u)).then(r=>r.json());if(!j||!j.origin||!j.destination||(j.fetch&&S(j.fetch.status)&&S(j.fetch.status)!=="Success")){if(manual)toast("SimBrief didn’t return a plan for that account");return}
    const id=j.params&&(j.params.request_id||j.params.time_generated),curId=!ofp._sample&&ofp.params&&(ofp.params.request_id||ofp.params.time_generated);
    if(id&&curId&&String(id)===String(curId)){if(manual)toast("You already have your latest plan");return}
    ofp=j;CL=buildCL();store.set("ofp",j);MAP.c=null;DL3.sel="plan";SBMAN.on=false;ofpTab="sum";store.set("ofpTab","sum");render();ciOfpSync();toast("Loaded your latest plan: "+O().flight+" "+S(j.origin.icao_code)+"–"+S(j.destination.icao_code))}
  catch(e){if(manual){SBMAN.on=true;toast("SimBrief can’t be reached from here. Paste or upload the plan in Flight › Download.")}}}
setTimeout(()=>{if(store.get("sbAuto",false)===true&&!apmOn())sbFetchQuiet(false)},2500);
document.addEventListener("change",e=>{if(e.target.id==="stSb"){store.set("sbUser",e.target.value.trim());render()}});
document.addEventListener("click",e=>{const b=e.target.closest("[data-sbauto],[data-sbnow]");if(!b)return;if(b.dataset.sbnow!=null){sbFetchQuiet(true);return}store.set("sbAuto",b.dataset.sbauto==="1");render()});

/* --- Navigation: the map's base map, layers and opening behaviour, set from Settings */
document.addEventListener("click",e=>{const b=e.target.closest("[data-nvbase],[data-nvl],[data-nvfollow]");if(!b)return;
  if(b.dataset.nvbase)ML.base=b.dataset.nvbase;
  else if(b.dataset.nvl){const k=b.dataset.nvl;ML[k]=b.dataset.v==="1"}
  else store.set("mapFollowOpen",b.dataset.nvfollow==="1");
  store.set("mapL",ML);render()});
