  const grp=(t,L,none)=>`<div class="dl-g"><div class="dl-gh">${t}</div>${L.length?L.map(dlRow).join(""):`<p class="note">${none}</p>`}</div>`;
  return grp("Departure · "+esc(ci.from),dep,"No datalink offered at "+esc(ci.from)+" right now. Request your clearance by voice.")
    +grp("Arrival · "+esc(ci.to),arr,"No datalink offered at "+esc(ci.to)+" right now.")
