V.timer=()=>{let body="";
  if(clockTab==="world")body=`<h2 class="ck-title">World Clock</h2><div id="wcList">${worldRows()}</div>`;
  else if(clockTab==="sw"){const run=!!tmr.start,ms=swMs();
    body=`<span class="sw-dig" id="swDig">${swFmt(ms)}</span><div class="ck-btns"><button class="cbtn grey" id="swLap"${!run&&!ms?" disabled":""}>${run||!ms?"Lap":"Reset"}</button><button class="cbtn ${run?"red":"green"}" id="swStart">${run?"Stop":"Start"}</button></div><div class="laps">${lapsHtml()}</div>`}
  else{const active=cd.end!=null||cd.remain!=null;
    if(!active){const h=Math.floor(cd.dur/3600),m=Math.floor(cd.dur%3600/60),sc=cd.dur%60;
      body=`<div class="cd-pick"><label><input type="number" id="cdH" min="0" max="23" value="${h}" aria-label="Hours">hr</label><label><input type="number" id="cdM" min="0" max="59" value="${m}" aria-label="Minutes">min</label><label><input type="number" id="cdS" min="0" max="59" value="${sc}" aria-label="Seconds">sec</label></div>
      <div class="cd-pre">${[1,3,5,10,20,30].map(n=>`<button data-preset="${n*60}">${n} min</button>`).join("")}</div>
      <div class="ck-btns"><button class="cbtn grey" disabled>Cancel</button><button class="cbtn green" id="cdStart">Start</button></div>`}
    else{const t=cdLeft(),run=cd.end!=null,endAt=new Date(Date.now()+t*1000);
      body=`<div class="cd-ring"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="45" fill="none" stroke="var(--ck-line)" stroke-width="3"/><circle id="cdArc" cx="50" cy="50" r="45" fill="none" stroke="var(--ck-orange)" stroke-width="3" stroke-linecap="round" stroke-dasharray="283" stroke-dashoffset="${283*(1-t/Math.max(1,cd.total||cd.dur))}"/></svg>
       <div class="in"><span class="cd-dig" id="cdDig">${cdFmt(t)}</span><span class="cd-end">${run?"Ends at "+pad(endAt.getHours())+":"+pad(endAt.getMinutes()):"Paused"}</span></div></div>
       <div class="ck-btns"><button class="cbtn grey" id="cdCancel">Cancel</button><button class="cbtn ${run?"orange":"green"}" id="cdPause">${run?"Pause":"Resume"}</button></div>`}}
  const tabs=[["world","World Clock",'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3.2 3 14.8 0 18M12 3c-3 3.2-3 14.8 0 18"/>'],["sw","Stopwatch",'<circle cx="12" cy="13.5" r="8"/><path d="M12 9.5v4M10 2.5h4"/>'],["cd","Timer",'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>']];
  return `<div class="clk"><div class="ck-body">${body}</div><nav class="ck-tabs" aria-label="Clock sections">${tabs.map(t=>`<button data-ctab="${t[0]}" aria-pressed="${clockTab===t[0]}"><svg viewBox="0 0 24 24" aria-hidden="true">${t[2]}</svg>${t[1]}</button>`).join("")}</nav></div>`};
