const TOOLS={
 checklist:()=>`<div class="seg" role="group" aria-label="Checklist type"><button data-clmode="normal" aria-pressed="${clMode==="normal"}">Normal</button><button data-clmode="nn" aria-pressed="${clMode==="nn"}">Non-normal</button></div>`,
 perf:()=>{const m=pfDs?"ds":pfState().mode;return `<div class="seg" role="group" aria-label="Performance"><button data-pfmode="to" aria-pressed="${m==="to"}">Takeoff</button><button data-pfmode="ld" aria-pressed="${m==="ld"}">Landing</button><button data-pfmode="ds" aria-pressed="${m==="ds"}">Descent</button></div>`},
 ofp:()=>ofp._sample?`<a class="btn sm hide-n" href="#simbrief">No plan · Load yours</a>`:(O().pdf?`<a class="btn sm hide-n" href="${esc(O().pdf)}" target="_blank" rel="noopener">OFP PDF ↗</a>`:""),
 load:()=>`<button class="btn sm" data-ldact="reset">Reset to OFP</button>`
};
function appChrome(id){const fl=isFl(id),a=fl?APPS.flight:APPS[id];$("#appTitle").textContent=fl?FLV[id][0]:a.name;const ic=$("#navIc");ic.style.background=a.bg;ic.style.color=a.fg;ic.innerHTML=`<svg viewBox="0 0 24 24">${a.g}</svg>`;
  screenEl.dataset.app=id;screenEl.dataset.layout=LAYOUT[id]||"page";screenEl.classList.toggle("ft-on",fl);if(fl)store.set("ftLast",id)}
function updBar(){$("#wake").hidden=!wl;const mm=$("#muMini");if(mm){const on=typeof muA!=="undefined"&&!muA.paused&&cur!=="music"&&!(window.__islOn&&window.__islOn());mm.hidden=!on;if(on){const t=muCur();mm.innerHTML=`<span class="eq"><i></i><i></i><i></i></span><span>${esc(t?t.title:"Music")}</span>`;mm.setAttribute("aria-label","Now playing: "+(t?t.title:"music"))}}if(!cur)return;const x=O();$("#navEyebrow").textContent=(EYEBROW[cur]||(()=>""))(x);const th=(TOOLS[cur]||(()=>""))();$("#navTools").innerHTML=th;screenEl.classList.toggle("no-tools",!th.trim())}
function tick(){const d=new Date();
  $("#sbTime").textContent=pad(d.getHours())+":"+pad(d.getMinutes());
  $("#sbDate").textContent=d.toLocaleDateString("en-US",{weekday:"short",day:"numeric",month:"short"});
  $("#utc").textContent=pad(d.getUTCHours())+":"+pad(d.getUTCMinutes())+":"+pad(d.getUTCSeconds());
  tickHome();cdCheck();if(cur==="timer")updateTimer();if(cur==="map")mapLoadAll()}
function render(){
  renderHome();
  if(cur){const sc=[...document.querySelectorAll("#view .side,#view .detail")].map(e=>e.scrollTop);$("#view").innerHTML=V[cur]();document.querySelectorAll("#view .side,#view .detail").forEach((e,i)=>{if(sc[i])e.scrollTop=sc[i]});if(["perf","convert"].includes(cur))calcTools();if(cur==="timer")updateTimer();
    if(cur==="map"){mapBind();requestAnimationFrame(()=>{drawMap();updMapNote();mapInfo()});mapLoadAll()}
    if(cur==="charts"&&CH.doc)requestAnimationFrame(chRender);}
  updBar();
}
function originOf(el){const r=el.getBoundingClientRect(),s=screenEl.getBoundingClientRect();
  if(r.right<s.left||r.left>s.right||!r.width)return null;return{x:r.left-s.left+r.width/2,y:r.top-s.top+r.height/2}}
function setOrigin(o){const s=screenEl.getBoundingClientRect();o=o||{x:s.width/2,y:s.height/2};win.style.transformOrigin=`${o.x}px ${o.y}px`}
function route(){
  let h=location.hash.slice(1);if(h==="taxi"){location.replace("#map");return}if(h==="descent"){pfDs=true;store.set("pfDs",true);location.replace("#perf");return}if(h==="_navlog"||h==="_oooi")h=h.slice(1);if(h==="navlog"||h==="oooi"){ofpTab=h;store.set("ofpTab",h);location.replace("#ofp");return}
  if(h==="flight"){location.replace("#"+ftLast());return}if(h==="ofp"){DL3.sel="plan";location.replace("#simbrief");return}
  const next=(APPS[h]||isFl(h))&&typeof V[h]==="function"?h:null;const prev=cur;
  if(next===prev){render();return}
  cur=next;pendingDel=null;pendingReset=null;
  if(next){
    {const rid=isFl(next)?"flight":next;if(!DOCK.includes(rid))store.set("recents",[rid,...store.get("recents",[]).filter(i=>i!==rid)].slice(0,3))}
    appChrome(next);screenEl.classList.add("in-app");$("#home").inert=true;root.style.setProperty("--sbg","var(--bar)");
    render();$("#main").scrollTop=0;
    if(prev==null){win.hidden=false;win.classList.remove("closing","opening");
      if(!reduced()&&openOrigin){setOrigin(openOrigin);void win.offsetWidth;win.classList.add("opening")}}
    openOrigin=null;
  }else{
    screenEl.classList.remove("in-app");$("#home").inert=false;root.style.setProperty("--sbg","var(--wp0)");render();
    if(reduced()){win.hidden=true;return}
    const ic=document.querySelector(`#home [data-app="${isFl(prev)?"flight":prev}"] .icon`);setOrigin(ic&&originOf(ic));
    win.classList.remove("opening");void win.offsetWidth;win.classList.add("closing");
  }
}
win.addEventListener("animationend",()=>{if(win.classList.contains("closing")){win.classList.remove("closing");if(!cur)win.hidden=true}win.classList.remove("opening")});
function goApp(id){if(location.hash==="#"+id)route();else location.hash=id}
function goHome(){if(cur)location.hash="home";else goPage(0)}
function loadOfp(obj){
  if(obj&&typeof obj==="object"&&obj.fetch&&S(obj.fetch.status)&&S(obj.fetch.status)!=="Success"){toast("SimBrief: "+S(obj.fetch.status));return false}
  if(!obj||typeof obj!=="object"||!obj.origin||!obj.destination){toast("That doesn’t look like a SimBrief JSON plan");return false}
  ofp=obj;CL=buildCL();store.set("ofp",obj);MAP.c=null;DL3.sel="plan";SBMAN.on=false;ofpTab="sum";store.set("ofpTab","sum");ciOfpSync();toast("Loaded "+O().flight+" "+S(obj.origin.icao_code)+"–"+S(obj.destination.icao_code));goApp("ofp");return true}

