/* ===== Performance + Loadsheet (graphic pages, Fenix-style) ===== */
const ACDB={
 A21N:{name:"A321neo",mtow:97000,mlw:79200,mzfw:75600,oew:50800,dowCg:27,mac:4.29,cabin:[6.2,38],
  J:{rows:5,ab:[2,2],pitch:1.55},Y:{rows:29,ab:[3,3]},holds:[["FWD",-7.4,5670],["AFT",6.3,7350],["BULK",9.6,1500]],
  tanks:{wing:6250,ctr:6440,xw:-0.25,xc:-1.0},env:[[15,47000],[17,60000],[24,97000],[36,97000],[40,80000],[40,47000]],
  wmin:40000,wmax:100000,cmin:10,cmax:46,ld:{LOW:2050,MED:1500,MAX:1200},ldRef:70000,vref:131,
  toBase:1950,toRef:89000,v2:146,flexMax:68,flaps:["1+F","2","3"],ldFlaps:["3","FULL"],ths:[[17,2.5],[40,-1.5]]},
 A359:{name:"A350-900",mtow:283000,mlw:207000,mzfw:195700,oew:142400,dowCg:29,mac:10.8,cabin:[7.5,58],
  J:{rows:8,ab:[1,2,1],pitch:1.85},Y:{rows:29,ab:[3,3,3]},holds:[["FWD",-11,20000],["AFT",12,16000],["BULK",17,2800]],
  tanks:{wing:37500,ctr:35500,xw:-0.6,xc:-2.2},env:[[16,130000],[18,200000],[26,283000],[38,283000],[42,220000],[42,130000]],
  wmin:120000,wmax:290000,cmin:10,cmax:47,ld:{LOW:2350,MED:1750,MAX:1450},ldRef:190000,vref:138,
  toBase:2550,toRef:268000,v2:158,flexMax:65,flaps:["1+F","2","3"],ldFlaps:["3","FULL"],ths:[[18,2],[42,-2]]}
};
function acType(){const c=S(O().ac.icaocode).toUpperCase();if(/^A35/.test(c))return"A359";return"A21N"}
function AC(){return ACDB[acType()]}
const KGLB=2.20462;const toKg=v=>O().unit==="LB"?v/KGLB:v;const fromKg=v=>O().unit==="LB"?v*KGLB:v;
const ft=m=>m*3.28084,mtr=f=>f/3.28084;

/* runway database fallback (ft): ident -> [length, heading] */
const RWY_DB={
 KSFO:{"28L":[11870,284],"10R":[11870,104],"28R":[11381,284],"10L":[11381,104],"01R":[8650,14],"19L":[8650,194],"01L":[7650,14],"19R":[7650,194]},
 KSEA:{"16L":[11901,163],"34R":[11901,343],"16C":[9426,163],"34C":[9426,343],"16R":[8500,163],"34L":[8500,343]},
 KPDX:{"10R":[11000,101],"28L":[11000,281],"10L":[9825,101],"28R":[9825,281],"03":[6000,31],"21":[6000,211]}
};
function hav(a,b){const R=6371000,r=Math.PI/180,dl=(b[1]-a[1])*r,dn=(b[0]-a[0])*r;const h=Math.sin(dl/2)**2+Math.cos(a[1]*r)*Math.cos(b[1]*r)*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
function brg(a,b){const r=Math.PI/180,y=Math.sin((b[0]-a[0])*r)*Math.cos(b[1]*r),x=Math.cos(a[1]*r)*Math.sin(b[1]*r)-Math.sin(a[1]*r)*Math.cos(b[1]*r)*Math.cos((b[0]-a[0])*r);return(Math.atan2(y,x)/r+360)%360}
/* list runways for an airport: SimBrief TLR first, then built-in table, then OSM geometry */
function runwaysFor(icao,kind){const out={};
  const tl=ofp.tlr&&ofp.tlr[kind==="to"?"takeoff":"landing"];
  if(tl&&S((tl.conditions||{}).airport_icao).toUpperCase()===icao){let rs=tl.runway;if(rs&&!Array.isArray(rs))rs=[rs];(rs||[]).forEach(r=>{const id=S(r.identifier);if(!id)return;
    const L=kind==="to"?(N(r.length_tora)||N(r.length)):(N(r.length_lda)||N(r.length));if(L)out[id]={len:L,hdg:N(r.magnetic_course)||rwyHdg(id),src:"SimBrief"}})}
  const db=RWY_DB[icao];if(db)Object.keys(db).forEach(id=>{if(!out[id])out[id]={len:db[id][0],hdg:db[id][1],src:"database"}});
  const tx=TX.data[icao];if(tx&&tx.runways)tx.runways.filter(r=>!r.area&&!r.stopway&&r.ref&&r.pts.length>1).forEach(r=>{const a=r.pts[0],b=r.pts[r.pts.length-1];const L=Math.round(ft(hav(a,b))/10)*10;const ends=r.ref.split("/");
    if(ends.length===2){const h=brg(a,b);const lo=+ends[0].replace(/\D/g,"")*10;const fwd=Math.abs(((h-lo+540)%360)-180)<90;const e0=fwd?ends[0]:ends[1],e1=fwd?ends[1]:ends[0];
      if(!out[e0])out[e0]={len:L,hdg:Math.round(fwd?h:(h+180)%360),src:"OpenStreetMap"};if(!out[e1])out[e1]={len:L,hdg:Math.round(fwd?(h+180)%360:h),src:"OpenStreetMap"}}});
  return out}

/* ---------- Loadsheet ---------- */
function seed(s){let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return()=>{h=Math.imul(h^h>>>15,2246822507);h=Math.imul(h^h>>>13,3266489909);return((h^=h>>>16)>>>0)/4294967296}}
function seatLayout(ac){const units=ac.J.rows*ac.J.pitch+ac.Y.rows,u=(ac.cabin[1]-ac.cabin[0])/units;const seats=[];let x=ac.cabin[0];
  [["J",ac.J,ac.J.pitch],["Y",ac.Y,1]].forEach(([c,def,p])=>{for(let r=0;r<def.rows;r++){const cx=x+(r+.5)*p*u;let col=0;def.ab.forEach((n,g)=>{for(let k=0;k<n;k++)seats.push({c,x:cx,g,k,col:col++,n:def.ab.reduce((a,b)=>a+b,0)})})}x+=def.rows*p*u});
  return seats}
function ldState(){const x=O(),ac=AC(),wt=ofp.weights||{},key="ld:"+x.id;let s=store.get(key,null);
  if(!s||s.ac!==acType()){const pax=Math.round(N(wt.pax_count)||0);const seats=seatLayout(ac);const capJ=seats.filter(q=>q.c==="J").length,capY=seats.length-capJ;
    let J=Math.min(capJ,Math.round(pax*capJ/seats.length));let Y=Math.min(capY,pax-J);
    const pw=N(wt.pax_weight)||(x.unit==="LB"?220:100);const cargo=Math.max(0,N(wt.cargo)!=null?N(wt.cargo):(N(wt.payload)||0)-pax*pw);
    const ch=ac.holds;const capT=ch[0][2]+ch[1][2];
    s={ac:acType(),J,Y,pw,fwd:Math.round(cargo*ch[0][2]/capT),aft:Math.round(cargo*ch[1][2]/capT),bulk:0,fuel:N((ofp.fuel||{}).plan_takeoff)||0,ramp:N((ofp.fuel||{}).plan_ramp)||0};
    store.set(key,s)}return s}
function fuelSplit(kg,ac){const w=Math.min(kg,ac.tanks.wing*2);return{l:w/2,r:w/2,c:Math.max(0,kg-w)}}
function ldCalc(){const x=O(),ac=AC(),s=ldState(),wt=ofp.weights||{};
  const seats=seatLayout(ac);const rnd=seed(x.id);const order=seats.map((q,i)=>({i,r:rnd()}));
  const fill=new Set();["J","Y"].forEach(c=>{const list=order.filter(o=>seats[o.i].c===c).sort((a,b)=>a.r-b.r);list.slice(0,s[c]).forEach(o=>fill.add(o.i))});
  const pwKg=toKg(s.pw);const xs=seats.map(q=>q.x);const full=xs.reduce((a,b)=>a+b,0)/xs.length;const lemac=full-0.31*ac.mac;
  const arm=xm=>(xm-lemac)/ac.mac*100;
  const oewKg=(N(wt.oew)!=null?toKg(N(wt.oew)):(N(wt.est_zfw)!=null&&N(wt.payload)!=null?toKg(N(wt.est_zfw)-N(wt.payload)):ac.oew));
  let W=oewKg,M=oewKg*ac.dowCg;seats.forEach((q,i)=>{if(fill.has(i)){W+=pwKg;M+=pwKg*arm(q.x)}});
  const hold=[["fwd",0],["aft",1],["bulk",2]];hold.forEach(([k,i])=>{const m=toKg(s[k]||0);W+=m;M+=m*(ac.holds[i][1]/ac.mac*100+31)});
  const zfw=W,zcg=M/W;const fArm={w:ac.tanks.xw/ac.mac*100+31,c:ac.tanks.xc/ac.mac*100+31};
  const withFuel=f=>{const sp=fuelSplit(f,ac);const m=(sp.l+sp.r)*fArm.w+sp.c*fArm.c;return{w:zfw+f,cg:(zfw*zcg+m)/(zfw+f)}};
  const tof=toKg(s.fuel),lf=toKg(N((ofp.fuel||{}).plan_landing)||Math.max(0,s.fuel-(N((ofp.fuel||{}).enroute_burn)||0)));
  const to=withFuel(tof),lw=withFuel(lf);
  return{ac,s,seats,fill,zfw,zcg,tow:to.w,tcg:to.cg,lw:lw.w,lcg:lw.cg,tof,cargo:toKg((s.fwd||0)+(s.aft||0)+(s.bulk||0)),pax:s.J+s.Y}}
function inEnv(ac,cg,w){const e=ac.env;const half=e.length/2;const fwd=e.slice(0,half),aft=e.slice(half).reverse();
  const lim=(arr,w)=>{for(let i=0;i<arr.length-1;i++){const [c1,w1]=arr[i],[c2,w2]=arr[i+1];if(w>=Math.min(w1,w2)&&w<=Math.max(w1,w2))return c1+(c2-c1)*(w-w1)/((w2-w1)||1)}return null};
  const f=lim(fwd,w),a=lim(aft,w);return f!=null&&a!=null&&cg>=f&&cg<=a}
function envSvg(L){const ac=L.ac,W=380,H=300,l=46,r=12,t=14,b=34;const X=c=>l+(c-ac.cmin)/(ac.cmax-ac.cmin)*(W-l-r),Y=w=>t+(1-(w-ac.wmin)/(ac.wmax-ac.wmin))*(H-t-b);
  let g="";const step=(ac.wmax-ac.wmin)>100000?20000:10000;
  for(let c=Math.ceil(ac.cmin/5)*5;c<=ac.cmax;c+=5)g+=`<line class="env-grid" x1="${X(c)}" x2="${X(c)}" y1="${t}" y2="${H-b}"/><text class="env-ax" x="${X(c)}" y="${H-b+14}" text-anchor="middle">${c}</text>`;
  for(let w=Math.ceil(ac.wmin/step)*step;w<=ac.wmax;w+=step)g+=`<line class="env-grid" y1="${Y(w)}" y2="${Y(w)}" x1="${l}" x2="${W-r}"/><text class="env-ax" x="${l-5}" y="${Y(w)+3.5}" text-anchor="end">${Math.round(fromKg(w)/1000)}</text>`;
  const poly=ac.env.map(p=>X(p[0])+","+Y(p[1])).join(" ");
  const lim=(w,lab,cls)=>`<line class="env-lim ${cls}" x1="${l}" x2="${W-r}" y1="${Y(w)}" y2="${Y(w)}"/><text class="env-lab" x="${W-r-3}" y="${Y(w)-4}" text-anchor="end">${lab}</text>`;
  const pt=(c,w,shape,lab,ok)=>{const px=X(Math.max(ac.cmin,Math.min(ac.cmax,c))),py=Y(Math.max(ac.wmin,Math.min(ac.wmax,w)));const cls="env-pt"+(ok?"":" bad");
    const sh=shape==="o"?`<circle cx="${px}" cy="${py}" r="5.5"/>`:shape==="s"?`<rect x="${px-5}" y="${py-5}" width="10" height="10"/>`:`<path d="M${px} ${py-6.5}L${px+6} ${py+4.5}H${px-6}Z"/>`;
    return `<g class="${cls}">${sh}<text x="${px+9}" y="${py+4}">${lab}</text></g>`};
  const zOk=inEnv(ac,L.zcg,L.zfw)&&L.zfw<=ac.mzfw,tOk=inEnv(ac,L.tcg,L.tow)&&L.tow<=ac.mtow,lOk=inEnv(ac,L.lcg,L.lw)&&L.lw<=ac.mlw;
  return `<svg class="env" viewBox="0 0 ${W} ${H}" role="img" aria-label="Centre of gravity envelope">${g}
   <polygon class="env-poly" points="${poly}"/>${lim(ac.mtow,"MTOW","")}${lim(ac.mlw,"MLW","")}${lim(ac.mzfw,"MZFW","")}
   <polyline class="env-path" points="${X(L.zcg)},${Y(L.zfw)} ${X(L.lcg)},${Y(L.lw)} ${X(L.tcg)},${Y(L.tow)}"/>
   ${pt(L.zcg,L.zfw,"o","ZFW",zOk)}${pt(L.lcg,L.lw,"t","LW",lOk)}${pt(L.tcg,L.tow,"s","TOW",tOk)}
   <text class="env-ax" x="${(l+W-r)/2}" y="${H-4}" text-anchor="middle">CG  %MAC</text><text class="env-ax" x="12" y="${(t+H-b)/2}" transform="rotate(-90 12 ${(t+H-b)/2})" text-anchor="middle">WEIGHT  ${O().unit==="LB"?"1000 LB":"T"}</text></svg>`}
function seatSvg(L){const ac=L.ac,len=ac.cabin[1]+(ac===ACDB.A359?8:6.5),W=640,H=ac===ACDB.A359?150:120,sx=W/len,cy=H/2,maxN=Math.max(...[ac.J,ac.Y].map(d=>d.ab.reduce((a,b)=>a+b,0)+d.ab.length-1));
  const fh=H*0.78,sh=fh/(maxN+1.2);const nose=ac.cabin[0]*sx*0.9;
  let s=`<path class="fus" d="M${nose} ${cy-fh/2}H${W-46}Q${W-6} ${cy-fh/2+4} ${W-4} ${cy}Q${W-6} ${cy+fh/2-4} ${W-46} ${cy+fh/2}H${nose}C${nose*0.35} ${cy+fh/2} 2 ${cy+fh*0.18} 2 ${cy}C2 ${cy-fh*0.18} ${nose*0.35} ${cy-fh/2} ${nose} ${cy-fh/2}Z"/>`;
  s+=`<path class="ckpt" d="M${nose*0.42} ${cy-fh*0.22}L${nose*0.75} ${cy-fh*0.3}V${cy+fh*0.3}L${nose*0.42} ${cy+fh*0.22}"/>`;
  L.seats.forEach((q,i)=>{const def=q.c==="J"?ac.J:ac.Y;const tot=q.n+def.ab.length-1;const slot=q.col+q.g;const y=cy-(tot*sh)/2+slot*sh;const w=(q.c==="J"?ac.J.pitch:1)*((ac.cabin[1]-ac.cabin[0])/(ac.J.rows*ac.J.pitch+ac.Y.rows))*sx*0.72;
    s+=`<rect class="seat ${q.c}${L.fill.has(i)?" on":""}" x="${(q.x*sx-w/2).toFixed(1)}" y="${(y+sh*0.08).toFixed(1)}" width="${w.toFixed(1)}" height="${(sh*0.84).toFixed(1)}" rx="1.5"/>`});
  return `<svg class="seats" viewBox="0 0 ${W} ${H}" role="img" aria-label="Cabin seat map, ${L.pax} passengers boarded">${s}</svg>`}
function fuelSvg(L){const ac=L.ac,sp=fuelSplit(L.tof,ac);const fr=(v,c)=>Math.max(0,Math.min(1,v/c));
  const tank=(id,pts,f,lab,v,x,y)=>`<defs><linearGradient id="${id}" x1="0" y1="1" x2="0" y2="0"><stop offset="${f}" class="fq-on"/><stop offset="${f}" class="fq-off"/></linearGradient></defs><polygon points="${pts}" fill="url(#${id})" class="tank"/><text class="tk-l" x="${x}" y="${y}" text-anchor="middle">${lab}</text><text class="tk-v" x="${x}" y="${y+15}" text-anchor="middle">${fmt(fromKg(v))}</text>`;
  return `<svg class="fuel" viewBox="0 0 420 150" role="img" aria-label="Fuel tanks">
   <rect class="fus2" x="188" y="10" width="44" height="130" rx="20"/>
   ${tank("fqL","188,60 18,108 18,124 188,104",fr(sp.l,ac.tanks.wing),"LEFT",sp.l,110,92)}
   ${tank("fqR","232,60 402,108 402,124 232,104",fr(sp.r,ac.tanks.wing),"RIGHT",sp.r,310,92)}
   ${tank("fqC","190,62 230,62 230,102 190,102",fr(sp.c,ac.tanks.ctr),"CTR",sp.c,210,40)}</svg>`}
V.load=()=>{const L=ldCalc(),x=O(),u=x.unit,ac=L.ac,s=L.s;const capJ=L.seats.filter(q=>q.c==="J").length,capY=L.seats.length-capJ;
  return `<section class="panel"><div class="ph"><span>Cabin</span><span id="ldPax">${ldPaxTxt(L)}</span></div>
    <div class="pb seatbox" id="ldSeats">${seatSvg(L)}</div>
    <div class="pb cabrow"><label class="f"><span>Business <small>/ ${capJ}</small></span><input type="number" min="0" max="${capJ}" data-ld="J" value="${s.J}"></label><label class="f"><span>Economy <small>/ ${capY}</small></span><input type="number" min="0" max="${capY}" data-ld="Y" value="${s.Y}"></label><label class="f">Pax weight ${u}<input type="number" data-ld="pw" value="${s.pw}"></label>
     <div class="row"><button class="btn" data-ldact="board">Board all</button><button class="btn" data-ldact="empty">Deboard</button></div></div></section>
  <div class="pf-grid">
   <section class="panel"><div class="ph"><span>Trim sheet</span><span>${esc(ac.name)} · ${esc(S(x.ac.reg))}</span></div><div class="pb envbox" id="ldEnv">${envSvg(L)}</div>
    <div class="cells" id="ldCells">${ldCells(L)}</div><div class="pb note">Figures update live. Simplified balance model for simulator use only.</div></section>
   <div class="pf-r">
    <section class="panel"><div class="ph"><span>Cargo</span><span>${u}</span></div><div class="pb holds" id="ldHolds">${holdHtml(L)}</div></section>
    <section class="panel"><div class="ph"><span>Fuel</span><span>${u}</span></div><div class="pb fields"><label class="f">Takeoff fuel<input type="number" data-ld="fuel" value="${s.fuel}"></label></div><div class="pb" id="ldFuel">${fuelSvg(L)}</div></section>
    <div class="row"><button class="btn" data-ldact="reset">Reset to OFP</button><a class="btn pri" href="#perf">Performance ▶</a></div>
   </div></div>`};
function ldPaxTxt(L){return `<b>${L.pax}</b> boarded · planned ${fmt(N((ofp.weights||{}).pax_count))}`}
function holdHtml(L){const ac=L.ac,s=L.s;return ac.holds.map((h,i)=>{const k=["fwd","aft","bulk"][i];const v=toKg(s[k]||0);const p=Math.min(100,v/h[2]*100);
  return `<label class="hold"><span class="hk">${h[0]}</span><span class="hbar"><i style="width:${p.toFixed(1)}%" class="${v>h[2]?"over":""}"></i></span><input type="number" min="0" data-ld="${k}" value="${s[k]||0}"><span class="hc">/ ${fmt(fromKg(h[2]))}</span></label>`}).join("")}
function ldCells(L){const ac=L.ac;const c=(k,v,lim)=>cell(k,fmt(fromKg(v)),lim!=null&&v>lim?"c-red":"");const cg=(k,v,w)=>cell(k,v.toFixed(1),inEnv(ac,v,w)?"c-green":"c-red");
  return c("ZFW",L.zfw,ac.mzfw)+cg("ZFWCG %",L.zcg,L.zfw)+c("TOW",L.tow,ac.mtow)+cg("TOWCG %",L.tcg,L.tow)+c("LW",L.lw,ac.mlw)+cg("LWCG %",L.lcg,L.lw)+cell("THS",thsTxt(L.tcg))+cell("Payload",fmt(fromKg(L.cargo+L.pax*toKg(L.s.pw))))}
function thsTxt(cg){const t=AC().ths;const v=t[0][1]+(t[1][1]-t[0][1])*(cg-t[0][0])/(t[1][0]-t[0][0]);const c=Math.max(-2.5,Math.min(3.5,v));return Math.abs(c)<0.05?"0.0":Math.abs(c).toFixed(1)+(c>=0?" UP":" DN")}
function ldRefresh(){const L=ldCalc();$("#ldEnv").innerHTML=envSvg(L);$("#ldCells").innerHTML=ldCells(L);$("#ldSeats").innerHTML=seatSvg(L);$("#ldFuel").innerHTML=fuelSvg(L);
  $("#ldPax").innerHTML=ldPaxTxt(L);document.querySelectorAll(".hold").forEach((h,i)=>{const k=["fwd","aft","bulk"][i],v=toKg(L.s[k]||0),c=L.ac.holds[i][2];const b=h.querySelector("i");b.style.width=Math.min(100,v/c*100).toFixed(1)+"%";b.className=v>c?"over":""})}

/* ---------- Performance ---------- */
/* A321 in-flight landing distance (no failure): a compact model fitted to Airbus in-flight landing data for
   the A321 (CONF FULL/3, max manual / autobrake MED / LOW, runway condition codes 6..1). Per code:
   ref = distance (m) at 78 t, sea level, ISA, no wind, no slope, no reverser, VAPP = VLS, for [MAX, MED, LOW];
   c3 = CONF 3 factor; wgt = fraction per t above 78 t; wb = m per t below [FULL, 3]; spd per 5 kt above VLS;
   alt per 1000 ft; tw per 5 kt tailwind; tmp per 10 °C above ISA; slp per 1 % downslope;
   rev per reverser [MAX FULL, MAX 3, MED FULL, MED 3, LOW FULL, LOW 3]; al = autoland (m).
   The result gets +3 % so the fit stays on the safe side. */
