function pfApt(k){const x=O();return k==="DEP"?x.o:k==="ALTN"?x.a:x.d}
function pfMetar(k){const a=wxFor(O()).find(a=>a[1]===k);return a?decodeMetar(a[3]):null}
function pfApply(st,k){const m=pfMetar(k);if(!m)return false;if(m.wind){st.wd=m.wind.dir==null?0:m.wind.dir;st.ws=m.wind.spd;st.gust=m.wind.gust||0}if(m.temp!=null)st.oat=m.temp;if(m.alt)st.qnh=m.alt.hpa;st.cc=metarCC(m);return true}
