  const dist=R.m==="ld"?`<div class="cells dist">${cell("LDA FT",u(R.len))}${cell("LDR FT",u(R.ldr),cls)}${cell("1.15 LDR FT",u(R.f115),cls)}</div><div class="cells">${cell("VLS",R.vls)}${cell("VAPP",R.vapp+(R.cor!=null?` <small>+${R.cor}</small>`:""),"c-cyan")}${cell("Margin FT",R.len?u(R.len-R.f115):"—",cls)}</div>`
   :`<div class="cells dist">${cell("TORA FT",u(R.len))}${cell("TODR FT",u(R.todr),cls)}${cell("ASDR FT",u(R.asdr),cls)}</div><div class="cells spd">${cell("FLEX",R.flex!=null?R.flex+"°":"TOGA","c-cyan")}${cell("V1",R.v1,"c-cyan")}${cell("VR",R.vr,"c-cyan")}${cell("V2",R.v2,"c-cyan")}${cell("THS",R.ths)}${cell("CONF",esc(R.st.flaps))}</div>`;
