/* ---------- handwriting (the OFP's pens) ---------- */
const kbCur=()=>KB.sel?KB.pages.get(KB.sel):null;
function kbStrokeEl(k){const hl=k.h;return `<path d="${odPathD(k.p)}"${!hl&&k.c==="ink"?' class="ki"':` stroke="${hl?OD_HL:OD_COL[k.c]||OD_COL.blue}"`} stroke-width="${hl?16:2.1}" ${hl?'opacity=".38" stroke-linecap="butt"':'stroke-linecap="round"'} stroke-linejoin="round" fill="none"/>`}
function kbInkRedraw(){const g=document.querySelector("#kbInk g"),p=kbCur();if(g&&p)g.innerHTML=(p.ink||[]).map(kbStrokeEl).join("")}
function kbToolsRedraw(){const T=document.querySelector(".kb-tools");if(!T)return;
  T.querySelectorAll("[data-kbt]").forEach(b=>{const a=b.dataset.kbt,col=a.startsWith("col:");
    if(col||a==="type"||a==="hl"||a==="erase"){const on=col?KB.tool==="pen"&&KB.col===a.slice(4):KB.tool===a;b.setAttribute("aria-pressed",String(on));if(!col)b.classList.toggle("on",on)}
    if(a==="undo")b.disabled=!KB.undo.length;if(a==="redo")b.disabled=!KB.redo.length});
  const h=T.querySelector(".kb-hint"),txt=kbHint();if(h&&h.textContent!==txt){h.textContent=txt;if(!reduced()){h.classList.remove("kb-fade");void h.offsetWidth;h.classList.add("kb-fade")}}}
