  for(let i=list.length-1;i>=0&&hit<0;i--){const k=list[i],rr=9+(k.h?7:1),q=k.p;
    for(let j=0;j<q.length;j++){const a=q[j],b=q[j+1]||a,dx=b[0]-a[0],dy=b[1]-a[1],L=dx*dx+dy*dy,t=L?Math.max(0,Math.min(1,((pt[0]-a[0])*dx+(pt[1]-a[1])*dy)/L)):0;
      if(Math.hypot(a[0]+t*dx-pt[0],a[1]+t*dy-pt[1])<rr){hit=i;break}}}
