/* iPad: hold the page still while a Pencil (or a writing finger) draws */
const kbOnPaper=e=>cur==="kneeboard"&&e.target&&e.target.closest&&e.target.closest("#kbPaper");
const kbHold=e=>[...e.changedTouches,...e.touches].some(t=>t.touchType==="stylus")||(KB.tool!=="type"&&KB.finger==="write")||!!KB.draw||!!(kbPan&&kbTP.size);
