let kbSd=null;
document.addEventListener("pointerdown",e=>{const h=e.target.closest&&e.target.closest(".kb-grabber,.kb-shh");if(!h||cur!=="kneeboard"||!kbNarrow()||e.target.closest("button"))return;const sh=h.closest(".kb-sheet");kbSd={y:e.clientY,t:performance.now(),sh,dy:0};sh.style.animation="none";sh.style.transition="none"});
document.addEventListener("pointermove",e=>{if(!kbSd)return;kbSd.dy=Math.max(0,e.clientY-kbSd.y);kbSd.sh.style.transform=`translateY(${kbSd.dy}px)`;const sd=document.querySelector(".kb-shade");if(sd)sd.style.opacity=String(1-Math.min(1,kbSd.dy/400))});
