function hlWidgets(){const box=$("#page1 .widgets");if(!box)return;const G=hlWG(),ws=[...box.children].filter(e=>e.classList.contains("w"));
  ws.forEach(w=>{w.dataset.wk=hlWKey(w)});const rank=k=>{const i=G.order.indexOf(k);return i<0?100+ws.findIndex(w=>w.dataset.wk===k):i};
  ws.slice().sort((a,b)=>rank(a.dataset.wk)-rank(b.dataset.wk)).forEach(w=>box.appendChild(w));
  ws.forEach(w=>{if(G.hidden.includes(w.dataset.wk))w.remove()})}
