/* iPhone: hold an app at the screen edge to carry it to the next page */
function hlEdge(x){if(HL.mode!=="phone"){return}const s=screenEl.getBoundingClientRect(),dir=x<s.left+30?-1:x>s.right-30?1:0;
  if(!dir){clearTimeout(HL.flipT);HL.flipT=0;return}if(HL.flipT)return;
  HL.flipT=setTimeout(()=>{HL.flipT=0;if(!HL.drag)return;const n=hlPage()+dir;if(n<1||n>2)return;goPage(n);
    setTimeout(()=>{if(HL.drag){hlPlace(HL.drag.x,HL.drag.y);hlEdge(HL.drag.x)}},420)},620)}
