  (typeof UPD_LOG!=="undefined"?UPD_LOG:[]).forEach(([d,L])=>L.forEach(t=>{if(news.length<3&&new RegExp("^"+a.name+"\\b|\\b"+a.name+":","i").test(t)){const x=t.replace(new RegExp("^"+a.name+":\\s*","i"),"");news.push([d,x.charAt(0).toUpperCase()+x.slice(1)])}}));
