/* ---------- taps ---------- */
document.addEventListener("click",e=>{const t=e.target.closest&&e.target.closest("[data-asget],[data-asopen],[data-asdet],[data-asxtab],[data-asback],[data-asdel],[data-asall],[data-asneed],[data-asneedx]");if(!t)return;const d=t.dataset;
  if(d.asneedx!=null){asNeedClose();return}
  if(d.asneed){const id=d.asneed;asGet(id,()=>{asNeedClose(true);setTimeout(()=>goApp(id),reduced()?0:260)});return}
  if(cur!=="store")return;
  if(d.asget){asGet(d.asget);return}
  if(d.asopen){goApp(d.asopen);return}
  if(d.asall){d.asall.split(",").filter(id=>!asHas(id)).forEach((id,i)=>setTimeout(()=>asGet(id,()=>{if(cur==="store"&&!ASX.det&&!Object.keys(ASX.busy).length)render()}),i*180));return}
  if(d.asdet){ASX.det=d.asdet;ASX.armDel=null;ASX.anim=2;render();const s=$("#asScroll");if(s)s.scrollTop=0;return}
  if(d.asback!=null){ASX.det=null;ASX.anim=3;render();return}
  if(d.asxtab){ASX.tab=d.asxtab;ASX.det=null;ASX.anim=3;render();const s=$("#asScroll");if(s)s.scrollTop=0;return}
  if(d.asdel){if(ASX.armDel!==d.asdel){ASX.armDel=d.asdel;render();setTimeout(()=>{if(ASX.armDel===d.asdel){ASX.armDel=null;if(cur==="store")render()}},4000);return}ASX.armDel=null;asRemove(d.asdel);render()}});
document.addEventListener("input",e=>{if(cur!=="store"||!e.target.matches("[data-asq]"))return;ASX.q=e.target.value;const w=$("#asRoot .asx-wrap"),p=e.target.selectionStart;if(w){w.innerHTML=asApps();const i=w.querySelector("[data-asq]");if(i){i.focus();try{i.setSelectionRange(p,p)}catch(x){}}}});

/* ---------- an app that isn't installed: offer it instead of opening nothing ---------- */
function asNeed(id){if(!APPS[id]||!AS_INFO[id])return;asNeedClose(true);const A=AS_INFO[id];
  document.body.insertAdjacentHTML("beforeend",`<div class="asx-need" id="asNeed" role="dialog" aria-label="Get ${esc(APPS[id].name)}"><div class="asx-nshade" data-asneedx></div><div class="asx-ncard">${asIcon(id,"md")}<b>${esc(APPS[id].name)}</b><p>${esc(A.s)}. Get it from the App Store to open it.</p><div class="asx-nact"><button class="asx-nbtn" data-asneedx>Not Now</button><button class="asx-nbtn pri" data-asneed="${id}" data-asb="${id}">Get</button></div></div></div>`)}
function asNeedClose(now){const n=$("#asNeed");if(!n)return;if(now||reduced()){n.remove();return}n.classList.add("out");setTimeout(()=>n.remove(),200)}
/* links and icons pointing at an app that isn't installed */
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest('a[href^="#"]');if(!a)return;const id=a.getAttribute("href").slice(1);if(APPS[id]&&!asOk(id)){e.preventDefault();e.stopImmediatePropagation();asNeed(id)}},true);
{const _g=goApp;goApp=function(id){
  if(APPS[id]&&!asOk(id)){asNeed(id);return}asNeedClose(true);return _g.call(this,id)}}
/* opening another app (a link, a notification) closes a "Get …" sheet left from before */
{const _ac=appChrome;appChrome=function(id){if(APPS[id]&&!asOk(id)){setTimeout(()=>{goHome();asNeed(id)},0)}else asNeedClose(true);return _ac.apply(this,arguments)}}

/* ---------- Home Screen: remove an app, or only take it off the Home Screen ---------- */
