const AL_D=["S","M","T","W","T","F","S"],AL_DN=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
function alRepText(r){r=(r||[]).slice().sort();if(!r.length)return"";if(r.length===7)return"every day";if(r.join()==="1,2,3,4,5")return"every weekday";if(r.join()==="0,6")return"every weekend";
  return "every "+r.map(i=>AL_DN[i].slice(0,3)).join(", ")}
/* a minute that has already begun counts as passed (iOS): saving or switching on an alarm for this very minute rings next time */
const ckNowKey=()=>{const n=new Date();return n.getFullYear()+"-"+n.getMonth()+"-"+n.getDate()+" "+pad(n.getHours())+":"+pad(n.getMinutes())};
const alArm=a=>{const n=new Date();if(a.hm===pad(n.getHours())+":"+pad(n.getMinutes()))CK.fired[a.id]=ckNowKey()};
const alNextLocal=a=>{const [h,m]=a.hm.split(":").map(Number),n=new Date();for(let k=0;k<=7;k++){const t=new Date(n.getFullYear(),n.getMonth(),n.getDate()+k,h,m,0,0);if(t>n&&(!a.rep||!a.rep.length||a.rep.includes(t.getDay())))return +t}return null};
/* the server rings the closed EFB: the whole list goes up whenever it changes */
let ckSyncT=0;function ckSyncSoon(){clearTimeout(ckSyncT);ckSyncT=setTimeout(ckSync,700)}
function ckSync(){if(typeof pushOn!=="function"||!pushOn()||typeof authOn!=="function"||!authOn()||!vam.url)return;
  const list=[];alGet().filter(a=>a.on).forEach(a=>{if(a.rep&&a.rep.length)list.push({id:a.id,kind:"alarm",hm:a.hm,tz:LOCAL_TZ,rep:a.rep,label:a.label||""});else{const at=alNextLocal(a);if(at)list.push({id:a.id,kind:"alarm",at,hm:a.hm,label:a.label||""})}});
  (store.get("alSnooze",[])||[]).forEach(s=>{if(s.at>Date.now())list.push({id:"z"+s.id,kind:"alarm",at:s.at,hm:s.hm,label:(s.label?s.label+" · ":"")+"Snoozed"})});
  if(cd.end!=null)list.push({id:"timer",kind:"timer",at:cd.end,label:cd.label||""});
  const k=JSON.stringify(list);if(k===CK.lastSync)return;
  pmPost("/api/efb/crew/alarms",{list}).then(()=>{CK.lastSync=k}).catch(()=>{})}
