function ckRing(r){if(CK.ring)return;CK.ring=r;let n=0;clearInterval(CK.ringT);beep();try{navigator.vibrate&&navigator.vibrate([400,200,400])}catch(e){}
  CK.ringT=setInterval(()=>{if(++n>40){ckRingStop(true);return}beep()},1500);ckRingDraw()}
function ckRingDraw(){let el=document.getElementById("ckRing");const r=CK.ring;if(!r){if(el)el.remove();return}
  if(!el){el=document.createElement("div");el.id="ckRing";el.className="ck-ringov";el.setAttribute("role","alertdialog");el.setAttribute("aria-label",r.kind==="timer"?"Timer":"Alarm");document.body.appendChild(el)}
  el.innerHTML=`<div class="ck-rin"><p class="k">${r.kind==="timer"?"Timer":"Alarm"}</p><p class="t">${esc(r.hm||"")}</p><p class="l">${esc(r.label||(r.kind==="timer"?"Your timer is done":""))}</p>
    ${r.snooze?`<button class="ck-snz" data-cksnooze>Snooze</button>`:""}<button class="ck-stop" data-ckstop>Stop</button></div>`}
function ckRingStop(missed){const r=CK.ring;clearInterval(CK.ringT);CK.ring=null;ckRingDraw();if(missed&&r)toast((r.kind==="timer"?"Timer":"Alarm "+r.hm)+" stopped ringing")}
setInterval(()=>{const n=new Date(),key=n.getFullYear()+"-"+n.getMonth()+"-"+n.getDate()+" "+pad(n.getHours())+":"+pad(n.getMinutes()),hm=pad(n.getHours())+":"+pad(n.getMinutes());
  let L=alGet(),ch=false;
  for(const a of L){if(!a.on||a.hm!==hm||CK.fired[a.id]===key)continue;if(a.rep&&a.rep.length&&!a.rep.includes(n.getDay()))continue;
    CK.fired[a.id]=key;if(!a.rep||!a.rep.length){a.on=false;ch=true}ckRing({id:a.id,kind:"alarm",hm:a.hm,label:a.label,snooze:a.snooze!==false})}
  if(ch){alSet(L);if(cur==="timer"&&clockTab==="alarm"&&!CK.sheet)render()}
  const Z=store.get("alSnooze",[])||[],due=Z.filter(s=>s.at<=Date.now());
  if(due.length){store.set("alSnooze",Z.filter(s=>s.at>Date.now()));ckRing({id:due[0].id,kind:"alarm",hm:due[0].hm,label:due[0].label,snooze:true})}},1000);
document.addEventListener("click",e=>{const t=e.target.closest&&e.target.closest("[data-ckstop],[data-cksnooze]");if(!t)return;const r=CK.ring;
  if(t.dataset.cksnooze!=null&&r){const at=Date.now()+9*60000,Z=(store.get("alSnooze",[])||[]).filter(s=>s.id!==r.id);Z.push({id:r.id,at,hm:r.hm,label:r.label});store.set("alSnooze",Z);ckSyncSoon();toast("Snoozed for 9 minutes")}
  ckRingStop()});
/* a timer that ends while the EFB is open rings like an alarm */
{const _cc=cdCheck;cdCheck=function(){const was=cd.end!=null&&Date.now()>=cd.end,lab=cd.label;const r=_cc.apply(this,arguments);if(was){ckRing({id:"timer",kind:"timer",hm:"",label:lab});ckSyncSoon()}return r}}
/* ---------- wheel picker ---------- */
const WH=36;
const whl=(k,max,val,unit,two)=>`<div class="whl"><div class="whl-s" data-whl="${k}" data-v="${val}" tabindex="0" aria-label="${unit}" role="listbox">${Array.from({length:max+1},(_,i)=>`<div class="whl-i" data-i="${i}">${two?pad(i):i}</div>`).join("")}</div>${unit?`<span class="whl-u">${unit}</span>`:""}</div>`;
function whlInit(){document.querySelectorAll("#view .whl-s").forEach(s=>{if(s._on)return;s._on=1;s.scrollTop=(+s.dataset.v||0)*WH;let t=0;
  s.addEventListener("scroll",()=>{clearTimeout(t);t=setTimeout(()=>{const v=Math.max(0,Math.min(s.children.length-1,Math.round(s.scrollTop/WH)));s.dataset.v=v;CK.wh[s.dataset.whl]=v;
    s.querySelectorAll(".whl-i").forEach(i=>i.classList.toggle("on",+i.dataset.i===v))},90)},{passive:true});
  s.addEventListener("click",e=>{const i=e.target.closest(".whl-i");if(i)s.scrollTo({top:+i.dataset.i*WH,behavior:"smooth"})});
  s.addEventListener("keydown",e=>{if(e.key!=="ArrowUp"&&e.key!=="ArrowDown")return;e.preventDefault();s.scrollTo({top:((+s.dataset.v||0)+(e.key==="ArrowUp"?-1:1))*WH,behavior:"smooth"})});
  CK.wh[s.dataset.whl]=+s.dataset.v||0;s.querySelectorAll(".whl-i").forEach(i=>i.classList.toggle("on",+i.dataset.i===(+s.dataset.v||0)))})}
