    if(v.rep==="weekly"){const until=+v.until||hi;let k=Math.max(0,Math.ceil((lo-s0)/W));for(let t=s0+k*W;t<=Math.min(until,hi)&&occ.length<90;t+=W,k++)occ.push([t,k])}else occ.push([s0,0]);
