      const sub=[v.subtype&&v.subtype!=="routes"&&v.subtype!=="airports"?v.subtype:"",rt.slice(0,3).join(", "),ap.slice(0,6).join(" "),v.points?v.points+(v.pointsAsPercentage?"% ":" ")+"points":""].filter(Boolean).join(" · ");
