    const pd=.08*Math.max(e-w,n-so,1),W2=el.clientWidth||600,H2=el.clientHeight||320,k=Math.min(W2/((e-w)+2*pd),H2/((n-so)+2*pd)),X=(W2-(e-w)*k)/2+(s.lon-w)*k,Y=(H2-(n-so)*k)/2+(n-s.lat)*k;
