/* ===== File on VATSIM =====
   Flight Plan › Overview starts with a card for filing the plan on VATSIM: what goes in it (callsign, type and
   equipment, cruise level, route, alternate, endurance, SELCAL and remarks when the plan has them) and a button that
   opens myVATSIM's flight plan form filled in from it. The link is SimBrief's own pre-file link when the plan carries
   one; otherwise the form gets the plan's ICAO flight plan (raw). Copy buttons for the route and the whole flight plan
   are there for filing by hand (vPilot, xPilot, or another network). */
function pfiLink(net){const p=(ofp.prefile||{})[net];if(p&&S(p.link))return S(p.link);
  if(net!=="vatsim")return"";const t=S((ofp.atc||{}).flightplan_text);return t?"https://my.vatsim.net/pilots/flightplan?raw="+encodeURIComponent(t):"https://my.vatsim.net/pilots/flightplan"}
function pfiHtml(){if(ofp._sample)return"";const x=O(),a=ofp.atc||{},g=x.g,tm=ofp.times||{},cs=S(a.callsign)||x.flight,fl=N(g.initial_altitude),end=N(tm.endurance);
  const fpl=S(a.flightplan_text),route=S(a.route)||S(g.route),rmk=(fpl.match(/RMK\/([^)]*)/)||[])[1]||"",equip=(fpl.match(/-[A-Z0-9]{2,4}\/[A-Z]\s*-\s*([A-Z0-9]+\/[A-Z0-9]+)/)||[])[1]||"";
  const row=(k,v)=>v?`<div><dt>${k}</dt><dd>${v}</dd></div>`:"";const ivao=pfiLink("ivao");
  return `<section class="card pfi">${cardH("VATSIM","File this flight plan",`<span class="tagl">${esc(cs)}</span>`)}
    <dl class="stats">${row("Callsign",esc(cs))}${row("Type",esc(S(x.ac.icaocode))+(equip?` <small>${esc(equip)}</small>`:""))}${row("Cruise",fl?(fl>=18000?"FL"+Math.round(fl/100):fmt(fl)+" ft"):"")}${row("Route",esc(S(x.o.icao_code))+" → "+esc(S(x.d.icao_code)))}${row("Alternate",esc(S(x.a.icao_code)))}${row("Endurance",end?hhmm(end):"")}</dl>
    ${route?`<p class="pfi-rt">${esc(route)}</p>`:""}${rmk?`<p class="pfi-rmk"><b>RMK/</b>${esc(rmk.trim())}</p>`:""}
    <div class="row pfi-b"><a class="btn pri" href="${esc(pfiLink("vatsim"))}" target="_blank" rel="noopener">File on VATSIM ↗</a>${ivao?`<a class="btn" href="${esc(ivao)}" target="_blank" rel="noopener">File on IVAO ↗</a>`:""}
      ${route?`<button class="btn" data-pficopy="route">Copy route</button>`:""}${fpl?`<button class="btn" data-pficopy="fpl">Copy ICAO flight plan</button>`:""}</div>
    <p class="note">Opens myVATSIM's form filled in from this plan: check it and press File. Sign in to myVATSIM first if it asks.</p></section>`}
{const _s=ofpSummary;ofpSummary=function(){return pfiHtml()+_s.apply(this,arguments)}}
document.addEventListener("click",e=>{const t=e.target.closest("[data-pficopy]");if(!t)return;const a=ofp.atc||{},v=t.dataset.pficopy==="fpl"?S(a.flightplan_text):(S(a.route)||S(O().g.route));
  (navigator.clipboard?navigator.clipboard.writeText(v):Promise.reject()).then(()=>toast(t.dataset.pficopy==="fpl"?"Flight plan copied":"Route copied")).catch(()=>toast("The browser blocked copying"))});
