function csTick(){const n=csNext();if(!n)return;const b=document.querySelector(`[data-ck="${n.k}"]`);if(b)b.click();else{const key=clKey(),s=store.get(key,{});s[n.k]=true;store.set(key,s);render()}
  setTimeout(csAsk,450)}
