gl_Position=vec4(((uC.x-uS.x*.5)*Z+uFoc*X)/(uS.x*.5),(-(uC.y-uS.y*.5)*Z+uFoc*Y)/(uS.y*.5),Z*(f+n)/(f-n)-2.0*f*n/(f-n),Z);
