  const L={};for(const k of ["uCam","uR","uU","uF","uC","uS","uFoc","uMax","uNear","uOff","uSc","uFogC","uAltM","uAir","uDim"])L[k]=gl.getUniformLocation(p,k);for(const k of ["aP","aN","aE"])L[k]=gl.getAttribLocation(p,k);SV.loc=L;
