  const I=new Uint16Array(SV_NR*SV_NS*6);let q=0;for(let i=0;i<SV_NR;i++)for(let j=0;j<SV_NS;j++){const a=i*SV_NS+j,b=i*SV_NS+(j+1)%SV_NS,c=a+SV_NS,d=b+SV_NS;I[q++]=a;I[q++]=c;I[q++]=b;I[q++]=b;I[q++]=c;I[q++]=d}
