  EG:["the United Kingdom","🇬🇧","999"],EI:["Ireland","🇮🇪","112"],LF:["France","🇫🇷","112"],ED:["Germany","🇩🇪","112"],ET:["Germany","🇩🇪","112"],EH:["the Netherlands","🇳🇱","112"],EB:["Belgium","🇧🇪","112"],EL:["Luxembourg","🇱🇺","112"],
  LS:["Switzerland","🇨🇭","112"],LO:["Austria","🇦🇹","112"],LI:["Italy","🇮🇹","112"],LE:["Spain","🇪🇸","112"],GC:["Spain","🇪🇸","112"],LP:["Portugal","🇵🇹","112"],LG:["Greece","🇬🇷","112"],LT:["Türkiye","🇹🇷","112"],
