  LR:["Romania","🇷🇴","112"],LB:["Bulgaria","🇧🇬","112"],LD:["Croatia","🇭🇷","112"],LJ:["Slovenia","🇸🇮","112"],LY:["Serbia","🇷🇸","112"],LM:["Malta","🇲🇹","112"],LC:["Cyprus","🇨🇾","112"],EY:["Lithuania","🇱🇹","112"],EV:["Latvia","🇱🇻","112"],EE:["Estonia","🇪🇪","112"],
  UK:["Ukraine","🇺🇦","112"],U:["Russia","🇷🇺","112"],LL:["Israel","🇮🇱","100"],OJ:["Jordan","🇯🇴","911"],OM:["the United Arab Emirates","🇦🇪","999"],OT:["Qatar","🇶🇦","999"],OB:["Bahrain","🇧🇭","999"],OK:["Kuwait","🇰🇼","112"],OE:["Saudi Arabia","🇸🇦","911"],OO:["Oman","🇴🇲","9999"],OI:["Iran","🇮🇷","110"],
