  VI:["India","🇮🇳","112"],VA:["India","🇮🇳","112"],VE:["India","🇮🇳","112"],VO:["India","🇮🇳","112"],VC:["Sri Lanka","🇱🇰","119"],VR:["the Maldives","🇲🇻","119"],VN:["Nepal","🇳🇵","100"],OP:["Pakistan","🇵🇰","15"],VG:["Bangladesh","🇧🇩","999"],
  VT:["Thailand","🇹🇭","191"],VV:["Vietnam","🇻🇳","113"],VD:["Cambodia","🇰🇭","117"],VL:["Laos","🇱🇦","191"],VY:["Myanmar","🇲🇲","199"],WS:["Singapore","🇸🇬","999"],WM:["Malaysia","🇲🇾","999"],WB:["Malaysia","🇲🇾","999"],WI:["Indonesia","🇮🇩","112"],WA:["Indonesia","🇮🇩","112"],WR:["Indonesia","🇮🇩","112"],RP:["the Philippines","🇵🇭","911"],
