/* ---------- 3. a chart's georeference in the viewer, two-fix line-up, the aircraft ---------- */
async function cxDiagRef(pg,icao){try{if(!icao||(pg.rotate||0)%360!==0||(CH.data[icao]||{}).src==="tw")return null;if(!TX.data[icao]){txLoad(icao);for(let i=0;i<16&&!TX.data[icao];i++)await new Promise(r=>setTimeout(r,250))}
    const d=TX.data[icao];if(!d||!d.runways||!d.runways.length)return null;const tc=await pg.getTextContent();const g=dgRef(tc.items,pg.view,d.runways,(lat,lon)=>{const q=mpx(lat,lon,0);return[q[0]/TS,q[1]/TS]});if(!g)return null;
    const ll=munpx(g.c[0]*TS,g.c[1]*TS,0),hM=g.h*40075016.7*Math.cos(ll[0]*Math.PI/180);if(!isFinite(ll[0])||!(hM>500&&hM<30000))return null;return{lat:ll[0],lon:((ll[1]+540)%360)-180,h:hM,rot:g.rot}}catch(e){return null}}
/* the same order as on the Map: your own alignment, the chart's own coordinates, a Polaris pilot's, the runway numbers */
async function cxGeoLoad(){const sel=CV.sel,pg=CV.pg,page=CV.page;CX.geo=null;CX.geoSrc="";CX.geoBy="";if(!sel||!pg)return;const mine=sel.pdf+"|"+page+"|"+Math.random();CX.geoFor=mine;
  const v=pg.getViewport({scale:1});CX.pw=v.width;CX.ph=v.height;
  const done=(g,src,by)=>{if(CX.geoFor!==mine||CV.sel!==sel)return false;CX.geo=g?{lat:+g.lat,lon:+g.lon,h:+g.h,rot:+g.rot||0}:null;CX.geoSrc=g?src:"";CX.geoBy=by||"";cxViewUi();cxLayers();return true};
  const saved=store.get("ovgeo:"+sel.icao+":"+sel.pdf+":"+page,null);let auto=null;
  try{const raw=new TextDecoder("latin1").decode(await CV.doc.getData());auto=ovGeoref(raw,pg.view,pg.rotate,page,CV.pages)}catch(e){}
  if(auto){done(saved||auto,saved?"saved":"pdf");return}
  if(saved)done(saved,"saved");
  if(vam.url){try{const j=await vamGet("/api/efb/ovgeo?"+ovShQ(sel,page),10000),g=j&&j.geo;if(g&&!saved){done(g,"shared",g.by);return}}catch(e){}}
  if(saved)return;if(/diagram/i.test((sel.group||"")+" "+(sel.name||""))){const g=await cxDiagRef(pg,sel.icao);if(g)done(g,"rwy")}else done(null,"")}
function cxGeoM(g,pw,ph){const q=mpx(g.lat,g.lon,0),r=g.rot*Math.PI/180;return{cx:q[0],cy:q[1],s:g.h*TS/(40075016.7*Math.cos(g.lat*Math.PI/180)*ph),c:Math.cos(r),n:Math.sin(r),pw,ph}}
function cxW2P(M,la,lo){const q=mpx(la,lo,0);let ex=q[0]-M.cx;while(ex>TS/2)ex-=TS;while(ex<-TS/2)ex+=TS;const ey=q[1]-M.cy;return[(M.c*ex+M.n*ey)/M.s+M.pw/2,(-M.n*ex+M.c*ey)/M.s+M.ph/2]}
function cxP2W(M,px,py){const dx=px-M.pw/2,dy=py-M.ph/2,ll=munpx(M.cx+M.s*(M.c*dx-M.n*dy),M.cy+M.s*(M.n*dx+M.c*dy),0);return{la:ll[0],lo:((ll[1]+540)%360)-180}}
/* two chart points and the fixes they are: position, size and turn of the chart (a similarity on the Mercator plane) */
function cxFit2(a,b,pw,ph){const q1=mpx(a.la,a.lo,0),q2=mpx(b.la,b.lo,0);let Dx=q2[0]-q1[0];while(Dx>TS/2)Dx-=TS;while(Dx<-TS/2)Dx+=TS;const Dy=q2[1]-q1[1];
  const d1=[a.px-pw/2,a.py-ph/2],dx=b.px-a.px,dy=b.py-a.py,dd=Math.hypot(dx,dy),DD=Math.hypot(Dx,Dy);if(dd<25||!(DD>0))return null;
  const s=DD/dd,r=Math.atan2(Dy,Dx)-Math.atan2(dy,dx),c=Math.cos(r),n=Math.sin(r),cx=q1[0]-s*(c*d1[0]-n*d1[1]),cy=q1[1]-s*(n*d1[0]+c*d1[1]),ll=munpx(cx,cy,0);
  const h=s*ph*40075016.7*Math.cos(ll[0]*Math.PI/180)/TS;if(!isFinite(ll[0])||!(h>=200&&h<=4e6))return null;
  let rot=+(((r*180/Math.PI)%360+360)%360).toFixed(2);if(rot>=360)rot=0;return{lat:+ll[0].toFixed(6),lon:+(((ll[1]+540)%360)-180).toFixed(6),h:Math.round(h),rot}}
/* fixes that could be on this chart: the simulator's procedures at the airport, the route, the runway thresholds */
function cxLegs(p){return(p.f?[p.f,p.m||[],...Object.values(p.tr||{})]:[p.c||[],...Object.values(p.rt||{}),...Object.values(p.et||{})]).flat()}
function cxProcOf(icao,sel){const d=(typeof NP!=="undefined"&&(NP.data[icao]||npLocal(icao)))||null,out=new Set();if(!d||!sel)return out;
  if(sel.group==="Departures"||sel.group==="Arrivals"){const tw=(CH.data[icao]||{}).src==="tw",code=tw?"":rpCode(sel.name),L=sel.group==="Departures"?d.dep:d.arr;(L||[]).filter(p=>tw?cxTwScore(sel.name,p.n)>0:p.n===code).forEach(p=>cxLegs(p).forEach(g=>g.f&&out.add(g.f)))}
  else if(sel.group==="Approaches"){for(const p of d.apr||[])if(cxApScore({name:sel.name},{ty:p.ty,rw:npRwyN(p.rw),sfx:p.sfx})>0)cxLegs(p).forEach(g=>g.f&&out.add(g.f))}
  return out}
function cxCands(icao){const out=new Map(),add=(n,la,lo,k)=>{if(!n||la==null||lo==null||!isFinite(+la)||!isFinite(+lo)||out.has(n))return;out.set(n,{n,la:+la,lo:+lo,k})};
  const d=(typeof NP!=="undefined"&&(NP.data[icao]||npLocal(icao)))||null;
  if(d){for(const p of [...(d.dep||[]),...(d.arr||[]),...(d.apr||[])])for(const g of cxLegs(p))if(g.f&&!/^RW\d/.test(g.f))add(g.f,g.la,g.lo,"fix");(d.rw||[]).forEach(r=>add("RW"+r.n,r.la,r.lo,"rwy"));add(icao,d.la,d.lo,"apt")}
  if(cxOk())try{const[oi,di]=cxApts();if(icao===oi||icao===di)rePts().forEach(q=>{if(!q.apt&&!/^TO[CD]$/.test(q.n))add(q.n,q.lat,((q.lon+540)%360)-180,"route")})}catch(e){}
  const t=TX.data[icao];if(t&&t.airport&&t.airport.lat!=null)add(icao,t.airport.lat,t.airport.lon,"apt");
  return[...out.values()]}
const CX_KIND={fix:"Procedure fix",rwy:"Runway threshold",route:"Route point",apt:"Airport reference point",mine:"On this chart’s procedure"};
/* the line-up bar, the picker and the viewer's notes */
function cxViewUi(){const el=document.getElementById("cvWrap");if(!el||!CV.open)return;
  const n=el.querySelector("#cxGeoNote");if(n){const s=CX.geoSrc;n.textContent=!CV.pg?"":s==="pdf"?"Positioned from the chart’s own coordinates":s==="shared"?(CX.geoBy?"Lined up by "+CX.geoBy:"Lined up by a Polaris pilot"):s==="saved"?"Your alignment":s==="rwy"?"Lined up with the runways":"Not lined up · Line up shows your aircraft on it";n.dataset.s=s||"none"}
  const tb=el.querySelector('[data-cx="tf"]');if(tb){tb.hidden=!CV.pg||CX.geoSrc==="pdf";tb.setAttribute("aria-pressed",String(!!CX.tf))}
  const pb=el.querySelector('[data-cx="pen"]');if(pb)pb.setAttribute("aria-pressed",String(CX.pen));
  const sb=el.querySelector('[data-cx="split"]');if(sb){sb.hidden=!cxSplitOk();sb.setAttribute("aria-pressed",String(cxSplitOn()))}
  const bar=el.querySelector("#cxTf");if(bar){const T=CX.tf;let h="";
    if(T){const st=T.pts.length;h=`<span class="cx-tfn">${st+1}<i>/2</i></span><p><b>Line up: tap fix ${st+1} of 2 on the chart</b><span>${st?"Pick another fix far from "+esc(T.pts[0].n)+", across the chart.":"Zoom in and tap the centre of a fix, a navaid or a runway end whose name you can read."}</span></p><button class="btn sm" data-cx="tfx">Cancel</button>`}
    else if(CX.tfDone){h=`<span class="cx-tfn ok">✓</span><p><b>Lined up on ${esc(CX.tfDone.a)} and ${esc(CX.tfDone.b)}</b><span>The other fixes are shown in cyan for a moment: they should sit on the chart’s own.${CX.tfDone.sh?" Shared with Polaris pilots.":""}</span></p>${CX.tfDone.map?`<button class="btn sm" data-cx="tfmap2">Back to the map</button>`:""}<button class="btn sm" data-cx="tfok">Done</button>`}
    if(bar.dataset.h!==h){bar.dataset.h=h;bar.innerHTML=h}const hid=!h;if(bar.hidden!==hid){bar.hidden=hid;cvSharp()}}
  const pbar=el.querySelector("#cxPenBar");if(pbar){const hid=!CX.pen;if(pbar.hidden!==hid){pbar.hidden=hid;cvSharp()}if(CX.pen)cxPenBarUi(pbar)}}
function cxTfStart(){if(!CV.pg){CX.tfWant={page:CV.page};return}CX.tf={pts:[]};CX.tfDone=null;CX.pen=false;cxPickClose();cxViewUi();cxLayers()}
function cxTfStop(){CX.tf=null;cxPickClose();cxViewUi();cxLayers()}
function cxPickClose(){const p=document.getElementById("cxPick");if(p){p.remove();if(!CX.pick)try{cxOwnDraw()}catch(e){}}}
function cxTfTap(x,y){if(!CX.tf||!CV.pg)return;const p=cvApply(cvInv(cvM(CV)),[x,y]);if(p[0]<0||p[1]<0||p[0]>CX.pw||p[1]>CX.ph){toast("Tap on the chart itself");return}
  const icao=CV.sel.icao,mineSet=cxProcOf(icao,CV.sel),C=cxCands(icao).filter(c=>!CX.tf.pts.some(q=>q.n===c.n));
  if(!C.length){toast("No fixes known at "+icao+" yet: load a flight plan through it, or read its procedures with Polaris Navdata");return}
  let at=null;if(CX.geo)try{at=cxP2W(cxGeoM(CX.geo,CX.pw,CX.ph),p[0],p[1])}catch(e){}
  const dist=c=>at?npGd({la:at.la,lo:at.lo},{la:c.la,lo:c.lo}):0;
  C.forEach(c=>{c.mine=mineSet.has(c.n);c.dd=dist(c)});C.sort((a,b)=>(b.mine-a.mine)||(at?a.dd-b.dd:0)||a.n.localeCompare(b.n));
  CX.pick={px:p[0],py:p[1],x,y,C};cxPickUi("");cxOwnDraw()}
function cxPickUi(q){cxPickClose();const P=CX.pick,el=document.getElementById("cvWrap"),st=document.getElementById("cvStage");if(!P||!el||!st)return;const Q=String(q||"").trim().toUpperCase();
  const L=P.C.filter(c=>!Q||c.n.startsWith(Q)).slice(0,60),sr=st.getBoundingClientRect(),wr=el.getBoundingClientRect();
  const d=document.createElement("div");d.id="cxPick";d.className="cx-pick";d.setAttribute("role","dialog");d.setAttribute("aria-label","Which fix is this?");
  d.innerHTML=`<div class="cx-pkh"><b>Fix ${CX.tf.pts.length+1} of 2</b><span>Which fix did you tap?</span></div><input type="text" id="cxPickQ" placeholder="Type its name" autocomplete="off" autocapitalize="characters" spellcheck="false" enterkeyhint="done" value="${esc(Q)}" aria-label="Fix name">
    <div class="cx-pkl">${L.length?L.map(c=>`<button type="button" data-cxpick="${esc(c.n)}"><b>${esc(c.n)}</b><small>${c.mine?CX_KIND.mine:CX_KIND[c.k]||""}${c.dd&&c.dd<300?" · "+(c.dd<10?c.dd.toFixed(1):Math.round(c.dd))+" nm":""}</small></button>`).join(""):`<p>No fix called ${esc(Q)} here.</p>`}</div><button type="button" class="cx-pkx" data-cxpickx>Cancel</button>`;
  el.appendChild(d);const W=d.offsetWidth,H=d.offsetHeight,X=sr.left-wr.left+P.x,Y=sr.top-wr.top+P.y;
  d.style.left=Math.max(8,Math.min(wr.width-W-8,X+18))+"px";d.style.top=Math.max(8,Math.min(wr.height-H-8,Y-H/2))+"px";
  const i=d.querySelector("#cxPickQ");if(i&&matchMedia("(pointer:fine)").matches)try{i.focus();i.setSelectionRange(i.value.length,i.value.length)}catch(e){}}
function cxPickChoose(n){const P=CX.pick;if(!P||!CX.tf)return;const c=P.C.find(x=>x.n===n);if(!c)return;CX.tf.pts.push({px:P.px,py:P.py,n:c.n,la:c.la,lo:c.lo});CX.pick=null;cxPickClose();
  if(CX.tf.pts.length<2){cxViewUi();cxLayers();return}
  const [a,b]=CX.tf.pts,g=cxFit2(a,b,CX.pw,CX.ph);
  if(!g){CX.tf.pts.pop();toast("Those two are too close on the chart, or the names don’t match: pick a second fix farther away");cxViewUi();cxLayers();return}
  const sel=CV.sel,page=CV.page;store.set("ovgeo:"+sel.icao+":"+sel.pdf+":"+page,g);CX.geo=g;CX.geoSrc="saved";CX.geoBy="";
  const sh=typeof vamOn==="function"&&vamOn();if(sh)ovSharedPut({icao:sel.icao,name:sel.name},page,g);
  if(OV.sel&&OV.sel.icao===sel.icao&&OV.sel.pdf===sel.pdf&&OV.page===page){OV.geo={...g};OV.src="saved";try{ovUi();ovSched()}catch(e){}}
  CX.tfDone={a:a.n,b:b.n,sh,map:!!CX.tfFromMap};CX.tf=null;CX.tfFromMap=false;
  const M=cxGeoM(g,CX.pw,CX.ph);CX.verList=cxCands(sel.icao).filter(c=>c.n!==a.n&&c.n!==b.n).map(c=>({c,p:cxW2P(M,c.la,c.lo)})).filter(o=>o.p[0]>=0&&o.p[1]>=0&&o.p[0]<=CX.pw&&o.p[1]<=CX.ph).slice(0,40);CX.verUntil=Date.now()+15000;
  toast("Chart lined up"+(sh?" and shared with Polaris pilots":""));cxViewUi();cxLayers();cxLoop()}
document.addEventListener("click",e=>{const t=e.target;
  const pk=t.closest("[data-cxpick]");if(pk){cxPickChoose(pk.dataset.cxpick);return}
  if(t.closest("[data-cxpickx]")){CX.pick=null;cxPickClose();return}
  const b=t.closest("[data-cx]");if(!b)return;const a=b.dataset.cx;
  if(a==="tf"){if(CX.tf)cxTfStop();else cxTfStart()}
  else if(a==="tfx")cxTfStop();
  else if(a==="tfok"){CX.tfDone=null;CX.verUntil=0;cxViewUi();cxLayers()}
  else if(a==="tfmap2"&&CV.sel){CX.tfDone=null;const s=CV.sel;cvClose();const go=()=>{if(!(OV.sel&&OV.sel.pdf===s.pdf))ovOpen({name:s.name,pdf:s.pdf,group:s.group},s.icao,s.cycle);else{ovUi();ovSched();try{ovFly()}catch(x){}}};if(cur!=="map"){location.hash="map";setTimeout(go,400)}else go()}
  else if(a==="pen"){CX.pen=!CX.pen;if(CX.pen&&CX.tf)cxTfStop();CX.cur=null;cxViewUi()}
  else if(a==="split"){CX.split=!cxSplitOn();store.set("cvSplit",CX.split);cxSplitApply(true)}
  else if(a==="tfmap"&&OV.sel){const s=OV.sel;OV.edit=false;try{ovUi();ovSched()}catch(x){}CX.tfFromMap=true;CX.tfWant={page:OV.page};cvOpen({name:s.name,pdf:s.pdf,group:s.group},s.icao,s.cycle)}});
document.addEventListener("input",e=>{if(e.target&&e.target.id==="cxPickQ"){const v=e.target.value;cxPickUi(v);const i=document.getElementById("cxPickQ");if(i){i.focus();try{i.setSelectionRange(i.value.length,i.value.length)}catch(x){}}}});
document.addEventListener("keydown",e=>{if(e.target&&e.target.id==="cxPickQ"&&e.key==="Enter"){e.preventDefault();const f=document.querySelector("#cxPick [data-cxpick]");if(f)cxPickChoose(f.dataset.cxpick)}
  else if(e.key==="Escape"&&document.getElementById("cxPick")){e.stopImmediatePropagation();CX.pick=null;cxPickClose()}},true);
/* the Map's Adjust bar: line the chart up on two fixes in the full-screen viewer */
{const _ou=ovUi;ovUi=function(){const v=_ou.apply(this,arguments);try{const bar=$("#ovBar");if(bar&&OV.edit&&OV.img&&OV.autoKind!=="pdf"){const row=bar.querySelector(".ov-row");if(row&&!row.querySelector('[data-cx="tfmap"]')){const d=row.querySelector('[data-ov="edit"]');d.insertAdjacentHTML("beforebegin",'<button class="btn sm" data-cx="tfmap" title="Tap two fixes on the full-screen chart">Two fixes</button>')}}}catch(e){}return v}}

