/* ---------- 9. AIP Taiwan: which chart is which procedure ----------
   AIP Taiwan names its charts in many ways: "KUDOS 1A1C RNAV DEP", "CHALI-1A1C1B1D DEP", "BAKER 1A1B / DRAKE 1A1B RNAV
   ARR", "MKG 1U and TNN 1X ARR", "MA1R and SA1R ARR", "POLKA1 RNAV ARR", "PETRA ONE ARRIVAL (PT1)", or with no
   designator at all ("DEP-KUDOS PIANO", "STAR-HLG F H", "TNN C D DEP"). The simulator's names are the coded ones
   (KUDO1A, TNN1A). Designators are read off the name; a chart without them matches by its fix names and letters. */
const CX_TW_STOP=new Set(["DEP","ARR","SID","STAR","RNAV","RNP","RADAR","DEPARTURE","ARRIVAL","AND","RWY","WP","TABLE","ONE","TWO","THREE","FOUR","FIVE","SIX","SEVEN","EIGHT","NINE","ALPHA","BRAVO","CHARLIE","DELTA","ECHO","FOXTROT","KW","V1"]);
function cxTwParse(name){const u=String(name||"").toUpperCase(),codes=[],words=[],letters=[];
  for(const m of u.matchAll(/\(([A-Z]{1,5}\d[A-Z]?)\)/g))codes.push(m[1]);
  const t=u.replace(/\([^)]*\)/g," ").split(/[\s\/_,\-]+/).filter(Boolean);
  for(let i=0;i<t.length;i++){const w=t[i];if(CX_TW_STOP.has(w))continue;
    if(/^[A-Z]{2,5}\d[A-Z]?$/.test(w)){codes.push(w);continue}
    if(/^[A-Z]{3,8}$/.test(w)){const nx=t[i+1];if(nx&&/^(\d[A-Z])+$/.test(nx)){const b=w.length>4?w.slice(0,4):w;nx.match(/\d[A-Z]/g).forEach(x=>codes.push(b+x));i++}else words.push(w);continue}
    if(/^[A-Z]$/.test(w))letters.push(w)}
  return{codes:[...new Set(codes)],words,letters}}
function cxTwScore(name,code){const P=cxTwParse(name),c=String(code||"").toUpperCase();if(!c)return 0;if(P.codes.includes(c))return 10;if(P.codes.length)return 0;
  const m=c.match(/^([A-Z]{2,5})(\d)([A-Z]?)$/);if(!m)return 0;const b=m[1];
  if(!P.words.some(w=>w===b||(w.length>4?w.slice(0,4):w)===b||(b.length>=4&&w.startsWith(b))))return 0;
  return P.letters.length?(m[3]&&P.letters.includes(m[3])?3:0):2}
/* the chart for a SID or STAR the simulator names: FAA by its computer code, AIP Taiwan by the rules above */
function cxProcChart(icao,kind,code){const d=CH.data[icao];if(!d||!Array.isArray(d.charts)||!code)return null;
  if(d.src!=="tw"){const L=rpList(icao,kind),p=L&&L.find(q=>q.code===code);return p?p.c:null}
  const g=kind==="sid"?"Departures":"Arrivals";let best=null,bs=0;for(const c of d.charts){if(c.group!==g)continue;const v=cxTwScore(c.name,code);if(v>bs){bs=v;best=c}}return best}
/* the route editor's own list: the procedures an AIP Taiwan chart names with designators */
{const _l=rpList;rpList=function(icao,kind){const d=CH.data[icao];if(!d||d.src!=="tw")return _l.apply(this,arguments);if(!Array.isArray(d.charts))return null;const seen={},out=[];
  d.charts.forEach(c=>{if(c.group!==(kind==="sid"?"Departures":"Arrivals"))return;for(const code of cxTwParse(c.name).codes){if(seen[code])continue;seen[code]=1;out.push({code,name:c.name,c})}});return out.sort((a,b)=>a.code.localeCompare(b.code))}}
/* Set departure, arrival and approach: a Chart button wherever the chart is known, approaches included */
npChart=function(kind,name){try{const ic=npIcao(kind);let c=null;if(kind==="app"){const a=cxApParse(name);c=a.rw?cxApFind(ic,a):null}else c=cxProcChart(ic,kind,name);return c?{code:name,name:c.name,c}:null}catch(e){return null}};

